BUDGET_LOCAL_HOME_TSX = 'import React, { useMemo, useState } from \'react\';\n\nimport {\n  SvgCheveronLeft,\n  SvgCheveronRight,\n  SvgPiggyBank,\n} from \'@actual-app/components/icons/v1\';\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport * as monthUtils from \'@actual-app/core/shared/months\';\nimport { q } from \'@actual-app/core/shared/query\';\nimport type { CategoryEntity } from \'@actual-app/core/types/models\';\n\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useLocale } from \'#hooks/useLocale\';\nimport { useNavigate } from \'#hooks/useNavigate\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\ntype CardDefinition = {\n  label: string;\n  emoji: string;\n  background: string;\n  accent: string;\n  candidates: string[];\n};\n\nconst EXPENSE_CARDS: CardDefinition[] = [\n  {\n    label: \'Food & Drink\',\n    emoji: \'🍽️\',\n    background: \'#FFF2D5\',\n    accent: \'#FFC44D\',\n    candidates: [\'food & drink\', \'food\', \'groceries\', \'dining\', \'restaurants\'],\n  },\n  {\n    label: \'Transport\',\n    emoji: \'🚌\',\n    background: \'#DFECFF\',\n    accent: \'#56A4FF\',\n    candidates: [\'transport\', \'transportation\', \'gas\', \'auto\', \'car\'],\n  },\n  {\n    label: \'Home Bills\',\n    emoji: \'⚡\',\n    background: \'#FFE8D7\',\n    accent: \'#FF9B54\',\n    candidates: [\'home bills\', \'bills\', \'utilities\', \'rent\', \'mortgage\'],\n  },\n  {\n    label: \'Self-Care\',\n    emoji: \'✨\',\n    background: \'#F0E3FF\',\n    accent: \'#AB78E7\',\n    candidates: [\'self-care\', \'self care\', \'personal care\', \'personal\'],\n  },\n  {\n    label: \'Shopping\',\n    emoji: \'🛍️\',\n    background: \'#FFE0E0\',\n    accent: \'#FF5A5F\',\n    candidates: [\'shopping\', \'general\', \'clothing\'],\n  },\n  {\n    label: \'Health\',\n    emoji: \'✚\',\n    background: \'#D9F7F2\',\n    accent: \'#1FC9B0\',\n    candidates: [\'health\', \'medical\', \'pharmacy\'],\n  },\n];\n\nconst INCOME_CARDS: CardDefinition[] = [\n  {\n    label: \'Salary\',\n    emoji: \'💳\',\n    background: \'#D9F8F2\',\n    accent: \'#1FC9B0\',\n    candidates: [\'salary\', \'income\', \'paycheck\', \'pay\'],\n  },\n  {\n    label: \'Freelance\',\n    emoji: \'◇\',\n    background: \'#E8F8F8\',\n    accent: \'#92DDD6\',\n    candidates: [\'freelance\', \'side income\', \'side job\'],\n  },\n  {\n    label: \'Investment\',\n    emoji: \'📈\',\n    background: \'#E7F6DB\',\n    accent: \'#7FD84E\',\n    candidates: [\'investment\', \'investments\', \'dividend\', \'interest\'],\n  },\n];\n\nfunction normalize(value: string) {\n  return value\n    .toLowerCase()\n    .normalize(\'NFD\')\n    .replace(/[\\u0300-\\u036f]/g, \'\')\n    .replace(/[^a-z0-9]+/g, \' \')\n    .trim();\n}\n\nfunction findCategory(\n  categories: CategoryEntity[],\n  candidates: string[],\n  isIncome: boolean,\n) {\n  const normalizedCandidates = candidates.map(normalize);\n  const eligible = categories.filter(\n    category => !category.hidden && Boolean(category.is_income) === isIncome,\n  );\n\n  return eligible.find(category => {\n    const name = normalize(category.name);\n    return normalizedCandidates.some(\n      candidate =>\n        name === candidate ||\n        name.includes(candidate) ||\n        candidate.includes(name),\n    );\n  });\n}\n\nfunction DashboardCard({\n  definition,\n  category,\n  month,\n  amount,\n  onOpen,\n}: {\n  definition: CardDefinition;\n  category?: CategoryEntity;\n  month: string;\n  amount: number;\n  onOpen: () => void;\n}) {\n  const format = useFormat();\n  const value = category?.is_income\n    ? Math.max(0, amount)\n    : Math.max(0, -amount);\n\n  return (\n    <button\n      type="button"\n      onClick={onOpen}\n      aria-label={`${definition.label}: ${format(value, \'financial\')}`}\n      style={{\n        appearance: \'none\',\n        WebkitAppearance: \'none\',\n        WebkitTapHighlightColor: \'transparent\',\n        border: 0,\n        borderRadius: 24,\n        minWidth: 0,\n        minHeight: 154,\n        padding: \'16px 8px 14px\',\n        background: definition.background,\n        boxShadow: \'0 10px 28px rgba(47, 56, 90, 0.08)\',\n        display: \'flex\',\n        flexDirection: \'column\',\n        alignItems: \'center\',\n        justifyContent: \'space-between\',\n        color: \'#15151B\',\n        font: \'inherit\',\n        cursor: \'pointer\',\n      }}\n    >\n      <span\n        style={{\n          minHeight: 34,\n          display: \'flex\',\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          textAlign: \'center\',\n          fontSize: 15,\n          lineHeight: 1.08,\n          fontWeight: 700,\n          letterSpacing: \'-0.01em\',\n        }}\n      >\n        {definition.label}\n      </span>\n\n      <span\n        aria-hidden\n        style={{\n          width: 54,\n          height: 54,\n          borderRadius: 999,\n          display: \'flex\',\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          background: definition.accent,\n          fontSize: 26,\n          color: \'#fff\',\n          boxShadow: \'0 7px 15px rgba(0,0,0,0.06)\',\n        }}\n      >\n        {definition.emoji}\n      </span>\n\n      <span\n        style={{\n          fontSize: 18,\n          lineHeight: 1,\n          fontWeight: 800,\n          letterSpacing: \'-0.02em\',\n        }}\n      >\n        {format(value, \'financial\')}\n      </span>\n    </button>\n  );\n}\n\nexport function BudgetLocalHome() {\n  const navigate = useNavigate();\n  const locale = useLocale();\n  const format = useFormat();\n  const [month, setMonth] = useState(() => monthUtils.currentMonth());\n\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n\n  const transactionQuery = useMemo(\n    () =>\n      q(\'transactions\')\n        .options({ splits: \'all\' })\n        .filter({\n          date: { $transform: \'$month\', $eq: month },\n        })\n        .select(\'*\'),\n    [month],\n  );\n\n  const { transactions, isPending } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const categoryById = useMemo(\n    () => new Map(categories.map(category => [category.id, category])),\n    [categories],\n  );\n\n  const totals = useMemo(() => {\n    const byCategory = new Map<string, number>();\n    let expenses = 0;\n    let income = 0;\n\n    for (const transaction of transactions) {\n      if (\n        transaction.is_parent ||\n        transaction.tombstone ||\n        transaction.starting_balance_flag ||\n        !transaction.category\n      ) {\n        continue;\n      }\n\n      const category = categoryById.get(transaction.category);\n      if (!category || category.hidden) {\n        continue;\n      }\n\n      byCategory.set(\n        category.id,\n        (byCategory.get(category.id) ?? 0) + transaction.amount,\n      );\n\n      if (category.is_income) {\n        income += transaction.amount;\n      } else {\n        expenses += -transaction.amount;\n      }\n    }\n\n    return {\n      byCategory,\n      expenses: Math.max(0, expenses),\n      income: Math.max(0, income),\n    };\n  }, [categoryById, transactions]);\n\n  const currentMonth = monthUtils.currentMonth();\n  const monthLabel =\n    month === currentMonth\n      ? \'This Month\'\n      : monthUtils.format(month, "MMMM \'\'yy", locale);\n\n  const openCard = (category?: CategoryEntity) => {\n    if (category) {\n      void navigate(`/categories/${category.id}?month=${month}`);\n    } else {\n      void navigate(\'/budget\');\n    }\n  };\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        backgroundColor: \'#FFFFFF\',\n        color: \'#15151B\',\n        padding: \'calc(env(safe-area-inset-top) + 18px) 18px 132px\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          gap: 18,\n        }}\n      >\n        <View\n          style={{\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            justifyContent: \'space-between\',\n            minHeight: 44,\n          }}\n        >\n          <Text\n            style={{\n              color: \'#4D4B91\',\n              fontSize: 15,\n              fontWeight: 700,\n            }}\n          >\n            Monthly ▾\n          </Text>\n\n          <View\n            style={{\n              flexDirection: \'row\',\n              alignItems: \'center\',\n              gap: 12,\n            }}\n          >\n            <button\n              type="button"\n              aria-label="Previous month"\n              onClick={() => setMonth(value => monthUtils.subMonths(value, 1))}\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronLeft width={20} height={20} />\n            </button>\n\n            <Text\n              style={{\n                fontSize: 20,\n                fontWeight: 800,\n                minWidth: 116,\n                textAlign: \'center\',\n                color: \'#111116\',\n              }}\n            >\n              {monthLabel}\n            </Text>\n\n            <button\n              type="button"\n              aria-label="Next month"\n              onClick={() => setMonth(value => monthUtils.addMonths(value, 1))}\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronRight width={20} height={20} />\n            </button>\n          </View>\n\n          <button\n            type="button"\n            aria-label="Accounts"\n            onClick={() => void navigate(\'/accounts\')}\n            style={{\n              border: 0,\n              background: \'transparent\',\n              color: \'#4D4B91\',\n              padding: 4,\n            }}\n          >\n            <SvgPiggyBank width={30} height={30} />\n          </button>\n        </View>\n\n        <View style={{ alignItems: \'center\', gap: 3 }}>\n          <Text style={{ fontSize: 20, fontWeight: 800 }}>\n            Expense {isPending ? \'…\' : format(totals.expenses, \'financial\')}\n          </Text>\n        </View>\n\n        <div\n          style={{\n            display: \'grid\',\n            gridTemplateColumns: \'repeat(3, minmax(0, 1fr))\',\n            gap: 12,\n            width: \'100%\',\n          }}\n        >\n          {EXPENSE_CARDS.map(definition => {\n            const category = findCategory(\n              categories,\n              definition.candidates,\n              false,\n            );\n            return (\n              <DashboardCard\n                key={definition.label}\n                definition={definition}\n                category={category}\n                month={month}\n                amount={\n                  category ? (totals.byCategory.get(category.id) ?? 0) : 0\n                }\n                onOpen={() => openCard(category)}\n              />\n            );\n          })}\n        </div>\n\n        <View style={{ alignItems: \'center\', marginTop: 12, gap: 3 }}>\n          <Text style={{ fontSize: 20, fontWeight: 800 }}>\n            Income {isPending ? \'…\' : format(totals.income, \'financial\')}\n          </Text>\n        </View>\n\n        <div\n          style={{\n            display: \'grid\',\n            gridTemplateColumns: \'repeat(3, minmax(0, 1fr))\',\n            gap: 12,\n            width: \'100%\',\n          }}\n        >\n          {INCOME_CARDS.map(definition => {\n            const category = findCategory(\n              categories,\n              definition.candidates,\n              true,\n            );\n            return (\n              <DashboardCard\n                key={definition.label}\n                definition={definition}\n                category={category}\n                month={month}\n                amount={\n                  category ? (totals.byCategory.get(category.id) ?? 0) : 0\n                }\n                onOpen={() => openCard(category)}\n              />\n            );\n          })}\n        </div>\n\n        <View style={{ alignItems: \'center\', marginTop: 20 }}>\n          <button\n            type="button"\n            onClick={() => void navigate(\'/smart-add\')}\n            style={{\n              border: \'1px solid #EEEAF9\',\n              borderRadius: 999,\n              background: \'#FFFFFF\',\n              boxShadow: \'0 8px 24px rgba(72, 69, 143, 0.10)\',\n              color: \'#4D4B91\',\n              padding: \'10px 18px\',\n              fontSize: 15,\n              fontWeight: 800,\n            }}\n          >\n            ✦ Smart Add\n          </button>\n        </View>\n      </View>\n    </View>\n  );\n}\n'
MOBILE_NAV_V2_TSX = 'import React from \'react\';\nimport type { ComponentType, CSSProperties } from \'react\';\nimport { NavLink, useLocation } from \'react-router\';\n\nimport { useResponsive } from \'@actual-app/components/hooks/useResponsive\';\nimport {\n  SvgCog,\n  SvgHome,\n  SvgList,\n  SvgPiggyBank,\n  SvgWallet,\n} from \'@actual-app/components/icons/v1\';\n\nexport const MOBILE_NAV_HEIGHT = 92;\n\ntype NavIconProps = {\n  width: number;\n  height: number;\n  style?: CSSProperties;\n};\n\ntype NavItem = {\n  name: string;\n  path: string;\n  Icon: ComponentType<NavIconProps>;\n  end?: boolean;\n};\n\nconst items: NavItem[] = [\n  { name: \'Home\', path: \'/home\', Icon: SvgHome, end: true },\n  { name: \'Account\', path: \'/accounts\', Icon: SvgPiggyBank, end: true },\n  { name: \'Transactions\', path: \'/accounts/all\', Icon: SvgList, end: true },\n  { name: \'Budget\', path: \'/budget\', Icon: SvgWallet, end: true },\n  { name: \'Setting\', path: \'/settings\', Icon: SvgCog, end: true },\n];\n\nexport function MobileNavTabs() {\n  const { isNarrowWidth } = useResponsive();\n  const location = useLocation();\n\n  if (!isNarrowWidth) {\n    return null;\n  }\n\n  const showSmartAdd =\n    location.pathname !== \'/smart-add\' &&\n    location.pathname !== \'/budget\';\n\n  return (\n    <>\n      {showSmartAdd && (\n        <NavLink\n          to="/smart-add"\n          aria-label="Smart Add"\n          style={{\n            position: \'fixed\',\n            zIndex: 1001,\n            left: \'50%\',\n            transform: \'translateX(-50%)\',\n            bottom: \'calc(97px + env(safe-area-inset-bottom))\',\n            textDecoration: \'none\',\n            WebkitTapHighlightColor: \'transparent\',\n          }}\n        >\n          <span\n            style={{\n              display: \'flex\',\n              alignItems: \'center\',\n              justifyContent: \'center\',\n              gap: 7,\n              minHeight: 44,\n              padding: \'0 17px\',\n              borderRadius: 999,\n              background: \'#4D4B91\',\n              color: \'#FFFFFF\',\n              boxShadow: \'0 10px 28px rgba(52, 49, 112, 0.28)\',\n              fontSize: 13,\n              fontWeight: 850,\n            }}\n          >\n            ✦ Smart Add\n          </span>\n        </NavLink>\n      )}\n\n      <nav\n      aria-label="Main navigation"\n      style={{\n        position: \'fixed\',\n        zIndex: 1000,\n        left: 10,\n        right: 10,\n        bottom: \'calc(8px + env(safe-area-inset-bottom))\',\n        height: 78,\n        display: \'grid\',\n        gridTemplateColumns: \'repeat(5, minmax(0, 1fr))\',\n        alignItems: \'stretch\',\n        padding: \'7px 6px 6px\',\n        borderRadius: 30,\n        border: \'1px solid rgba(36, 38, 55, 0.12)\',\n        background: \'rgba(255, 255, 255, 0.96)\',\n        boxShadow: \'0 12px 34px rgba(42, 47, 74, 0.12)\',\n        backdropFilter: \'blur(18px)\',\n        WebkitBackdropFilter: \'blur(18px)\',\n      }}\n    >\n      {items.map(({ name, path, Icon, end }) => (\n        <NavLink\n          key={path}\n          to={path}\n          end={end}\n          style={{\n            textDecoration: \'none\',\n            WebkitTapHighlightColor: \'transparent\',\n            minWidth: 0,\n          }}\n        >\n          {({ isActive }) => (\n            <span\n              style={{\n                height: \'100%\',\n                display: \'flex\',\n                flexDirection: \'column\',\n                alignItems: \'center\',\n                justifyContent: \'center\',\n                gap: 4,\n                color: isActive ? \'#47458F\' : \'#8E929D\',\n                fontSize: 9.5,\n                fontWeight: isActive ? 800 : 650,\n                lineHeight: 1,\n                whiteSpace: \'nowrap\',\n              }}\n            >\n              <span\n                style={{\n                  width: 34,\n                  height: 31,\n                  borderRadius: 10,\n                  display: \'flex\',\n                  alignItems: \'center\',\n                  justifyContent: \'center\',\n                  background: isActive ? \'#FFD84F\' : \'transparent\',\n                  transition: \'background 140ms ease\',\n                }}\n              >\n                <Icon width={21} height={21} />\n              </span>\n              {name}\n            </span>\n          )}\n        </NavLink>\n      ))}\n      </nav>\n    </>\n  );\n}\n'
WELCOME_SCREEN_V2_TSX = 'import React from \'react\';\n\nimport { Button } from \'@actual-app/components/button\';\nimport { useResponsive } from \'@actual-app/components/hooks/useResponsive\';\nimport { SvgPiggyBank } from \'@actual-app/components/icons/v1\';\nimport { styles } from \'@actual-app/components/styles\';\nimport { Text } from \'@actual-app/components/text\';\nimport { theme } from \'@actual-app/components/theme\';\nimport { View } from \'@actual-app/components/view\';\n\nimport { createBudget } from \'#budgetfiles/budgetfilesSlice\';\nimport { pushModal } from \'#modals/modalsSlice\';\nimport { useDispatch } from \'#redux\';\n\nexport function WelcomeScreen() {\n  const dispatch = useDispatch();\n  const { isNarrowWidth } = useResponsive();\n\n  const buttonStyle = {\n    fontSize: 15,\n    padding: \'13px 18px\',\n    flexShrink: 0,\n    ...(isNarrowWidth && { minHeight: styles.mobileMinHeight }),\n  };\n\n  return (\n    <View\n      style={{\n        alignItems: \'center\',\n        justifyContent: \'center\',\n        width: \'100%\',\n        maxWidth: 460,\n        minHeight: \'100%\',\n        padding: \'calc(env(safe-area-inset-top) + 30px) 24px calc(env(safe-area-inset-bottom) + 30px)\',\n        gap: 22,\n      }}\n    >\n      <View\n        style={{\n          width: 78,\n          height: 78,\n          borderRadius: 26,\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          backgroundColor: \'#FFF0C6\',\n          boxShadow: \'0 12px 30px rgba(62, 56, 130, 0.12)\',\n        }}\n      >\n        <SvgPiggyBank width={44} height={44} style={{ color: \'#4D4B91\' }} />\n      </View>\n\n      <View style={{ alignItems: \'center\', gap: 8 }}>\n        <Text\n          style={{\n            fontSize: 32,\n            lineHeight: 1.05,\n            fontWeight: 800,\n            textAlign: \'center\',\n            color: theme.pageText,\n          }}\n        >\n          Welcome to Budget Local\n        </Text>\n        <Text\n          style={{\n            color: theme.pageTextLight,\n            fontSize: 15,\n            lineHeight: 1.45,\n            textAlign: \'center\',\n            maxWidth: 360,\n          }}\n        >\n          Private, local-first budgeting with Smart Add and receipt scanning.\n          Your budget stays on this device unless you export it yourself.\n        </Text>\n      </View>\n\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 380,\n          gap: 11,\n          marginTop: 8,\n        }}\n      >\n        <Button\n          variant="primary"\n          autoFocus={!isNarrowWidth}\n          style={{\n            ...buttonStyle,\n            borderRadius: 16,\n          }}\n          onPress={() => dispatch(createBudget({}))}\n        >\n          Start budgeting\n        </Button>\n\n        <Button\n          style={{\n            ...buttonStyle,\n            borderRadius: 16,\n          }}\n          onPress={() => dispatch(pushModal({ modal: { name: \'import\' } }))}\n        >\n          Import existing budget\n        </Button>\n      </View>\n\n      <Text\n        style={{\n          color: theme.pageTextSubdued,\n          textAlign: \'center\',\n          fontSize: 12,\n          lineHeight: 1.4,\n          maxWidth: 340,\n        }}\n      >\n        No OpenAI, Firebase, Supabase, bank-sync subscription, or voice service\n        is required for the local Budget Local workflow.\n      </Text>\n    </View>\n  );\n}\n'

SMART_ADD_TSX = 'import React, { useCallback, useMemo, useRef, useState } from \'react\';\n\nimport { Button } from \'@actual-app/components/button\';\nimport { Text } from \'@actual-app/components/text\';\nimport { theme } from \'@actual-app/components/theme\';\nimport { View } from \'@actual-app/components/view\';\n\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useNavigate } from \'#hooks/useNavigate\';\n\nimport {\n  buildBudgetAiContext,\n  clearLocalBudgetAiCache,\n  loadLocalBudgetAi,\n  LOCAL_AI_APPROX_DOWNLOAD,\n  LOCAL_AI_MODEL_LABEL,\n  localAiWasInstalled,\n  localAiWebGpuAvailable,\n  localModelFileInfo,\n  localModelFileSelected,\n  releaseLocalModelFile,\n  rememberBudgetAiChoice,\n  selectLocalModelFile,\n  runLocalBudgetAi,\n  type AiProgress,\n} from \'./localBudgetAI\';\nimport { MobileBackButton } from \'./MobileBackButton\';\nimport { MobilePageHeader, Page } from \'../Page\';\nimport {\n  parseReceiptText,\n  parseSmartText,\n  toActualTransactionQuery,\n  type SmartDraft,\n} from \'./smartAddParser\';\n\ntype OcrLog = {\n  status?: string;\n  progress?: number;\n};\n\ntype OcrWorker = {\n  recognize: (image: File | Blob) => Promise<{ data: { text: string } }>;\n  terminate: () => Promise<unknown>;\n};\n\ntype TesseractBrowserApi = {\n  createWorker: (\n    langs?: string | string[],\n    oem?: number,\n    options?: {\n      workerPath?: string;\n      corePath?: string;\n      langPath?: string;\n      workerBlobURL?: boolean;\n      logger?: (message: OcrLog) => void;\n    },\n  ) => Promise<OcrWorker>;\n};\n\ndeclare global {\n  interface Window {\n    Tesseract?: TesseractBrowserApi;\n  }\n}\n\nlet tesseractLoader: Promise<TesseractBrowserApi> | null = null;\n\nfunction loadTesseract(): Promise<TesseractBrowserApi> {\n  if (window.Tesseract) return Promise.resolve(window.Tesseract);\n  if (tesseractLoader) return tesseractLoader;\n\n  tesseractLoader = new Promise((resolve, reject) => {\n    const previous = document.querySelector<HTMLScriptElement>(\n      \'script[data-budget-local-ocr="tesseract"]\',\n    );\n    if (previous) {\n      previous.addEventListener(\'load\', () => {\n        if (window.Tesseract) resolve(window.Tesseract);\n        else reject(new Error(\'No se pudo iniciar el OCR local.\'));\n      });\n      previous.addEventListener(\'error\', () =>\n        reject(new Error(\'No se pudo cargar el OCR local.\')),\n      );\n      return;\n    }\n\n    const script = document.createElement(\'script\');\n    script.src = \'/ocr/tesseract.min.js\';\n    script.async = true;\n    script.dataset.budgetLocalOcr = \'tesseract\';\n    script.onload = () => {\n      if (window.Tesseract) resolve(window.Tesseract);\n      else reject(new Error(\'No se pudo iniciar el OCR local.\'));\n    };\n    script.onerror = () => reject(new Error(\'No se pudo cargar el OCR local.\'));\n    document.head.appendChild(script);\n  });\n\n  return tesseractLoader;\n}\n\nfunction progressPercent(progress: AiProgress | null) {\n  if (!progress || typeof progress.progress !== \'number\') return undefined;\n  return Math.round(Math.max(0, Math.min(1, progress.progress)) * 100);\n}\n\nfunction Field({ label, value }: { label: string; value?: string }) {\n  return (\n    <View\n      style={{\n        flex: 1,\n        minWidth: 130,\n        padding: 12,\n        borderRadius: 14,\n        backgroundColor: theme.tableBackground,\n        border: `1px solid ${theme.tableBorder}`,\n      }}\n    >\n      <Text style={{ fontSize: 11, color: theme.pageTextSubdued }}>{label}</Text>\n      <Text style={{ fontSize: 15, fontWeight: 600, marginTop: 3 }}>\n        {value || \'—\'}\n      </Text>\n    </View>\n  );\n}\n\nexport function SmartAdd() {\n  const navigate = useNavigate();\n  const fileInputRef = useRef<HTMLInputElement | null>(null);\n  const modelFileInputRef = useRef<HTMLInputElement | null>(null);\n  const { data: categoryData } = useCategories();\n\n  const categories = useMemo(\n    () =>\n      (categoryData?.list ?? [])\n        .filter(category => !category.hidden)\n        .map(category => category.name),\n    [categoryData?.list],\n  );\n\n  const aiContext = useMemo(\n    () => buildBudgetAiContext(categories),\n    [categories],\n  );\n\n  const [text, setText] = useState(\'\');\n  const [draft, setDraft] = useState<SmartDraft | null>(null);\n  const [ocrProgress, setOcrProgress] = useState<number | null>(null);\n  const [ocrStatus, setOcrStatus] = useState(\'\');\n  const [error, setError] = useState(\'\');\n\n  const [aiState, setAiState] = useState<\n    \'off\' | \'cached\' | \'loading\' | \'ready\' | \'running\' | \'error\'\n  >(() => (localAiWasInstalled() ? \'cached\' : \'off\'));\n  const [aiProgress, setAiProgress] = useState<AiProgress | null>(null);\n  const [aiMessage, setAiMessage] = useState(\'\');\n  const [remembered, setRemembered] = useState(false);\n  const [modelFile, setModelFile] = useState(() => localModelFileInfo());\n\n  const webGpuAvailable = localAiWebGpuAvailable();\n  const aiPercent = progressPercent(aiProgress);\n  const reviewEnabled = Boolean(draft?.amount);\n\n  const confidenceLabel = useMemo(() => {\n    if (draft?.confidence == null) return undefined;\n    return `${Math.round(draft.confidence * 100)}%`;\n  }, [draft?.confidence]);\n\n  const updateAiProgress = useCallback((progress: AiProgress) => {\n    setAiProgress(progress);\n    if (progress.status === \'ready\') {\n      setAiState(\'ready\');\n      setAiMessage(\'SmolLM2 135M listo en este dispositivo.\');\n      return;\n    }\n\n    const stageLabels: Record<string, string> = {\n      \'webgpu-check\': \'Comprobando WebGPU…\',\n      \'runtime-check\': \'Comprobando Transformers.js…\',\n      \'ort-module-check\': \'Comprobando ONNX WebGPU…\',\n      \'ort-wasm-check\': \'Comprobando motor WASM…\',\n      \'model-file-check\': \'Comprobando modelo de iPhone Files…\',\n      \'runtime-ready\': \'Motor de IA listo…\',\n      \'model-download\': \'Cargando SmolLM2 135M desde Files…\',\n      classifying: \'AI clasificando categoría y subcategoría…\',\n    };\n\n    const file = progress.file || progress.name;\n    const pct =\n      typeof progress.progress === \'number\'\n        ? ` ${Math.round(progress.progress * 100)}%`\n        : \'\';\n\n    setAiMessage(\n      stageLabels[progress.status || \'\'] ||\n        (file\n          ? `Descargando ${file}${pct}`\n          : progress.status\n            ? `${progress.status}${pct}`\n            : `Preparando IA local${pct}`),\n    );\n  }, []);\n\n  const enableAi = useCallback(async () => {\n    setError(\'\');\n    if (!localModelFileSelected()) {\n      setError(\n        \'Primero selecciona model_q4f16.onnx desde la app Files del iPhone.\',\n      );\n      return;\n    }\n    setAiState(\'loading\');\n    setAiMessage(\'Preparando SmolLM2 135M local…\');\n    try {\n      await loadLocalBudgetAi(updateAiProgress);\n      setAiState(\'ready\');\n      setAiMessage(\'SmolLM2 135M listo. Tus textos se procesan localmente.\');\n    } catch (err) {\n      setAiState(\'error\');\n      setAiMessage(\'\');\n      setError(\n        err instanceof Error ? err.message : \'No se pudo iniciar la IA local.\',\n      );\n    }\n  }, [updateAiProgress]);\n\n  const chooseModelFile = useCallback((file: File) => {\n    setError(\'\');\n    setAiMessage(\'\');\n    try {\n      const info = selectLocalModelFile(file);\n      setModelFile(info);\n      setAiState(\'off\');\n      setAiProgress(null);\n      setAiMessage(\n        `Modelo seleccionado desde Files: ${info.name} (${Math.round(\n          info.size / 1_000_000,\n        )} MB).`,\n      );\n    } catch (err) {\n      setModelFile(null);\n      releaseLocalModelFile();\n      setAiState(\'error\');\n      setError(\n        err instanceof Error ? err.message : \'No pude usar ese archivo de modelo.\',\n      );\n    }\n  }, []);\n\n  const parseTypedText = useCallback(() => {\n    setError(\'\');\n    setRemembered(false);\n    const parsed = parseSmartText(text);\n    setDraft(parsed);\n    if (!parsed.amount) {\n      setError(\n        \'No encontré una cantidad. Escribe algo como: Walmart 84.72 groceries.\',\n      );\n    }\n  }, [text]);\n\n  const parseWithAi = useCallback(async () => {\n    if (!text.trim()) {\n      setError(\'Escribe primero el gasto o ingreso.\');\n      return;\n    }\n\n    setError(\'\');\n    setRemembered(false);\n    setAiState(\'running\');\n    setAiMessage(\n      localAiWasInstalled()\n        ? \'Analizando con SmolLM2 135M local…\'\n        : \'Preparando SmolLM2 135M desde Files…\',\n    );\n\n    try {\n      const parsed = await runLocalBudgetAi(\n        text,\n        aiContext,\n        updateAiProgress,\n      );\n      setDraft(parsed);\n      setAiState(\'ready\');\n      setAiMessage(\'Interpretado con SmolLM2 135M local.\');\n      if (!parsed.amount) {\n        setError(\n          \'La IA no encontró una cantidad segura. Puedes corregir con entrada manual.\',\n        );\n      }\n    } catch (err) {\n      // Deterministic fallback: Smart Add never becomes unusable because AI failed.\n      const fallback = parseSmartText(text);\n      setDraft(fallback);\n      setAiState(\'error\');\n      setAiMessage(\'\');\n      setError(\n        `${\n          err instanceof Error ? err.message : \'La IA local no pudo completar la lectura.\'\n        } Usé el parser local normal como respaldo.`,\n      );\n    }\n  }, [aiContext, text, updateAiProgress]);\n\n  const openForReview = useCallback(() => {\n    if (!draft) return;\n    const query = toActualTransactionQuery(draft);\n    void navigate(`/smart-review/new${query ? `?${query}` : \'\'}`);\n  }, [draft, navigate]);\n\n  const scanReceipt = useCallback(\n    async (file: File) => {\n      setError(\'\');\n      setRemembered(false);\n      setDraft(null);\n      setOcrProgress(0);\n      setOcrStatus(\'Preparando OCR local…\');\n\n      let worker: OcrWorker | null = null;\n      try {\n        const api = await loadTesseract();\n        worker = await api.createWorker(\'eng\', 1, {\n          workerPath: \'/ocr/worker.min.js\',\n          corePath: \'/ocr/core\',\n          langPath: \'/ocr/lang\',\n          workerBlobURL: false,\n          logger: message => {\n            if (typeof message.progress === \'number\') {\n              setOcrProgress(Math.max(0, Math.min(1, message.progress)));\n            }\n            if (message.status) setOcrStatus(message.status);\n          },\n        });\n\n        setOcrStatus(\'Leyendo recibo…\');\n        const result = await worker.recognize(file);\n        let parsed = parseReceiptText(result.data.text);\n\n        if (aiState === \'ready\') {\n          setAiState(\'running\');\n          setAiMessage(\'SmolLM2 135M está organizando el recibo…\');\n          try {\n            parsed = await runLocalBudgetAi(\n              result.data.text,\n              aiContext,\n              updateAiProgress,\n            );\n            setAiState(\'ready\');\n            setAiMessage(\'Recibo interpretado con SmolLM2 135M local.\');\n          } catch {\n            setAiState(\'ready\');\n            setAiMessage(\n              \'OCR listo. La IA no mejoró esta lectura; mantuve el resultado local.\',\n            );\n          }\n        }\n\n        setDraft(parsed);\n        setOcrProgress(1);\n        setOcrStatus(\'Listo\');\n        if (!parsed.amount) {\n          setError(\n            \'Leí el recibo, pero no pude identificar el total. Puedes usar entrada manual.\',\n          );\n        }\n      } catch (err) {\n        setError(\n          err instanceof Error ? err.message : \'No se pudo leer el recibo.\',\n        );\n        setOcrProgress(null);\n        setOcrStatus(\'\');\n      } finally {\n        if (worker) await worker.terminate();\n      }\n    },\n    [aiContext, aiState, updateAiProgress],\n  );\n\n  const rememberMerchant = useCallback(() => {\n    if (!draft) return;\n    if (rememberBudgetAiChoice(draft)) {\n      setRemembered(true);\n      setAiMessage(\n        `${draft.payee} quedó aprendido localmente para futuras sugerencias.`,\n      );\n    }\n  }, [draft]);\n\n  const removeAi = useCallback(async () => {\n    setError(\'\');\n    try {\n      await clearLocalBudgetAiCache();\n      setAiState(\'off\');\n      setAiProgress(null);\n      setAiMessage(\n        \'Cache de IA eliminado. Tus presupuestos y transacciones no fueron tocados.\',\n      );\n    } catch (err) {\n      setError(\n        err instanceof Error ? err.message : \'No se pudo limpiar la cache de IA.\',\n      );\n    }\n  }, []);\n\n  return (\n    <Page\n      header={\n        <MobilePageHeader\n          title="Smart Add"\n          leftContent={<MobileBackButton />}\n        />\n      }\n      padding={0}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          padding: 16,\n          paddingBottom: 120,\n          gap: 16,\n        }}\n      >\n        <View\n          style={{\n            padding: 16,\n            borderRadius: 20,\n            backgroundColor: \'#F5F2FF\',\n            border: \'1px solid #E4DDFB\',\n          }}\n        >\n          <View\n            style={{\n              flexDirection: \'row\',\n              justifyContent: \'space-between\',\n              alignItems: \'center\',\n              gap: 12,\n            }}\n          >\n            <View style={{ flex: 1 }}>\n              <Text style={{ fontSize: 17, fontWeight: 800 }}>\n                🤖 Local AI\n              </Text>\n              <Text\n                style={{\n                  marginTop: 3,\n                  color: theme.pageTextSubdued,\n                  lineHeight: 1.4,\n                }}\n              >\n                {LOCAL_AI_MODEL_LABEL} · {LOCAL_AI_APPROX_DOWNLOAD}\n              </Text>\n            </View>\n            <Text\n              style={{\n                fontSize: 12,\n                fontWeight: 800,\n                color:\n                  aiState === \'ready\'\n                    ? \'#23844A\'\n                    : aiState === \'error\'\n                      ? theme.errorText\n                      : \'#6D61A8\',\n              }}\n            >\n              {aiState === \'ready\'\n                ? \'READY\'\n                : aiState === \'cached\'\n                  ? \'CACHED\'\n                  : aiState === \'loading\' || aiState === \'running\'\n                    ? \'WORKING\'\n                    : aiState === \'error\'\n                      ? \'CHECK\'\n                      : \'OFF\'}\n            </Text>\n          </View>\n\n          <Text\n            style={{\n              marginTop: 8,\n              color: theme.pageTextSubdued,\n              lineHeight: 1.45,\n              fontSize: 12,\n            }}\n          >\n            El modelo grande se lee directamente desde un archivo que tú eliges\n            en iPhone Files. No se vuelve a descargar ni se copia a la cache de\n            Safari. Los archivos pequeños del tokenizer/config siguen usando el\n            Worker privado de Budget Local.\n          </Text>\n\n          {!webGpuAvailable && (\n            <Text style={{ marginTop: 8, color: theme.errorText, fontSize: 12 }}>\n              WebGPU no está disponible aquí. Smart Add y OCR normal siguen funcionando.\n            </Text>\n          )}\n\n          {(aiState === \'loading\' || aiState === \'running\') && (\n            <View style={{ marginTop: 10 }}>\n              <div\n                style={{\n                  height: 8,\n                  borderRadius: 99,\n                  overflow: \'hidden\',\n                  background: \'#DED9EE\',\n                }}\n              >\n                <div\n                  style={{\n                    height: \'100%\',\n                    width: `${aiPercent ?? 8}%`,\n                    minWidth: 8,\n                    background: \'#6D61A8\',\n                    transition: \'width 180ms ease\',\n                  }}\n                />\n              </div>\n            </View>\n          )}\n\n          {aiMessage && (\n            <Text\n              style={{\n                marginTop: 8,\n                color: theme.pageTextSubdued,\n                fontSize: 12,\n              }}\n            >\n              {aiMessage}\n            </Text>\n          )}\n\n          <View\n            style={{\n              marginTop: 12,\n              padding: 12,\n              borderRadius: 14,\n              backgroundColor: \'#FFFFFF\',\n              border: \'1px solid #E2DDF1\',\n            }}\n          >\n            <Text style={{ fontSize: 13, fontWeight: 800 }}>\n              📁 Modelo desde iPhone Files\n            </Text>\n            <Text\n              style={{\n                marginTop: 4,\n                color: theme.pageTextSubdued,\n                fontSize: 12,\n                lineHeight: 1.4,\n              }}\n            >\n              Selecciona model_q4f16.onnx. Budget Local lo usa directamente;\n              no lo copia ni lo vuelve a descargar.\n            </Text>\n\n            {modelFile ? (\n              <Text\n                style={{\n                  marginTop: 8,\n                  color: \'#23844A\',\n                  fontSize: 12,\n                  fontWeight: 800,\n                }}\n              >\n                ✓ {modelFile.name} · {Math.round(modelFile.size / 1_000_000)} MB\n              </Text>\n            ) : (\n              <Text\n                style={{\n                  marginTop: 8,\n                  color: \'#A86600\',\n                  fontSize: 12,\n                  fontWeight: 800,\n                }}\n              >\n                No model file selected\n              </Text>\n            )}\n\n            <View\n              style={{\n                flexDirection: \'row\',\n                flexWrap: \'wrap\',\n                gap: 8,\n                marginTop: 9,\n              }}\n            >\n              <Button\n                variant="normal"\n                onPress={() => modelFileInputRef.current?.click()}\n              >\n                📂 Choose model from Files\n              </Button>\n              {modelFile && (\n                <Button\n                  variant="bare"\n                  onPress={() => {\n                    releaseLocalModelFile();\n                    setModelFile(null);\n                    setAiState(\'off\');\n                    setAiProgress(null);\n                    setAiMessage(\'Modelo liberado de esta sesión.\');\n                  }}\n                >\n                  Release model\n                </Button>\n              )}\n            </View>\n\n            <input\n              ref={modelFileInputRef}\n              type="file"\n              accept=".onnx,application/octet-stream"\n              style={{ display: \'none\' }}\n              onChange={event => {\n                const file = event.target.files?.[0];\n                if (file) chooseModelFile(file);\n                event.currentTarget.value = \'\';\n              }}\n            />\n          </View>\n\n          <View\n            style={{\n              flexDirection: \'row\',\n              flexWrap: \'wrap\',\n              gap: 8,\n              marginTop: 11,\n            }}\n          >\n            {aiState !== \'ready\' && (\n              <Button\n                variant="primary"\n                isDisabled={\n                  !webGpuAvailable ||\n                  !modelFile ||\n                  aiState === \'loading\'\n                }\n                onPress={() => void enableAi()}\n              >\n                {aiState === \'cached\'\n                  ? \'Cargar AI\'\n                  : aiState === \'loading\'\n                    ? \'Descargando…\'\n                    : \'Enable Local AI\'}\n              </Button>\n            )}\n            {(aiState === \'ready\' || aiState === \'cached\') && (\n              <Button variant="bare" onPress={() => void removeAi()}>\n                Quitar modelo local\n              </Button>\n            )}\n          </View>\n        </View>\n\n        <View\n          style={{\n            padding: 18,\n            borderRadius: 20,\n            backgroundColor: theme.tableBackground,\n            border: `1px solid ${theme.tableBorder}`,\n          }}\n        >\n          <Text style={{ fontSize: 21, fontWeight: 700 }}>\n            Agregar gasto rápido\n          </Text>\n          <Text\n            style={{\n              marginTop: 6,\n              color: theme.pageTextSubdued,\n              lineHeight: 1.5,\n            }}\n          >\n            Ejemplo: “Kroger 42.87 groceries con Apple Card hoy”.\n          </Text>\n\n          <textarea\n            aria-label="Entrada inteligente"\n            value={text}\n            onChange={event => setText(event.target.value)}\n            placeholder="Ejemplo: Kroger 42.87 groceries hoy"\n            rows={4}\n            style={{\n              marginTop: 16,\n              width: \'100%\',\n              resize: \'vertical\',\n              borderRadius: 14,\n              border: `1px solid ${theme.formInputBorder}`,\n              background: theme.formInputBackground,\n              color: theme.formInputText,\n              padding: 14,\n              font: \'inherit\',\n              minHeight: 92,\n            }}\n          />\n\n          <View\n            style={{\n              flexDirection: \'row\',\n              flexWrap: \'wrap\',\n              gap: 10,\n              marginTop: 12,\n            }}\n          >\n            <Button\n              variant="primary"\n              isDisabled={aiState === \'loading\' || aiState === \'running\'}\n              onPress={() => void parseWithAi()}\n            >\n              🤖 Interpretar con AI\n            </Button>\n            <Button variant="normal" onPress={parseTypedText}>\n              Interpretar sin AI\n            </Button>\n            <Button\n              variant="normal"\n              onPress={() => fileInputRef.current?.click()}\n            >\n              📷 Escanear recibo\n            </Button>\n            <Button\n              variant="bare"\n              onPress={() => void navigate(\'/smart-review/new\')}\n            >\n              Entrada manual\n            </Button>\n          </View>\n\n          <input\n            ref={fileInputRef}\n            type="file"\n            accept="image/*"\n            capture="environment"\n            style={{ display: \'none\' }}\n            onChange={event => {\n              const file = event.target.files?.[0];\n              if (file) void scanReceipt(file);\n              event.currentTarget.value = \'\';\n            }}\n          />\n\n          {ocrProgress != null && ocrProgress < 1 && (\n            <View style={{ marginTop: 14 }}>\n              <Text style={{ color: theme.pageTextSubdued }}>\n                {ocrStatus || \'Procesando…\'} {Math.round(ocrProgress * 100)}%\n              </Text>\n              <div\n                style={{\n                  height: 8,\n                  marginTop: 7,\n                  borderRadius: 99,\n                  overflow: \'hidden\',\n                  background: theme.tableBorder,\n                }}\n              >\n                <div\n                  style={{\n                    height: \'100%\',\n                    width: `${Math.round(ocrProgress * 100)}%`,\n                    background: theme.buttonPrimaryBackground,\n                    transition: \'width 160ms ease\',\n                  }}\n                />\n              </div>\n            </View>\n          )}\n\n          {error && (\n            <Text style={{ marginTop: 12, color: theme.errorText }}>\n              {error}\n            </Text>\n          )}\n        </View>\n\n        {draft && (\n          <View\n            style={{\n              padding: 18,\n              borderRadius: 20,\n              backgroundColor: theme.tableBackground,\n              border: `1px solid ${theme.tableBorder}`,\n            }}\n          >\n            <View\n              style={{\n                flexDirection: \'row\',\n                justifyContent: \'space-between\',\n                gap: 10,\n              }}\n            >\n              <Text style={{ fontSize: 18, fontWeight: 700 }}>Revisión</Text>\n              {confidenceLabel && (\n                <Text style={{ color: theme.pageTextSubdued }}>\n                  Lectura {confidenceLabel}\n                </Text>\n              )}\n            </View>\n\n            <View\n              style={{\n                flexDirection: \'row\',\n                flexWrap: \'wrap\',\n                gap: 10,\n                marginTop: 14,\n              }}\n            >\n              <Field\n                label="Tipo"\n                value={draft.kind === \'income\' ? \'Ingreso\' : \'Gasto\'}\n              />\n              <Field\n                label="Cantidad"\n                value={\n                  draft.amount != null\n                    ? `$${draft.amount.toFixed(2)}`\n                    : undefined\n                }\n              />\n              <Field label="Comercio" value={draft.payee} />\n              <Field label="Fecha" value={draft.date} />\n              <Field label="Categoría" value={draft.category} />\n              <Field label="Subcategoría" value={draft.subcategory} />\n              <Field label="Cuenta" value={draft.account} />\n            </View>\n\n            <Text\n              style={{\n                marginTop: 12,\n                color: theme.pageTextSubdued,\n                lineHeight: 1.45,\n              }}\n            >\n              Antes de guardar, Actual Budget abrirá su formulario normal para\n              que confirmes o corrijas los datos. La subcategoría se conserva\n              como tag en la nota y sigue descontando del presupuesto de la\n              categoría principal.\n            </Text>\n\n            <View\n              style={{\n                flexDirection: \'row\',\n                flexWrap: \'wrap\',\n                gap: 10,\n                marginTop: 14,\n              }}\n            >\n              <Button\n                variant="primary"\n                isDisabled={!reviewEnabled}\n                onPress={openForReview}\n              >\n                Revisar y guardar\n              </Button>\n\n              {draft.payee && draft.category && (\n                <Button\n                  variant="normal"\n                  isDisabled={remembered}\n                  onPress={rememberMerchant}\n                >\n                  {remembered ? \'✓ Aprendido\' : \'🧠 Recordar comercio\'}\n                </Button>\n              )}\n\n              <Button\n                variant="normal"\n                onPress={() =>\n                  setDraft(current =>\n                    current\n                      ? {\n                          ...current,\n                          kind:\n                            current.kind === \'expense\'\n                              ? \'income\'\n                              : \'expense\',\n                        }\n                      : current,\n                  )\n                }\n              >\n                Cambiar a {draft.kind === \'expense\' ? \'ingreso\' : \'gasto\'}\n              </Button>\n            </View>\n          </View>\n        )}\n\n        <View\n          style={{\n            padding: 16,\n            borderRadius: 18,\n            backgroundColor: theme.noticeBackground,\n          }}\n        >\n          <Text style={{ fontWeight: 700 }}>Privacidad local</Text>\n          <Text\n            style={{\n              marginTop: 5,\n              color: theme.pageTextSubdued,\n              lineHeight: 1.45,\n            }}\n          >\n            IA: SmolLM2 360M Instruct ejecutándose con WebGPU en el navegador. OCR:\n            Tesseract.js local. Sin OpenAI API, Firebase ni Supabase para estas\n            funciones. Solo la descarga inicial del modelo requiere internet.\n          </Text>\n        </View>\n      </View>\n    </Page>\n  );\n}\n'
LOCAL_BUDGET_AI_TS = 'import { parseSmartText, type SmartDraft } from \'./smartAddParser\';\n\nexport const LOCAL_AI_MODEL_ID = \'onnx-community/SmolLM2-135M-Instruct-ONNX\';\nexport const LOCAL_AI_MODEL_LABEL = \'SmolLM2 135M Instruct · WebGPU · q4f16\';\nexport const LOCAL_AI_APPROX_DOWNLOAD = \'≈117 MB + tokenizer/runtime\';\n\nconst RUNTIME_URL = \'/ai/transformers-4.3.0.min.js\';\nconst INSTALL_KEY = \'budget-local-ai-smollm2-135m-v1\';\nconst MERCHANT_MEMORY_KEY = \'budget-local-ai-merchant-memory-v1\';\nconst CUSTOM_SUBCATEGORY_KEY = \'budget-local-subcategories-v1\';\nconst MODEL_FILE_NAME = \'model_q4f16.onnx\';\nconst MODEL_MIN_BYTES = 100_000_000;\nconst MODEL_MAX_BYTES = 140_000_000;\n\nlet selectedModelFile: File | null = null;\n\ntype ChatMessage = {\n  role: \'system\' | \'user\' | \'assistant\';\n  content: string;\n};\n\ntype TextGenerator = (\n  input: string | ChatMessage[],\n  options: Record<string, unknown>,\n) => Promise<unknown>;\n\ntype TransformersModule = {\n  pipeline: (\n    task: string,\n    model: string,\n    options?: Record<string, unknown>,\n  ) => Promise<TextGenerator>;\n  env?: {\n    allowRemoteModels?: boolean;\n    allowLocalModels?: boolean;\n    useBrowserCache?: boolean;\n    useWasmCache?: boolean;\n    useCustomCache?: boolean;\n    customCache?: {\n      match: (request: string) => Promise<Response | undefined>;\n      put: (\n        request: string,\n        response: Response,\n        progressCallback?: (data: {\n          progress: number;\n          loaded: number;\n          total: number;\n        }) => void,\n      ) => Promise<void>;\n    };\n    remoteHost?: string;\n    remotePathTemplate?: string;\n    backends?: {\n      onnx?: {\n        wasm?: {\n          proxy?: boolean;\n          numThreads?: number;\n          wasmPaths?: string | { wasm?: string; mjs?: string };\n        };\n      };\n    };\n  };\n};\n\nexport type AiProgress = {\n  status?: string;\n  progress?: number;\n  loaded?: number;\n  total?: number;\n  file?: string;\n  name?: string;\n};\n\nexport type BudgetAiContext = {\n  categories: string[];\n  subcategories: Record<string, string[]>;\n};\n\ntype MerchantMemory = {\n  payee: string;\n  category: string;\n  subcategory?: string;\n  updatedAt: number;\n};\n\nlet runtimePromise: Promise<TransformersModule> | null = null;\nlet generatorPromise: Promise<TextGenerator> | null = null;\n\nfunction normalize(value: string) {\n  return value\n    .toLowerCase()\n    .normalize(\'NFD\')\n    .replace(/[\\u0300-\\u036f]/g, \'\')\n    .replace(/[^a-z0-9]+/g, \' \')\n    .trim();\n}\n\nfunction todayIso() {\n  const now = new Date();\n  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, \'0\')}-${String(\n    now.getDate(),\n  ).padStart(2, \'0\')}`;\n}\n\nfunction readJson<T>(key: string, fallback: T): T {\n  try {\n    const raw = window.localStorage.getItem(key);\n    if (!raw) return fallback;\n    return JSON.parse(raw) as T;\n  } catch {\n    return fallback;\n  }\n}\n\nfunction defaultSubcategories(categoryName: string): string[] {\n  const name = normalize(categoryName);\n  if ([\'food\', \'food drink\', \'food and drink\'].includes(name)) {\n    return [\'Breakfast\', \'Lunch\', \'Dinner\', \'Snacks\', \'Coffee\', \'Groceries\'];\n  }\n  if ([\'transport\', \'transportation\'].includes(name)) {\n    return [\n      \'Gas\',\n      \'Parking\',\n      \'Public Transit\',\n      \'Tolls\',\n      \'Maintenance\',\n      \'Car Payment\',\n      \'Auto Insurance\',\n    ];\n  }\n  if ([\'bills\', \'home bills\', \'utilities\'].includes(name)) {\n    return [\'Mortgage\', \'Rent\', \'Electric\', \'Gas (Home)\', \'Phone\', \'Cable\', \'Internet\', \'Water\'];\n  }\n  if ([\'self care\', \'selfcare\', \'personal care\'].includes(name)) {\n    return [\'Hair Cut\', \'Barber\', \'Nails\', \'Skincare\', \'Gym\', \'Spa\', \'Beauty\'];\n  }\n  if (name === \'shopping\') {\n    return [\'Clothing\', \'Shoes\', \'Electronics\', \'Household\', \'Gifts\', \'Online\'];\n  }\n  if ([\'health\', \'medical\'].includes(name)) {\n    return [\'Doctor\', \'Pharmacy\', \'Dental\', \'Vision\', \'Therapy\', \'Insurance\'];\n  }\n  if ([\'salary\', \'income\'].includes(name)) {\n    return [\'Paycheck\', \'Overtime\', \'Bonus\', \'Commission\', \'Tips\'];\n  }\n  if (name === \'freelance\') {\n    return [\'Client\', \'Project\', \'Contract\', \'Side Job\', \'Reimbursement\'];\n  }\n  if ([\'investment\', \'investments\'].includes(name)) {\n    return [\'Dividends\', \'Interest\', \'Stocks\', \'ETF\', \'Crypto\', \'Retirement\'];\n  }\n  return [];\n}\n\nfunction parentAliases(categoryName: string): string[] {\n  const name = normalize(categoryName);\n  if ([\'food\', \'food drink\', \'food and drink\'].includes(name)) {\n    return [\'food\', \'food & drink\', \'food and drink\'];\n  }\n  if ([\'transport\', \'transportation\'].includes(name)) {\n    return [\'transport\', \'transportation\'];\n  }\n  if ([\'bills\', \'home bills\', \'utilities\'].includes(name)) {\n    return [\'bills\', \'home bills\', \'utilities\'];\n  }\n  if ([\'self care\', \'selfcare\', \'personal care\'].includes(name)) {\n    return [\'self-care\', \'self care\', \'personal care\'];\n  }\n  return [categoryName];\n}\n\nexport function buildBudgetAiContext(categoryNames: string[]): BudgetAiContext {\n  const categories = Array.from(new Set(categoryNames.filter(Boolean)));\n  const mainCategoryNames = new Set(categories.map(normalize));\n  const custom = readJson<Record<string, string[]>>(CUSTOM_SUBCATEGORY_KEY, {});\n  const subcategories: Record<string, string[]> = {};\n\n  for (const category of categories) {\n    const aliases = new Set(parentAliases(category).map(normalize));\n    const customForCategory = Object.entries(custom)\n      .filter(([parent]) => aliases.has(normalize(parent)))\n      .flatMap(([, values]) => (Array.isArray(values) ? values : []));\n\n    subcategories[category] = Array.from(\n      new Set([...defaultSubcategories(category), ...customForCategory]),\n    ).filter(value => !mainCategoryNames.has(normalize(value)));\n  }\n\n  return { categories, subcategories };\n}\n\n\nfunction modelCacheUrl() {\n  return `${window.location.origin}/hf/${LOCAL_AI_MODEL_ID}/resolve/main/onnx/${MODEL_FILE_NAME}`;\n}\n\nfunction sameModelRequest(request: string) {\n  try {\n    const url = new URL(request, window.location.origin);\n    return url.href === modelCacheUrl();\n  } catch {\n    return false;\n  }\n}\n\nasync function smallFileCache() {\n  return caches.open(\'budget-local-ai-support-v1\');\n}\n\nconst fileBackedModelCache = {\n  async match(request: string): Promise<Response | undefined> {\n    if (selectedModelFile && sameModelRequest(request)) {\n      return new Response(selectedModelFile, {\n        status: 200,\n        headers: {\n          \'Content-Type\': \'application/octet-stream\',\n          \'Content-Length\': String(selectedModelFile.size),\n          \'X-Budget-Local-Model-Source\': \'iphone-files\',\n        },\n      });\n    }\n\n    const cache = await smallFileCache();\n    return (await cache.match(request)) ?? undefined;\n  },\n\n  async put(\n    request: string,\n    response: Response,\n    progressCallback?: (data: {\n      progress: number;\n      loaded: number;\n      total: number;\n    }) => void,\n  ) {\n    // Never duplicate the large ONNX file into Safari\'s CacheStorage.\n    if (sameModelRequest(request)) {\n      progressCallback?.({\n        progress: 100,\n        loaded: selectedModelFile?.size ?? 0,\n        total: selectedModelFile?.size ?? 0,\n      });\n      return;\n    }\n\n    const cache = await smallFileCache();\n    await cache.put(request, response.clone());\n  },\n};\n\nexport function localModelFileSelected() {\n  return Boolean(selectedModelFile);\n}\n\nexport function localModelFileInfo() {\n  if (!selectedModelFile) return null;\n  return {\n    name: selectedModelFile.name,\n    size: selectedModelFile.size,\n  };\n}\n\nexport function selectLocalModelFile(file: File) {\n  const lower = file.name.toLowerCase();\n  if (lower !== MODEL_FILE_NAME) {\n    throw new Error(\n      `Selecciona exactamente ${MODEL_FILE_NAME}. El archivo elegido fue ${file.name}.`,\n    );\n  }\n\n  if (file.size < MODEL_MIN_BYTES || file.size > MODEL_MAX_BYTES) {\n    throw new Error(\n      `El archivo no parece ser el modelo q4f16 correcto (${Math.round(\n        file.size / 1_000_000,\n      )} MB).`,\n    );\n  }\n\n  selectedModelFile = file;\n  generatorPromise = null;\n\n  return {\n    name: file.name,\n    size: file.size,\n  };\n}\n\nexport function releaseLocalModelFile() {\n  selectedModelFile = null;\n  generatorPromise = null;\n}\n\nexport function localAiWebGpuAvailable() {\n  return typeof navigator !== \'undefined\' && \'gpu\' in navigator;\n}\n\nasync function assertWebGpuAdapter() {\n  if (!localAiWebGpuAvailable()) {\n    throw new Error(\n      \'WebGPU no está disponible en este navegador. Smart Add normal sigue funcionando.\',\n    );\n  }\n\n  const gpu = (navigator as Navigator & {\n    gpu?: {\n      requestAdapter: (options?: Record<string, unknown>) => Promise<unknown>;\n    };\n  }).gpu;\n\n  if (!gpu?.requestAdapter) {\n    throw new Error(\'Safari reporta WebGPU, pero no expone requestAdapter().\');\n  }\n\n  const adapter = await gpu.requestAdapter({\n    powerPreference: \'high-performance\',\n  });\n  if (!adapter) {\n    throw new Error(\n      \'Safari no pudo obtener un adaptador WebGPU en este dispositivo.\',\n    );\n  }\n}\n\nexport function localAiWasInstalled() {\n  try {\n    return window.localStorage.getItem(INSTALL_KEY) === \'ready\' && localModelFileSelected();\n  } catch {\n    return false;\n  }\n}\n\nasync function assertLocalAiAsset(\n  url: string,\n  label: string,\n  method: \'GET\' | \'HEAD\' = \'GET\',\n) {\n  let response: Response;\n  try {\n    response = await fetch(url, { method, cache: \'no-store\' });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    throw new Error(`${label}: fallo de red (${message}).`);\n  }\n\n  if (!response.ok) {\n    throw new Error(`${label} no está disponible (${response.status}).`);\n  }\n\n  const contentType = response.headers.get(\'content-type\') || \'\';\n  if (\n    method === \'GET\' &&\n    url.split(\'?\')[0].endsWith(\'.mjs\') &&\n    !contentType.includes(\'javascript\') &&\n    !contentType.includes(\'ecmascript\')\n  ) {\n    throw new Error(\n      `${label} tiene un MIME inválido: ${contentType || \'desconocido\'}.`,\n    );\n  }\n}\n\nasync function importRuntime(\n  onProgress?: (progress: AiProgress) => void,\n): Promise<TransformersModule> {\n  if (runtimePromise) return runtimePromise;\n\n  runtimePromise = (async () => {\n    onProgress?.({ status: \'webgpu-check\', progress: 0.02 });\n    await assertWebGpuAdapter();\n\n    onProgress?.({ status: \'runtime-check\', progress: 0.05 });\n    await assertLocalAiAsset(RUNTIME_URL, \'Transformers.js\');\n\n    onProgress?.({ status: \'ort-module-check\', progress: 0.08 });\n    await assertLocalAiAsset(\n      \'/ort/ort-wasm-simd-threaded.asyncify.mjs\',\n      \'ONNX WebGPU asyncify module\',\n    );\n\n    onProgress?.({ status: \'ort-wasm-check\', progress: 0.10 });\n    await assertLocalAiAsset(\n      \'/ort/ort-wasm-simd-threaded.asyncify.wasm\',\n      \'ONNX WebGPU asyncify WASM\',\n      \'HEAD\',\n    );\n\n    onProgress?.({ status: \'model-file-check\', progress: 0.12 });\n    if (!selectedModelFile) {\n      throw new Error(\n        \'Selecciona model_q4f16.onnx desde Files antes de activar Local AI.\',\n      );\n    }\n\n    const runtimeUrl = RUNTIME_URL;\n    const imported = (await import(\n      /* @vite-ignore */ runtimeUrl\n    )) as unknown as TransformersModule;\n\n    if (!imported?.pipeline) {\n      throw new Error(\'El runtime local de IA no pudo iniciarse.\');\n    }\n\n    if (imported.env) {\n      imported.env.allowRemoteModels = true;\n      imported.env.allowLocalModels = false;\n      imported.env.useBrowserCache = false;\n      imported.env.useCustomCache = true;\n      imported.env.customCache = fileBackedModelCache;\n      imported.env.useWasmCache = true;\n\n      // Small tokenizer/config files still use the same-origin Worker proxy.\n      // The large ONNX weights are intercepted by fileBackedModelCache and\n      // read directly from the File object selected in iPhone Files.\n      imported.env.remoteHost = `${window.location.origin}/hf/`;\n      imported.env.remotePathTemplate = \'{model}/resolve/{revision}/\';\n\n      // Avoid spawning a WASM proxy worker on iOS. The selected model uses\n      // WebGPU, but these conservative WASM settings keep fallback internals\n      // from consuming extra memory.\n      const wasm = imported.env.backends?.onnx?.wasm;\n      if (wasm) {\n        // Transformers.js is self-hosted by Budget Local, so ONNX Runtime\'s\n        // WebGPU/JSEP companion files must also be self-hosted. Otherwise\n        // Safari can fail with the generic "Load failed" message while trying\n        // to dynamically import the backend loader. The small .mjs is\n        // same-origin; the oversized .wasm binary is fetched by CORS.\n        wasm.wasmPaths = {\n          // Transformers.js 4.3 expects ONNX Runtime\'s asyncify factory on\n          // modern Safari/WebGPU. Forcing the older JSEP factory can produce\n          // `webgpuInit is not a function`.\n          // Both files still come through the same-origin Budget Worker.\n          mjs: \'/ort/ort-wasm-simd-threaded.asyncify.mjs\',\n          wasm: \'/ort/ort-wasm-simd-threaded.asyncify.wasm\',\n        };\n        wasm.proxy = false;\n        wasm.numThreads = 1;\n      }\n    }\n\n    return imported;\n  })().catch(error => {\n    runtimePromise = null;\n    if (error instanceof Error) {\n      if (error.message === \'Load failed\') {\n        throw new Error(\n          \'Safari no pudo cargar un archivo del motor WebGPU. Budget Local ya usa Transformers.js 4.3 con soporte Safari 26+; vuelve a intentar con buena conexión.\',\n        );\n      }\n      if (\n        error.message.includes(\'webgpuInit\') ||\n        error.message.includes(\'no available backend\')\n      ) {\n        throw new Error(\n          `El backend WebGPU no pudo iniciar con ONNX Runtime: ${error.message}`,\n        );\n      }\n    }\n    throw error;\n  });\n\n  return runtimePromise;\n}\n\nfunction normalizeProgress(value: AiProgress): AiProgress {\n  const next = { ...value };\n  if (typeof next.progress === \'number\') {\n    next.progress =\n      next.progress > 1 ? Math.min(1, next.progress / 100) : Math.max(0, next.progress);\n  } else if (\n    typeof next.loaded === \'number\' &&\n    typeof next.total === \'number\' &&\n    next.total > 0\n  ) {\n    next.progress = Math.max(0, Math.min(1, next.loaded / next.total));\n  }\n  return next;\n}\n\nexport async function loadLocalBudgetAi(\n  onProgress?: (progress: AiProgress) => void,\n): Promise<TextGenerator> {\n  if (!localAiWebGpuAvailable()) {\n    throw new Error(\n      \'WebGPU no está disponible en este navegador. Smart Add normal sigue funcionando.\',\n    );\n  }\n\n  if (!generatorPromise) {\n    generatorPromise = (async () => {\n      if (navigator.storage?.persist) {\n        try {\n          await navigator.storage.persist();\n        } catch {\n          // Persistence is best-effort only.\n        }\n      }\n\n      const runtime = await importRuntime(onProgress);\n      onProgress?.({ status: \'runtime-ready\', progress: 0.14 });\n      onProgress?.({ status: \'model-download\', progress: 0.15 });\n\n      const generator = await runtime.pipeline(\n        \'text-generation\',\n        LOCAL_AI_MODEL_ID,\n        {\n          device: \'webgpu\',\n          dtype: \'q4f16\',\n          progress_callback: (progress: AiProgress) =>\n            onProgress?.(normalizeProgress(progress)),\n        },\n      );\n\n      window.localStorage.setItem(INSTALL_KEY, \'ready\');\n      onProgress?.({ status: \'ready\', progress: 1 });\n      return generator;\n    })().catch(error => {\n      generatorPromise = null;\n      if (error instanceof Error && error.message === \'Load failed\') {\n        throw new Error(\n          \'SmolLM2 135M no pudo cargar desde el archivo seleccionado después de iniciar WebGPU. Budget Local usa un proxy del mismo dominio para Hugging Face y ONNX; vuelve a intentar y revisa la etapa mostrada.\',\n        );\n      }\n      throw error;\n    });\n  }\n\n  return generatorPromise;\n}\n\nfunction extractGeneratedText(output: unknown): string {\n  if (!Array.isArray(output) || output.length === 0) return \'\';\n  const first = output[0] as { generated_text?: unknown };\n  const generated = first?.generated_text;\n\n  if (typeof generated === \'string\') return generated;\n  if (Array.isArray(generated) && generated.length > 0) {\n    const last = generated[generated.length - 1] as { content?: unknown };\n    if (typeof last?.content === \'string\') return last.content;\n  }\n  return \'\';\n}\n\nfunction parseJsonObject(text: string): Record<string, unknown> {\n  const cleaned = text\n    .replace(/<think>[\\s\\S]*?<\\/think>/gi, \'\')\n    .replace(/```(?:json)?/gi, \'\')\n    .replace(/```/g, \'\')\n    .trim();\n\n  const start = cleaned.indexOf(\'{\');\n  const end = cleaned.lastIndexOf(\'}\');\n  if (start < 0 || end <= start) {\n    throw new Error(\'La IA no devolvió una transacción válida.\');\n  }\n\n  return JSON.parse(cleaned.slice(start, end + 1)) as Record<string, unknown>;\n}\n\n\nfunction canonicalMention(text: string, allowed: string[]): string | undefined {\n  const normalizedText = ` ${normalize(text)} `;\n  return [...allowed]\n    .sort((a, b) => normalize(b).length - normalize(a).length)\n    .find(item => {\n      const candidate = normalize(item);\n      return candidate && normalizedText.includes(` ${candidate} `);\n    });\n}\n\nfunction parseLabelValue(text: string, label: string): string | undefined {\n  const regex = new RegExp(\n    `${label}\\\\s*[:=]\\\\s*([^;\\\\n|]+)`,\n    \'i\',\n  );\n  const match = text.match(regex);\n  return match?.[1]?.trim();\n}\n\nfunction merchantMemoryFor(payee?: string): MerchantMemory | undefined {\n  if (!payee) return undefined;\n  const key = normalize(payee);\n  return [...readMerchantMemory()]\n    .reverse()\n    .find(item => normalize(item.payee) === key);\n}\n\nfunction nullableString(value: unknown): string | undefined {\n  if (typeof value !== \'string\') return undefined;\n  const cleaned = value.trim();\n  if (!cleaned || cleaned.toLowerCase() === \'null\') return undefined;\n  return cleaned;\n}\n\nfunction canonicalName(value: unknown, allowed: string[]): string | undefined {\n  const candidate = nullableString(value);\n  if (!candidate) return undefined;\n  const target = normalize(candidate);\n  return allowed.find(item => normalize(item) === target);\n}\n\nfunction readMerchantMemory(): MerchantMemory[] {\n  const stored = readJson<MerchantMemory[]>(MERCHANT_MEMORY_KEY, []);\n  return Array.isArray(stored)\n    ? stored\n        .filter(\n          item =>\n            item &&\n            typeof item.payee === \'string\' &&\n            typeof item.category === \'string\',\n        )\n        .slice(-100)\n    : [];\n}\n\nexport function rememberBudgetAiChoice(draft: SmartDraft) {\n  if (!draft.payee || !draft.category) return false;\n\n  const memory = readMerchantMemory().filter(\n    item => normalize(item.payee) !== normalize(draft.payee || \'\'),\n  );\n  memory.push({\n    payee: draft.payee,\n    category: draft.category,\n    subcategory: draft.subcategory,\n    updatedAt: Date.now(),\n  });\n\n  window.localStorage.setItem(\n    MERCHANT_MEMORY_KEY,\n    JSON.stringify(memory.slice(-100)),\n  );\n  return true;\n}\n\nexport async function clearLocalBudgetAiCache() {\n  generatorPromise = null;\n  runtimePromise = null;\n  selectedModelFile = null;\n  window.localStorage.removeItem(INSTALL_KEY);\n\n  if (\'caches\' in window) {\n    const names = await caches.keys();\n    await Promise.all(\n      names\n        .filter(name => name.toLowerCase().includes(\'transform\'))\n        .map(name => caches.delete(name)),\n    );\n  }\n}\n\nexport async function runLocalBudgetAi(\n  sourceText: string,\n  context: BudgetAiContext,\n  onProgress?: (progress: AiProgress) => void,\n): Promise<SmartDraft> {\n  // The deterministic parser is authoritative for fields it handles well:\n  // amount, date, payee, account and basic expense/income detection.\n  const base = parseSmartText(sourceText);\n\n  // User-confirmed merchant learning wins before model inference.\n  const remembered = merchantMemoryFor(base.payee);\n  if (remembered) {\n    const validCategory = canonicalName(\n      remembered.category,\n      context.categories,\n    );\n    const validSubcategory =\n      validCategory &&\n      canonicalName(\n        remembered.subcategory,\n        context.subcategories[validCategory] ?? [],\n      );\n\n    if (validCategory) {\n      return {\n        ...base,\n        category: validCategory,\n        subcategory: validSubcategory,\n        confidence: 0.99,\n      };\n    }\n  }\n\n  const generator = await loadLocalBudgetAi(onProgress);\n  onProgress?.({ status: \'classifying\', progress: 0.96 });\n\n  const categories = context.categories;\n  const compactSubcategories = categories\n    .map(category => {\n      const subs = context.subcategories[category] ?? [];\n      return subs.length\n        ? `${category}: ${subs.join(\', \')}`\n        : `${category}: none`;\n    })\n    .join(\'\\n\');\n\n  // SmolLM2 135M is intentionally used only as a constrained classifier.\n  // Requiring full JSON from a 135M model was unreliable even though the\n  // model loaded successfully.\n  const prompt = `Classify this personal finance transaction.\n\nTEXT:\n${sourceText}\n\nALLOWED CATEGORIES:\n${categories.join(\' | \')}\n\nALLOWED SUBCATEGORIES:\n${compactSubcategories}\n\nReturn ONLY one short line:\nCATEGORY=<exact allowed category or NONE>; SUBCATEGORY=<exact allowed subcategory or NONE>; TYPE=<expense or income>\n\nDo not explain.`;\n\n  const output = await generator(prompt, {\n    max_new_tokens: 44,\n    do_sample: false,\n    repetition_penalty: 1.01,\n    return_full_text: false,\n  });\n\n  const answer = extractGeneratedText(output).trim();\n\n  const rawCategory = parseLabelValue(answer, \'CATEGORY\');\n  let category =\n    canonicalName(rawCategory, categories) ??\n    canonicalMention(answer, categories);\n\n  // If the model mentions a subcategory clearly, infer its unique parent too.\n  let subcategory: string | undefined;\n  const rawSubcategory = parseLabelValue(answer, \'SUBCATEGORY\');\n\n  if (category) {\n    const allowedSubs = context.subcategories[category] ?? [];\n    subcategory =\n      canonicalName(rawSubcategory, allowedSubs) ??\n      canonicalMention(answer, allowedSubs);\n  } else {\n    for (const candidateCategory of categories) {\n      const allowedSubs = context.subcategories[candidateCategory] ?? [];\n      const candidateSub =\n        canonicalName(rawSubcategory, allowedSubs) ??\n        canonicalMention(answer, allowedSubs);\n      if (candidateSub) {\n        category = candidateCategory;\n        subcategory = candidateSub;\n        break;\n      }\n    }\n  }\n\n  const typeValue = normalize(parseLabelValue(answer, \'TYPE\') || answer);\n  const kind: SmartDraft[\'kind\'] =\n    /\\bincome\\b/.test(typeValue)\n      ? \'income\'\n      : /\\bexpense\\b/.test(typeValue)\n        ? \'expense\'\n        : base.kind;\n\n  // AI augments the working deterministic result instead of replacing it.\n  return {\n    ...base,\n    kind,\n    category: category ?? base.category,\n    subcategory,\n    notes: base.notes,\n    sourceText,\n    confidence: category ? 0.9 : base.confidence,\n  };\n}\n'

SMART_ADD_PARSER_TS = 'export type SmartDraft = {\n  kind: \'expense\' | \'income\';\n  amount?: number;\n  payee?: string;\n  category?: string;\n  subcategory?: string;\n  account?: string;\n  date?: string;\n  notes?: string;\n  sourceText?: string;\n  confidence?: number;\n};\n\nfunction cleanSpaces(value: string): string {\n  return value.replace(/\\s+/g, \' \').trim();\n}\n\nfunction cleanLabel(value?: string): string | undefined {\n  if (!value) return undefined;\n  const cleaned = cleanSpaces(value.replace(/^[\\s,:;\\-–—]+|[\\s,:;\\-–—]+$/g, \'\'));\n  return cleaned || undefined;\n}\n\nfunction normalizeAmount(value: string): number | undefined {\n  const normalized = value\n    .replace(/[$,]/g, \'\')\n    .replace(/[Oo](?=\\d)/g, \'0\')\n    .replace(/(?<=\\d)[Oo]/g, \'0\');\n  const parsed = Number.parseFloat(normalized);\n  if (!Number.isFinite(parsed) || parsed <= 0 || parsed > 100000000) {\n    return undefined;\n  }\n  return Math.round(parsed * 100) / 100;\n}\n\nfunction findAmount(text: string): number | undefined {\n  const matches = [...text.matchAll(/(?:\\$\\s*)?(\\d{1,3}(?:,\\d{3})*|\\d+)[.](\\d{2})\\b/g)];\n  if (matches.length === 0) return undefined;\n  return normalizeAmount(matches[0][0]);\n}\n\nfunction isoFromParts(month: number, day: number, year: number): string | undefined {\n  const fullYear = year < 100 ? (year >= 70 ? 1900 + year : 2000 + year) : year;\n  const date = new Date(fullYear, month - 1, day);\n  if (\n    date.getFullYear() !== fullYear ||\n    date.getMonth() !== month - 1 ||\n    date.getDate() !== day\n  ) {\n    return undefined;\n  }\n  return `${String(fullYear).padStart(4, \'0\')}-${String(month).padStart(2, \'0\')}-${String(day).padStart(2, \'0\')}`;\n}\n\nexport function extractDate(text: string, now = new Date()): string | undefined {\n  const lower = text.toLowerCase();\n  if (/\\b(today|hoy)\\b/.test(lower)) {\n    return isoFromParts(now.getMonth() + 1, now.getDate(), now.getFullYear());\n  }\n  if (/\\b(yesterday|ayer)\\b/.test(lower)) {\n    const d = new Date(now);\n    d.setDate(d.getDate() - 1);\n    return isoFromParts(d.getMonth() + 1, d.getDate(), d.getFullYear());\n  }\n\n  const iso = text.match(/\\b(20\\d{2})[-/.](\\d{1,2})[-/.](\\d{1,2})\\b/);\n  if (iso) {\n    return isoFromParts(Number(iso[2]), Number(iso[3]), Number(iso[1]));\n  }\n\n  const us = text.match(/\\b(\\d{1,2})[/-](\\d{1,2})[/-](\\d{2,4})\\b/);\n  if (us) {\n    return isoFromParts(Number(us[1]), Number(us[2]), Number(us[3]));\n  }\n\n  const monthNames: Record<string, number> = {\n    jan: 1,\n    january: 1,\n    ene: 1,\n    enero: 1,\n    feb: 2,\n    february: 2,\n    febrero: 2,\n    mar: 3,\n    march: 3,\n    marzo: 3,\n    apr: 4,\n    april: 4,\n    abr: 4,\n    abril: 4,\n    may: 5,\n    mayo: 5,\n    jun: 6,\n    june: 6,\n    junio: 6,\n    jul: 7,\n    july: 7,\n    julio: 7,\n    aug: 8,\n    august: 8,\n    ago: 8,\n    agosto: 8,\n    sep: 9,\n    sept: 9,\n    september: 9,\n    septiembre: 9,\n    oct: 10,\n    october: 10,\n    octubre: 10,\n    nov: 11,\n    november: 11,\n    noviembre: 11,\n    dec: 12,\n    december: 12,\n    dic: 12,\n    diciembre: 12,\n  };\n  const wordDate = lower.match(\n    /\\b(jan(?:uary)?|ene(?:ro)?|feb(?:ruary|rero)?|mar(?:ch|zo)?|apr(?:il)?|abr(?:il)?|may|mayo|jun(?:e|io)?|jul(?:y|io)?|aug(?:ust)?|ago(?:sto)?|sep(?:t(?:ember)?)?|septiembre|oct(?:ober|ubre)?|nov(?:ember|iembre)?|dec(?:ember)?|dic(?:iembre)?)\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{2,4}))?\\b/,\n  );\n  if (wordDate) {\n    const month = monthNames[wordDate[1]];\n    const year = wordDate[3] ? Number(wordDate[3]) : now.getFullYear();\n    return isoFromParts(month, Number(wordDate[2]), year);\n  }\n  return undefined;\n}\n\nfunction extractTaggedValue(text: string, labels: string[]): string | undefined {\n  const escaped = labels.map(label => label.replace(/[.*+?^${}()|[\\]\\\\]/g, \'\\\\$&\'));\n  const nextTag = \'(?:category|categoria|categoría|account|cuenta|payee|comercio|merchant)\';\n  const regex = new RegExp(\n    `(?:^|\\\\s)(?:${escaped.join(\'|\')})\\\\s*[:=]\\\\s*(?:"([^"]+)"|\'([^\']+)\'|(.+?))(?=\\\\s+${nextTag}\\\\s*[:=]|[,;\\\\n]|$)`,\n    \'i\',\n  );\n  const match = text.match(regex);\n  return cleanLabel(match?.[1] || match?.[2] || match?.[3]);\n}\n\nfunction stripTaggedValues(text: string): string {\n  return text.replace(\n    /(?:^|\\s)(?:category|categoria|categoría|account|cuenta|payee|comercio|merchant)\\s*[:=]\\s*(?:"[^"]+"|\'[^\']+\'|.+?)(?=\\s+(?:category|categoria|categoría|account|cuenta|payee|comercio|merchant)\\s*[:=]|[,;\\n]|$)/gi,\n    \' \',\n  );\n}\n\nexport function parseSmartText(text: string, now = new Date()): SmartDraft {\n  const sourceText = cleanSpaces(text);\n  const lower = sourceText.toLowerCase();\n  const kind: SmartDraft[\'kind\'] = /\\b(income|ingreso|salary|salario|paycheck|deposit|depósito|deposito|refund|reembolso)\\b/.test(\n    lower,\n  )\n    ? \'income\'\n    : \'expense\';\n\n  const explicitPayee = extractTaggedValue(sourceText, [\'payee\', \'merchant\', \'comercio\']);\n  const category =\n    extractTaggedValue(sourceText, [\'category\', \'categoria\', \'categoría\']) ||\n    cleanLabel(sourceText.match(/(?:^|\\s)#([\\p{L}\\p{N}_ -]{2,40})/u)?.[1]);\n  const account =\n    extractTaggedValue(sourceText, [\'account\', \'cuenta\']) ||\n    cleanLabel(sourceText.match(/(?:^|\\s)@([\\p{L}\\p{N}_ -]{2,40})/u)?.[1]) ||\n    cleanLabel(\n      sourceText.match(\n        /\\b(?:with|con)\\s+([\\p{L}\\p{N}][\\p{L}\\p{N} ._-]{1,30}?(?:card|tarjeta))\\b/iu,\n      )?.[1],\n    );\n\n  const amountMatch = sourceText.match(\n    /(?:\\$\\s*)?(\\d{1,3}(?:,\\d{3})*|\\d+)[.](\\d{2})\\b|(?:\\$\\s*)(\\d+(?:\\.\\d{1,2})?)/,\n  );\n  const amount = amountMatch ? normalizeAmount(amountMatch[0]) : undefined;\n  const date = extractDate(sourceText, now);\n\n  let payee = explicitPayee;\n  if (!payee && amountMatch?.index != null) {\n    let beforeAmount = stripTaggedValues(sourceText.slice(0, amountMatch.index));\n    beforeAmount = beforeAmount\n      .replace(/\\b(expense|gasto|income|ingreso|paid|pagu[eé]|spent|gast[eé]|at|en|from|de)\\b/gi, \' \')\n      .replace(/[#@][\\p{L}\\p{N}_ -]+/gu, \' \');\n    payee = cleanLabel(beforeAmount);\n  }\n\n  return {\n    kind,\n    amount,\n    payee,\n    category,\n    account,\n    date,\n    notes: sourceText || undefined,\n    sourceText,\n    confidence: amount ? 0.8 : 0.45,\n  };\n}\n\nfunction amountsInLine(line: string): number[] {\n  return [...line.matchAll(/(?:\\$\\s*)?(\\d{1,3}(?:,\\d{3})*|\\d+)[.](\\d{2})\\b/g)]\n    .map(match => normalizeAmount(match[0]))\n    .filter((value): value is number => value != null);\n}\n\nfunction likelyMerchant(lines: string[]): string | undefined {\n  const ignored = /\\b(receipt|thank|thanks|welcome|cashier|register|store\\s*#|www\\.|http|tel|phone|date|time|subtotal|total|tax)\\b/i;\n  for (const line of lines.slice(0, 8)) {\n    const cleaned = cleanSpaces(line.replace(/[|_*~]+/g, \' \'));\n    const letters = (cleaned.match(/[A-Za-zÀ-ÿ]/g) || []).length;\n    if (cleaned.length >= 3 && cleaned.length <= 70 && letters >= 3 && !ignored.test(cleaned)) {\n      return cleaned;\n    }\n  }\n  return undefined;\n}\n\nexport function parseReceiptText(text: string, now = new Date()): SmartDraft {\n  const rawLines = text\n    .split(/\\r?\\n/)\n    .map(line => cleanSpaces(line))\n    .filter(Boolean);\n\n  const prioritized: Array<{ priority: number; amount: number }> = [];\n  for (const line of rawLines) {\n    const lower = line.toLowerCase();\n    if (/\\b(sub\\s*total|subtotal|tax|change|cash|tender)\\b/.test(lower)) continue;\n    const values = amountsInLine(line);\n    if (values.length === 0) continue;\n\n    let priority = 0;\n    if (/\\b(grand\\s*total|amount\\s*due|balance\\s*due|total\\s*due)\\b/.test(lower)) priority = 100;\n    else if (/\\btotal\\b/.test(lower)) priority = 90;\n    else if (/\\b(amount|due|paid)\\b/.test(lower)) priority = 65;\n\n    for (const amount of values) prioritized.push({ priority, amount });\n  }\n\n  let amount: number | undefined;\n  if (prioritized.length > 0) {\n    prioritized.sort((a, b) => b.priority - a.priority || b.amount - a.amount);\n    if (prioritized[0].priority > 0) {\n      amount = prioritized[0].amount;\n    } else {\n      const bottomHalf = rawLines.slice(Math.floor(rawLines.length / 2));\n      const fallback = bottomHalf.flatMap(amountsInLine);\n      if (fallback.length > 0) amount = Math.max(...fallback);\n    }\n  }\n\n  const date = rawLines.map(line => extractDate(line, now)).find(Boolean);\n  const payee = likelyMerchant(rawLines);\n  const confidence = amount ? (payee ? 0.88 : 0.78) : 0.4;\n\n  return {\n    kind: \'expense\',\n    amount,\n    payee,\n    date,\n    notes: payee\n      ? `Escaneado localmente desde recibo — comercio: ${payee}`\n      : \'Escaneado localmente desde recibo\',\n    sourceText: text,\n    confidence,\n  };\n}\n\nexport function toActualTransactionQuery(draft: SmartDraft): string {\n  const params = new URLSearchParams();\n  if (draft.amount != null) {\n    // Actual\'s mobile new-transaction route negates this query value.\n    // Positive query => expense. Negative query => income.\n    const queryAmount = draft.kind === \'income\' ? -Math.abs(draft.amount) : Math.abs(draft.amount);\n    params.set(\'amount\', queryAmount.toFixed(2));\n  }\n  if (draft.payee) params.set(\'payee\', draft.payee);\n  if (draft.category) params.set(\'category\', draft.category);\n  if (draft.account) params.set(\'account\', draft.account);\n  if (draft.date) params.set(\'date\', draft.date);\n\n  let notes = draft.notes?.trim() || \'\';\n  if (draft.subcategory) {\n    const tag = `#${draft.subcategory.replace(/\\\\s+/g, \'\')}`;\n    if (!notes.includes(tag)) {\n      notes = `${notes}${notes ? \' \' : \'\'}${tag}`;\n    }\n  }\n  if (notes) params.set(\'notes\', notes);\n  return params.toString();\n}\n'

