BUDGET_LOCAL_HOME_TSX = 'import React, { useEffect, useMemo, useState } from \'react\';\n\nimport {\n  SvgCheveronLeft,\n  SvgCheveronRight,\n  SvgPiggyBank,\n} from \'@actual-app/components/icons/v1\';\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport * as monthUtils from \'@actual-app/core/shared/months\';\nimport { send } from \'@actual-app/core/platform/client/connection\';\nimport { q } from \'@actual-app/core/shared/query\';\nimport type { CategoryEntity } from \'@actual-app/core/types/models\';\nimport { useQueryClient } from \'@tanstack/react-query\';\n\nimport { categoryQueries } from \'#budget\';\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useLocale } from \'#hooks/useLocale\';\nimport { useNavigate } from \'#hooks/useNavigate\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\nimport { RecurringIncomeCard } from \'./RecurringIncomeCard\';\n\ntype CardDefinition = {\n  label: string;\n  emoji: string;\n  background: string;\n  accent: string;\n  candidates: string[];\n};\n\nconst EXPENSE_CARDS: CardDefinition[] = [\n  {\n    label: \'Food & Drink\',\n    emoji: \'🍽️\',\n    background: \'#FFF2D5\',\n    accent: \'#FFC44D\',\n    candidates: [\'food & drink\', \'food\'],\n  },\n  {\n    label: \'Transport\',\n    emoji: \'🚌\',\n    background: \'#DFECFF\',\n    accent: \'#56A4FF\',\n    candidates: [\'transport\', \'transportation\'],\n  },\n  {\n    label: \'Home Bills\',\n    emoji: \'⚡\',\n    background: \'#FFE8D7\',\n    accent: \'#FF9B54\',\n    candidates: [\'home bills\', \'bills\', \'utilities\'],\n  },\n  {\n    label: \'Self-Care\',\n    emoji: \'✨\',\n    background: \'#F0E3FF\',\n    accent: \'#AB78E7\',\n    candidates: [\'self-care\', \'self care\'],\n  },\n  {\n    label: \'Shopping\',\n    emoji: \'🛍️\',\n    background: \'#FFE0E0\',\n    accent: \'#FF5A5F\',\n    candidates: [\'shopping\'],\n  },\n  {\n    label: \'Health\',\n    emoji: \'✚\',\n    background: \'#D9F7F2\',\n    accent: \'#1FC9B0\',\n    candidates: [\'health\'],\n  },\n];\n\nconst INCOME_CARDS: CardDefinition[] = [\n  {\n    label: \'Salary\',\n    emoji: \'💳\',\n    background: \'#D9F8F2\',\n    accent: \'#1FC9B0\',\n    candidates: [\'salary\', \'income\'],\n  },\n  {\n    label: \'Freelance\',\n    emoji: \'◇\',\n    background: \'#E8F8F8\',\n    accent: \'#92DDD6\',\n    candidates: [\'freelance\'],\n  },\n  {\n    label: \'Investment\',\n    emoji: \'📈\',\n    background: \'#E7F6DB\',\n    accent: \'#7FD84E\',\n    candidates: [\'investment\', \'investments\'],\n  },\n];\n\nconst REPORT_SUBCATEGORIES_BY_CARD: Record<string, string[]> = {\n  \'Food & Drink\': [\n    \'Breakfast\',\n    \'Lunch\',\n    \'Dinner\',\n    \'Snacks\',\n    \'Coffee\',\n    \'Groceries\',\n  ],\n  Transport: [\n    \'Gas\',\n    \'Parking\',\n    \'Public Transit\',\n    \'Tolls\',\n    \'Maintenance\',\n    \'Car Payment\',\n    \'Auto Insurance\',\n  ],\n  \'Home Bills\': [\n    \'Mortgage\',\n    \'Rent\',\n    \'Electric\',\n    \'Gas (Home)\',\n    \'Phone\',\n    \'Cable\',\n    \'Internet\',\n    \'Water\',\n  ],\n  \'Self-Care\': [\n    \'Hair\',\n    \'Barber\',\n    \'Nails\',\n    \'Skincare\',\n    \'Gym\',\n    \'Spa\',\n    \'Beauty\',\n  ],\n  Shopping: [\n    \'Clothing\',\n    \'Shoes\',\n    \'Electronics\',\n    \'Household\',\n    \'Gifts\',\n    \'Online\',\n  ],\n  Health: [\n    \'Doctor\',\n    \'Pharmacy\',\n    \'Dental\',\n    \'Vision\',\n    \'Therapy\',\n    \'Insurance\',\n  ],\n};\n\nfunction subcategorySlug(value: string) {\n  return normalize(value).replace(/\\s+/g, \'\');\n}\n\nfunction transactionSubcategory(\n  notes: string | null | undefined,\n  candidates: string[],\n) {\n  if (!notes || candidates.length === 0) return undefined;\n\n  const tokens = notes\n    .split(/\\s+/)\n    .filter(token => token.startsWith(\'#\'))\n    .map(token => token.slice(1));\n\n  for (const candidate of candidates) {\n    const slug = subcategorySlug(candidate);\n    if (\n      tokens.some(token => {\n        const clean = token.toLowerCase().startsWith(\'sub:\')\n          ? token.slice(4)\n          : token;\n        return subcategorySlug(clean) === slug;\n      })\n    ) {\n      return candidate;\n    }\n  }\n\n  return undefined;\n}\n\n\nfunction normalize(value: string) {\n  return value\n    .toLowerCase()\n    .normalize(\'NFD\')\n    .replace(/[\\u0300-\\u036f]/g, \'\')\n    .replace(/[^a-z0-9]+/g, \' \')\n    .trim();\n}\n\nfunction findCategory(\n  categories: CategoryEntity[],\n  candidates: string[],\n  isIncome: boolean,\n) {\n  const normalizedCandidates = candidates.map(normalize);\n  const eligible = categories.filter(\n    category => !category.hidden && Boolean(category.is_income) === isIncome,\n  );\n\n  return eligible.find(category => {\n    const name = normalize(category.name);\n    return normalizedCandidates.some(candidate => name === candidate);\n  });\n}\n\n\nconst SUBCATEGORY_STORAGE_KEY = \'budget-local-subcategories-v1\';\nconst PINNED_MAIN_STORAGE_KEY = \'budget-local-pinned-main-v1\';\n\nconst EXTRA_CARD_PALETTE = [\n  { background: \'#EAF3FF\', accent: \'#5A9BEF\' },\n  { background: \'#FFF0E1\', accent: \'#F59B57\' },\n  { background: \'#E9F8EA\', accent: \'#6FCD72\' },\n  { background: \'#F4E8FF\', accent: \'#A979E4\' },\n  { background: \'#FFE8EF\', accent: \'#EC7192\' },\n  { background: \'#E3F7F6\', accent: \'#45BEB4\' },\n];\n\nfunction categoryEmoji(name: string) {\n  const value = normalize(name);\n  if (value.includes(\'mortgage\') || value.includes(\'house\')) return \'🏠\';\n  if (value.includes(\'rent\')) return \'🏡\';\n  if (value.includes(\'travel\') || value.includes(\'vacation\')) return \'✈️\';\n  if (value.includes(\'pet\')) return \'🐾\';\n  if (value.includes(\'entertain\')) return \'🎬\';\n  if (value.includes(\'school\') || value.includes(\'education\')) return \'🎓\';\n  if (value.includes(\'debt\') || value.includes(\'credit\')) return \'💳\';\n  if (value.includes(\'gift\')) return \'🎁\';\n  if (value.includes(\'saving\')) return \'💰\';\n  if (value.includes(\'child\') || value.includes(\'kid\')) return \'🧸\';\n  return \'💵\';\n}\n\nfunction extraDefinition(category: CategoryEntity, index: number): CardDefinition {\n  const palette = EXTRA_CARD_PALETTE[index % EXTRA_CARD_PALETTE.length];\n  return {\n    label: category.name,\n    emoji: categoryEmoji(category.name),\n    background: palette.background,\n    accent: palette.accent,\n    candidates: [normalize(category.name)],\n  };\n}\n\nfunction readSubcategories(): Record<string, string[]> {\n  try {\n    const raw = window.localStorage.getItem(SUBCATEGORY_STORAGE_KEY);\n    if (!raw) return {};\n    const parsed = JSON.parse(raw) as Record<string, unknown>;\n    const clean: Record<string, string[]> = {};\n    for (const [key, value] of Object.entries(parsed)) {\n      if (Array.isArray(value)) {\n        clean[key] = value.filter(item => typeof item === \'string\') as string[];\n      }\n    }\n    return clean;\n  } catch {\n    return {};\n  }\n}\n\nfunction writeSubcategories(value: Record<string, string[]>) {\n  window.localStorage.setItem(SUBCATEGORY_STORAGE_KEY, JSON.stringify(value));\n}\n\nfunction readPinnedMainIds(): string[] {\n  try {\n    const parsed = JSON.parse(\n      window.localStorage.getItem(PINNED_MAIN_STORAGE_KEY) || \'[]\',\n    );\n    return Array.isArray(parsed)\n      ? parsed.filter(item => typeof item === \'string\')\n      : [];\n  } catch {\n    return [];\n  }\n}\n\nfunction writePinnedMainIds(ids: string[]) {\n  window.localStorage.setItem(\n    PINNED_MAIN_STORAGE_KEY,\n    JSON.stringify(Array.from(new Set(ids))),\n  );\n}\n\nfunction DashboardCard({\n  definition,\n  category,\n  month,\n  amount,\n  budget,\n  onOpen,\n}: {\n  definition: CardDefinition;\n  category?: CategoryEntity;\n  month: string;\n  amount: number;\n  budget: number;\n  onOpen: () => void;\n}) {\n  const format = useFormat();\n  const isIncome = Boolean(category?.is_income);\n  const value = isIncome ? Math.max(0, amount) : Math.max(0, -amount);\n  const planned = Math.max(0, budget);\n  const left = planned - value;\n  const usedPercent = planned > 0 ? Math.max(0, (value / planned) * 100) : 0;\n  const ringPercent = Math.min(100, usedPercent);\n  const overBudget = !isIncome && planned > 0 && left < 0;\n\n  return (\n    <button\n      type="button"\n      onClick={onOpen}\n      aria-label={`${definition.label}: ${format(value, \'financial\')}`}\n      style={{\n        appearance: \'none\',\n        WebkitAppearance: \'none\',\n        WebkitTapHighlightColor: \'transparent\',\n        border: 0,\n        borderRadius: 24,\n        minWidth: 0,\n        minHeight: 154,\n        padding: \'16px 8px 14px\',\n        background: definition.background,\n        boxShadow: \'0 10px 28px rgba(47, 56, 90, 0.08)\',\n        display: \'flex\',\n        flexDirection: \'column\',\n        alignItems: \'center\',\n        justifyContent: \'space-between\',\n        color: \'#15151B\',\n        font: \'inherit\',\n        cursor: \'pointer\',\n      }}\n    >\n      <span\n        style={{\n          minHeight: 34,\n          display: \'flex\',\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          textAlign: \'center\',\n          fontSize: 15,\n          lineHeight: 1.08,\n          fontWeight: 700,\n          letterSpacing: \'-0.01em\',\n        }}\n      >\n        {definition.label}\n      </span>\n\n      <span\n        aria-hidden\n        style={{\n          width: 62,\n          height: 62,\n          borderRadius: 999,\n          padding: 4,\n          display: \'flex\',\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          background: isIncome\n            ? \'#EEF1F4\'\n            : planned > 0\n              ? `conic-gradient(${overBudget ? \'#E34D59\' : definition.accent} ${ringPercent}%, rgba(255,255,255,0.58) 0)`\n              : \'rgba(255,255,255,0.58)\',\n          boxShadow: \'0 7px 15px rgba(0,0,0,0.05)\',\n        }}\n      >\n        <span\n          style={{\n            width: 50,\n            height: 50,\n            borderRadius: 999,\n            display: \'flex\',\n            alignItems: \'center\',\n            justifyContent: \'center\',\n            background: definition.accent,\n            fontSize: 25,\n            color: \'#fff\',\n          }}\n        >\n          {definition.emoji}\n        </span>\n      </span>\n\n      <span\n        style={{\n          display: \'flex\',\n          flexDirection: \'column\',\n          alignItems: \'center\',\n          gap: 4,\n        }}\n      >\n        <span\n          style={{\n            fontSize: 18,\n            lineHeight: 1,\n            fontWeight: 800,\n            letterSpacing: \'-0.02em\',\n            color: overBudget ? \'#C93645\' : \'#15151B\',\n          }}\n        >\n          {format(value, \'financial\')}\n        </span>\n        {!isIncome && (\n          <span\n            style={{\n              fontSize: 10,\n              lineHeight: 1,\n              fontWeight: 750,\n              color: overBudget ? \'#C93645\' : \'#747783\',\n            }}\n          >\n            {planned > 0\n              ? `${format(Math.abs(left), \'financial\')} ${left >= 0 ? \'left\' : \'over\'}`\n              : \'No budget\'}\n          </span>\n        )}\n      </span>\n    </button>\n  );\n}\n\nexport function BudgetLocalHome() {\n  const navigate = useNavigate();\n  const locale = useLocale();\n  const format = useFormat();\n  const queryClient = useQueryClient();\n  const [month, setMonth] = useState(() => monthUtils.currentMonth());\n  const [showCategoryOrganizer, setShowCategoryOrganizer] = useState(false);\n  const [showMonthlyReport, setShowMonthlyReport] = useState(false);\n  const [categoryMode, setCategoryMode] = useState<\'main\' | \'sub\'>(\'sub\');\n  const [categoryKind, setCategoryKind] = useState<\'expense\' | \'income\'>(\n    \'expense\',\n  );\n  const [newCategoryName, setNewCategoryName] = useState(\'\');\n  const [parentLabel, setParentLabel] = useState(\'Self-Care\');\n  const [categoryMessage, setCategoryMessage] = useState(\'\');\n  const [savingCategory, setSavingCategory] = useState(false);\n  const [pinnedMainIds, setPinnedMainIds] = useState<string[]>(() =>\n    readPinnedMainIds(),\n  );\n\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n  const [budgetByCategory, setBudgetByCategory] = useState<\n    Record<string, number>\n  >({});\n\n  useEffect(() => {\n    let cancelled = false;\n\n    void send(\'envelope-budget-month\', { month }).then(cells => {\n      if (cancelled) {\n        return;\n      }\n\n      const next: Record<string, number> = {};\n      for (const category of categories) {\n        const cell = cells.find(item =>\n          item.name.endsWith(`budget-${category.id}`),\n        );\n        next[category.id] = Number(cell?.value) || 0;\n      }\n      setBudgetByCategory(next);\n    });\n\n    return () => {\n      cancelled = true;\n    };\n  }, [categories, month]);\n\n  const transactionQuery = useMemo(\n    () =>\n      q(\'transactions\')\n        .options({ splits: \'all\' })\n        .filter({\n          date: { $transform: \'$month\', $eq: month },\n        })\n        .select(\'*\'),\n    [month],\n  );\n\n  const { transactions, isPending } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const categoryById = useMemo(\n    () => new Map(categories.map(category => [category.id, category])),\n    [categories],\n  );\n\n  const totals = useMemo(() => {\n    const byCategory = new Map<string, number>();\n    let expenses = 0;\n    let income = 0;\n\n    for (const transaction of transactions) {\n      if (\n        transaction.is_parent ||\n        transaction.tombstone ||\n        transaction.starting_balance_flag ||\n        !transaction.category\n      ) {\n        continue;\n      }\n\n      const category = categoryById.get(transaction.category);\n      if (!category || category.hidden) {\n        continue;\n      }\n\n      byCategory.set(\n        category.id,\n        (byCategory.get(category.id) ?? 0) + transaction.amount,\n      );\n\n      if (category.is_income) {\n        income += transaction.amount;\n      } else {\n        expenses += -transaction.amount;\n      }\n    }\n\n    return {\n      byCategory,\n      expenses: Math.max(0, expenses),\n      income: Math.max(0, income),\n    };\n  }, [categoryById, transactions]);\n\n\n  const predefinedExpensePairs = EXPENSE_CARDS.map(definition => ({\n    definition,\n    category: findCategory(categories, definition.candidates, false),\n  }));\n  const predefinedIncomePairs = INCOME_CARDS.map(definition => ({\n    definition,\n    category: findCategory(categories, definition.candidates, true),\n  }));\n\n  const usedCategoryIds = new Set(\n    [...predefinedExpensePairs, ...predefinedIncomePairs]\n      .map(pair => pair.category?.id)\n      .filter((id): id is string => Boolean(id)),\n  );\n\n  const hiddenLegacyNames = new Set([\n    \'general\',\n    \'bills flexible\',\n  ]);\n\n  const extraExpenseCategories = categories.filter(category => {\n    if (\n      category.hidden ||\n      category.is_income ||\n      usedCategoryIds.has(category.id) ||\n      hiddenLegacyNames.has(normalize(category.name))\n    ) {\n      return false;\n    }\n    const amount = Math.abs(totals.byCategory.get(category.id) ?? 0);\n    const budget = Math.abs(budgetByCategory[category.id] ?? 0);\n    return budget > 0 || amount > 0 || pinnedMainIds.includes(category.id);\n  });\n\n  const extraIncomeCategories = categories.filter(category => {\n    if (\n      category.hidden ||\n      !category.is_income ||\n      usedCategoryIds.has(category.id)\n    ) {\n      return false;\n    }\n    const amount = Math.abs(totals.byCategory.get(category.id) ?? 0);\n    return amount > 0 || pinnedMainIds.includes(category.id);\n  });\n\n  const visibleExpensePairs = [\n    ...predefinedExpensePairs,\n    ...extraExpenseCategories.map((category, index) => ({\n      definition: extraDefinition(category, index),\n      category,\n    })),\n  ];\n\n  const visibleIncomePairs = [\n    ...predefinedIncomePairs,\n    ...extraIncomeCategories.map((category, index) => ({\n      definition: extraDefinition(\n        category,\n        index + extraExpenseCategories.length,\n      ),\n      category,\n    })),\n  ];\n\n  const parentChoices = visibleExpensePairs.map(pair => pair.definition.label);\n\n  const monthlyReport = (() => {\n    const configured = readSubcategories();\n\n    const expenseRows = visibleExpensePairs\n      .filter(\n        (\n          pair,\n        ): pair is {\n          definition: CardDefinition;\n          category: CategoryEntity;\n        } => Boolean(pair.category),\n      )\n      .map(({ definition, category }) => {\n        const custom = configured[definition.label] ?? [];\n        const candidates = Array.from(\n          new Set([\n            ...(REPORT_SUBCATEGORIES_BY_CARD[definition.label] ?? []),\n            ...custom,\n          ]),\n        );\n\n        const bySubcategory = new Map<string, number>();\n        let uncategorized = 0;\n\n        for (const transaction of transactions) {\n          if (\n            transaction.is_parent ||\n            transaction.tombstone ||\n            transaction.starting_balance_flag ||\n            transaction.category !== category.id\n          ) {\n            continue;\n          }\n\n          const spending = -transaction.amount;\n          const matched = transactionSubcategory(\n            transaction.notes,\n            candidates,\n          );\n\n          if (matched) {\n            bySubcategory.set(\n              matched,\n              (bySubcategory.get(matched) ?? 0) + spending,\n            );\n          } else {\n            uncategorized += spending;\n          }\n        }\n\n        const subcategories = candidates\n          .map(name => ({\n            name,\n            amount: bySubcategory.get(name) ?? 0,\n            custom: custom.some(item => normalize(item) === normalize(name)),\n          }))\n          .filter(row => row.amount !== 0 || row.custom);\n\n        const spent = Math.max(\n          0,\n          -(totals.byCategory.get(category.id) ?? 0),\n        );\n\n        return {\n          id: category.id,\n          label: definition.label,\n          spent,\n          budget: Math.max(0, budgetByCategory[category.id] ?? 0),\n          subcategories,\n          uncategorized,\n        };\n      })\n      .filter(\n        row =>\n          row.spent !== 0 ||\n          row.budget !== 0 ||\n          row.subcategories.length > 0 ||\n          row.uncategorized !== 0,\n      );\n\n    const incomeRows = visibleIncomePairs\n      .filter(\n        (\n          pair,\n        ): pair is {\n          definition: CardDefinition;\n          category: CategoryEntity;\n        } => Boolean(pair.category),\n      )\n      .map(({ definition, category }) => ({\n        id: category.id,\n        label: definition.label,\n        amount: Math.max(0, totals.byCategory.get(category.id) ?? 0),\n      }))\n      .filter(row => row.amount !== 0);\n\n    return { expenseRows, incomeRows };\n  })();\n\n  const saveCategoryChoice = async () => {\n    const name = newCategoryName.trim();\n    if (!name) {\n      setCategoryMessage(\'Enter a name first.\');\n      return;\n    }\n\n    if (categoryMode === \'sub\') {\n      const all = readSubcategories();\n      const current = all[parentLabel] ?? [];\n      if (!current.some(item => normalize(item) === normalize(name))) {\n        all[parentLabel] = [...current, name];\n        writeSubcategories(all);\n      }\n      setCategoryMessage(`${name} is now a subcategory of ${parentLabel}.`);\n      setNewCategoryName(\'\');\n      return;\n    }\n\n    if (!categoryData) {\n      setCategoryMessage(\'Budget categories are still loading.\');\n      return;\n    }\n\n    const isIncome = categoryKind === \'income\';\n    const targetGroup = categoryData.grouped.find(\n      group => !group.hidden && Boolean(group.is_income) === isIncome,\n    );\n    if (!targetGroup) {\n      setCategoryMessage(\'No matching category group is available.\');\n      return;\n    }\n\n    const existing = categories.find(\n      category =>\n        !category.hidden &&\n        normalize(category.name) === normalize(name) &&\n        Boolean(category.is_income) === isIncome,\n    );\n    if (existing) {\n      const nextPinned = [...pinnedMainIds, existing.id];\n      writePinnedMainIds(nextPinned);\n      setPinnedMainIds(Array.from(new Set(nextPinned)));\n      setCategoryMessage(`${name} is already a main category.`);\n      return;\n    }\n\n    setSavingCategory(true);\n    try {\n      const id = await send(\'category-create\', {\n        name,\n        groupId: targetGroup.id,\n        isIncome,\n      });\n      const nextPinned = [...pinnedMainIds, id];\n      writePinnedMainIds(nextPinned);\n      setPinnedMainIds(Array.from(new Set(nextPinned)));\n      await queryClient.invalidateQueries({\n        queryKey: categoryQueries.all(),\n      });\n      setCategoryMessage(\n        `${name} created as a main category. Set its monthly budget in Budget.`,\n      );\n      setNewCategoryName(\'\');\n    } finally {\n      setSavingCategory(false);\n    }\n  };\n\n  const currentMonth = monthUtils.currentMonth();\n  const monthLabel =\n    month === currentMonth\n      ? \'This Month\'\n      : monthUtils.format(month, "MMMM \'\'yy", locale);\n\n  const openCard = (\n    definition: CardDefinition,\n    category?: CategoryEntity,\n  ) => {\n    const categoryId = category?.id ?? \'unmapped\';\n    const params = new URLSearchParams({\n      month,\n      label: definition.label,\n      income: category?.is_income ? \'1\' : \'0\',\n    });\n    void navigate(`/quick-category/${categoryId}?${params.toString()}`);\n  };\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        flexShrink: 0,\n        backgroundColor: \'#FFFFFF\',\n        color: \'#15151B\',\n        padding: \'calc(env(safe-area-inset-top) + 18px) 18px 132px\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          flexShrink: 0,\n          gap: 16,\n        }}\n      >\n        <View\n          style={{\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            justifyContent: \'space-between\',\n            flexShrink: 0,\n            minHeight: 44,\n          }}\n        >\n          <button\n            type="button"\n            onClick={() => setShowCategoryOrganizer(true)}\n            aria-label="Category / Subcategory"\n            style={{\n              width: 110,\n              border: 0,\n              background: \'transparent\',\n              color: \'#4D4B91\',\n              padding: \'4px 0\',\n              textAlign: \'left\',\n              fontSize: 12,\n              lineHeight: 1.05,\n              fontWeight: 850,\n              fontFamily: \'inherit\',\n              WebkitTapHighlightColor: \'transparent\',\n            }}\n          >\n            Category /\n            <br />\n            Subcategory\n          </button>\n\n          <View\n            style={{\n              flexDirection: \'row\',\n              alignItems: \'center\',\n              gap: 12,\n            }}\n          >\n            <button\n              type="button"\n              aria-label="Previous month"\n              onClick={() => setMonth(value => monthUtils.subMonths(value, 1))}\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronLeft width={20} height={20} />\n            </button>\n\n            <Text\n              style={{\n                fontSize: 20,\n                fontWeight: 800,\n                minWidth: 116,\n                textAlign: \'center\',\n                color: \'#111116\',\n              }}\n            >\n              {monthLabel}\n            </Text>\n\n            <button\n              type="button"\n              aria-label="Next month"\n              onClick={() => setMonth(value => monthUtils.addMonths(value, 1))}\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronRight width={20} height={20} />\n            </button>\n          </View>\n\n          <button\n            type="button"\n            aria-label="Accounts"\n            onClick={() => void navigate(\'/accounts\')}\n            style={{\n              border: 0,\n              background: \'transparent\',\n              color: \'#4D4B91\',\n              padding: 4,\n            }}\n          >\n            <SvgPiggyBank width={30} height={30} />\n          </button>\n        </View>\n\n        <View\n          style={{\n            flexShrink: 0,\n            alignItems: \'center\',\n            justifyContent: \'center\',\n            gap: 7,\n          }}\n        >\n          <Text style={{ fontSize: 20, fontWeight: 800 }}>\n            Expense {isPending ? \'…\' : format(totals.expenses, \'financial\')}\n          </Text>\n        </View>\n\n        {month === currentMonth && <RecurringIncomeCard />}\n\n        <div\n          style={{\n            display: \'grid\',\n            flexShrink: 0,\n            gridTemplateColumns: \'repeat(3, minmax(0, 1fr))\',\n            gap: 12,\n            width: \'100%\',\n          }}\n        >\n          {visibleExpensePairs.map(({ definition, category }) => (\n            <DashboardCard\n              key={`${definition.label}-${category?.id ?? \'unmapped\'}`}\n              definition={definition}\n              category={category}\n              month={month}\n              amount={\n                category ? (totals.byCategory.get(category.id) ?? 0) : 0\n              }\n              budget={category ? (budgetByCategory[category.id] ?? 0) : 0}\n              onOpen={() => openCard(definition, category)}\n            />\n          ))}\n        </div>\n\n        <View\n          style={{\n            flexShrink: 0,\n            alignItems: \'center\',\n            marginTop: 12,\n            gap: 3,\n          }}\n        >\n          <Text style={{ fontSize: 20, fontWeight: 800 }}>\n            Income {isPending ? \'…\' : format(totals.income, \'financial\')}\n          </Text>\n        </View>\n\n        <div\n          style={{\n            display: \'grid\',\n            flexShrink: 0,\n            gridTemplateColumns: \'repeat(3, minmax(0, 1fr))\',\n            gap: 12,\n            width: \'100%\',\n          }}\n        >\n          {visibleIncomePairs.map(({ definition, category }) => (\n            <DashboardCard\n              key={`${definition.label}-${category?.id ?? \'unmapped\'}`}\n              definition={definition}\n              category={category}\n              month={month}\n              amount={\n                category ? (totals.byCategory.get(category.id) ?? 0) : 0\n              }\n              budget={category ? (budgetByCategory[category.id] ?? 0) : 0}\n              onOpen={() => openCard(definition, category)}\n            />\n          ))}\n        </div>\n\n        <View\n          aria-hidden\n          style={{\n            height: 190,\n            flexShrink: 0,\n            pointerEvents: \'none\',\n          }}\n        />\n      </View>\n\n      {showMonthlyReport && (\n        <View\n          style={{\n            position: \'fixed\',\n            inset: 0,\n            zIndex: 120,\n            backgroundColor: \'#FFFFFF\',\n            overflowY: \'auto\',\n            padding:\n              \'calc(env(safe-area-inset-top) + 14px) 16px calc(env(safe-area-inset-bottom) + 28px)\',\n          }}\n        >\n          <View\n            style={{\n              width: \'100%\',\n              maxWidth: 760,\n              alignSelf: \'center\',\n              gap: 16,\n            }}\n          >\n            <View\n              style={{\n                flexDirection: \'row\',\n                alignItems: \'center\',\n                justifyContent: \'space-between\',\n              }}\n            >\n              <button\n                type="button"\n                aria-label="Close report"\n                onClick={() => setShowMonthlyReport(false)}\n                style={{\n                  border: 0,\n                  background: \'transparent\',\n                  color: \'#111116\',\n                  fontSize: 32,\n                  lineHeight: 1,\n                  padding: 6,\n                }}\n              >\n                ×\n              </button>\n\n              <View style={{ alignItems: \'center\', gap: 2 }}>\n                <Text style={{ fontSize: 22, fontWeight: 900 }}>\n                  Monthly Report\n                </Text>\n                <Text\n                  style={{\n                    color: \'#6F7079\',\n                    fontSize: 13,\n                    fontWeight: 750,\n                  }}\n                >\n                  {monthLabel}\n                </Text>\n              </View>\n\n              <View style={{ width: 44 }} />\n            </View>\n\n            <View\n              style={{\n                flexDirection: \'row\',\n                gap: 10,\n              }}\n            >\n              <View\n                style={{\n                  flex: 1,\n                  borderRadius: 18,\n                  backgroundColor: \'#FFF2D5\',\n                  padding: 14,\n                }}\n              >\n                <Text style={{ color: \'#7C7467\', fontSize: 12, fontWeight: 750 }}>\n                  EXPENSES\n                </Text>\n                <Text style={{ marginTop: 3, fontSize: 22, fontWeight: 900 }}>\n                  {format(totals.expenses, \'financial\')}\n                </Text>\n              </View>\n              <View\n                style={{\n                  flex: 1,\n                  borderRadius: 18,\n                  backgroundColor: \'#D9F8F2\',\n                  padding: 14,\n                }}\n              >\n                <Text style={{ color: \'#5D7772\', fontSize: 12, fontWeight: 750 }}>\n                  INCOME\n                </Text>\n                <Text style={{ marginTop: 3, fontSize: 22, fontWeight: 900 }}>\n                  {format(totals.income, \'financial\')}\n                </Text>\n              </View>\n            </View>\n\n            <View style={{ gap: 12 }}>\n              {monthlyReport.expenseRows.map(row => {\n                const left = row.budget - row.spent;\n                return (\n                  <View\n                    key={row.id}\n                    style={{\n                      border: \'1px solid #ECEAF2\',\n                      borderRadius: 18,\n                      backgroundColor: \'#FFFFFF\',\n                      padding: 14,\n                      gap: 10,\n                    }}\n                  >\n                    <View\n                      style={{\n                        flexDirection: \'row\',\n                        justifyContent: \'space-between\',\n                        gap: 12,\n                      }}\n                    >\n                      <View style={{ flex: 1 }}>\n                        <Text style={{ fontSize: 16, fontWeight: 900 }}>\n                          {row.label}\n                        </Text>\n                        {row.budget > 0 && (\n                          <Text\n                            style={{\n                              marginTop: 2,\n                              color: left < 0 ? \'#C93645\' : \'#747783\',\n                              fontSize: 11,\n                              fontWeight: 700,\n                            }}\n                          >\n                            Budget {format(row.budget, \'financial\')} ·{\' \'}\n                            {format(Math.abs(left), \'financial\')}{\' \'}\n                            {left >= 0 ? \'left\' : \'over\'}\n                          </Text>\n                        )}\n                      </View>\n                      <Text style={{ fontSize: 17, fontWeight: 900 }}>\n                        {format(row.spent, \'financial\')}\n                      </Text>\n                    </View>\n\n                    {(row.subcategories.length > 0 ||\n                      row.uncategorized !== 0) && (\n                      <View\n                        style={{\n                          borderTop: \'1px solid #F0EFF4\',\n                          paddingTop: 8,\n                          gap: 7,\n                        }}\n                      >\n                        {row.subcategories.map(subcategory => (\n                          <View\n                            key={subcategory.name}\n                            style={{\n                              flexDirection: \'row\',\n                              justifyContent: \'space-between\',\n                              gap: 12,\n                            }}\n                          >\n                            <Text\n                              style={{\n                                color: \'#5F6069\',\n                                fontSize: 13,\n                                fontWeight: 700,\n                              }}\n                            >\n                              {subcategory.name}\n                            </Text>\n                            <Text\n                              style={{\n                                color:\n                                  subcategory.amount === 0\n                                    ? \'#A1A2A9\'\n                                    : \'#17171C\',\n                                fontSize: 13,\n                                fontWeight: 800,\n                              }}\n                            >\n                              {format(subcategory.amount, \'financial\')}\n                            </Text>\n                          </View>\n                        ))}\n\n                        {row.uncategorized !== 0 && (\n                          <View\n                            style={{\n                              flexDirection: \'row\',\n                              justifyContent: \'space-between\',\n                              gap: 12,\n                            }}\n                          >\n                            <Text\n                              style={{\n                                color: \'#A86600\',\n                                fontSize: 13,\n                                fontWeight: 800,\n                              }}\n                            >\n                              Uncategorized\n                            </Text>\n                            <Text\n                              style={{\n                                color: \'#A86600\',\n                                fontSize: 13,\n                                fontWeight: 850,\n                              }}\n                            >\n                              {format(row.uncategorized, \'financial\')}\n                            </Text>\n                          </View>\n                        )}\n                      </View>\n                    )}\n                  </View>\n                );\n              })}\n            </View>\n\n            {monthlyReport.incomeRows.length > 0 && (\n              <View\n                style={{\n                  border: \'1px solid #DDEFEA\',\n                  borderRadius: 18,\n                  backgroundColor: \'#F6FCFA\',\n                  padding: 14,\n                  gap: 8,\n                }}\n              >\n                <Text style={{ fontSize: 16, fontWeight: 900 }}>\n                  Income\n                </Text>\n                {monthlyReport.incomeRows.map(row => (\n                  <View\n                    key={row.id}\n                    style={{\n                      flexDirection: \'row\',\n                      justifyContent: \'space-between\',\n                      gap: 12,\n                    }}\n                  >\n                    <Text\n                      style={{\n                        color: \'#5F6069\',\n                        fontSize: 13,\n                        fontWeight: 700,\n                      }}\n                    >\n                      {row.label}\n                    </Text>\n                    <Text style={{ fontSize: 13, fontWeight: 850 }}>\n                      {format(row.amount, \'financial\')}\n                    </Text>\n                  </View>\n                ))}\n              </View>\n            )}\n\n            <Text\n              style={{\n                color: \'#777A83\',\n                fontSize: 11,\n                lineHeight: 1.45,\n                textAlign: \'center\',\n              }}\n            >\n              Subcategory amounts come from the transactions in this month.\n              Any transaction without a subcategory is shown as Uncategorized,\n              so the category total is never hidden.\n            </Text>\n          </View>\n        </View>\n      )}\n\n      {showCategoryOrganizer && (\n        <View\n          style={{\n            position: \'fixed\',\n            zIndex: 1300,\n            inset: 0,\n            backgroundColor: \'rgba(20, 20, 30, 0.38)\',\n            alignItems: \'center\',\n            justifyContent: \'flex-end\',\n          }}\n        >\n          <View\n            style={{\n              width: \'100%\',\n              maxWidth: 760,\n              backgroundColor: \'#FFFFFF\',\n              borderTopLeftRadius: 28,\n              borderTopRightRadius: 28,\n              padding: \'22px 20px calc(22px + env(safe-area-inset-bottom))\',\n              gap: 14,\n              boxShadow: \'0 -18px 48px rgba(0,0,0,0.14)\',\n            }}\n          >\n            <View\n              style={{\n                flexDirection: \'row\',\n                justifyContent: \'space-between\',\n                alignItems: \'center\',\n              }}\n            >\n              <Text style={{ fontSize: 22, fontWeight: 850 }}>\n                Add category\n              </Text>\n              <button\n                type="button"\n                aria-label="Close"\n                onClick={() => {\n                  setShowCategoryOrganizer(false);\n                  setCategoryMessage(\'\');\n                }}\n                style={{\n                  border: 0,\n                  background: \'transparent\',\n                  fontSize: 28,\n                  lineHeight: 1,\n                }}\n              >\n                ×\n              </button>\n            </View>\n\n            <input\n              value={newCategoryName}\n              onChange={event => setNewCategoryName(event.target.value)}\n              placeholder="Example: Hair Cut or Mortgage"\n              style={{\n                height: 48,\n                borderRadius: 14,\n                border: \'1px solid #D9D9E2\',\n                padding: \'0 14px\',\n                fontSize: 16,\n              }}\n            />\n\n            <View style={{ flexDirection: \'row\', gap: 8 }}>\n              <button\n                type="button"\n                onClick={() => setCategoryMode(\'sub\')}\n                style={{\n                  flex: 1,\n                  border: 0,\n                  borderRadius: 14,\n                  padding: 12,\n                  background:\n                    categoryMode === \'sub\' ? \'#FFD954\' : \'#F1F1F4\',\n                  color: \'#333\',\n                  fontWeight: 800,\n                }}\n              >\n                Subcategory\n              </button>\n              <button\n                type="button"\n                onClick={() => setCategoryMode(\'main\')}\n                style={{\n                  flex: 1,\n                  border: 0,\n                  borderRadius: 14,\n                  padding: 12,\n                  background:\n                    categoryMode === \'main\' ? \'#FFD954\' : \'#F1F1F4\',\n                  color: \'#333\',\n                  fontWeight: 800,\n                }}\n              >\n                New Home Card\n              </button>\n            </View>\n\n            {categoryMode === \'sub\' ? (\n              <>\n                <Text style={{ fontSize: 13, fontWeight: 750, color: \'#6D6F79\' }}>\n                  Assign it under:\n                </Text>\n                <select\n                  value={parentLabel}\n                  onChange={event => setParentLabel(event.target.value)}\n                  style={{\n                    height: 48,\n                    borderRadius: 14,\n                    border: \'1px solid #D9D9E2\',\n                    background: \'#fff\',\n                    padding: \'0 12px\',\n                    fontSize: 15,\n                  }}\n                >\n                  {parentChoices.map(label => (\n                    <option key={label} value={label}>\n                      {label}\n                    </option>\n                  ))}\n                </select>\n                <Text style={{ fontSize: 12, color: \'#7D7F88\' }}>\n                  A subcategory does not create another Home card. Its spending\n                  stays inside the parent category budget.\n                </Text>\n              </>\n            ) : (\n              <>\n                <View style={{ flexDirection: \'row\', gap: 8 }}>\n                  <button\n                    type="button"\n                    onClick={() => setCategoryKind(\'expense\')}\n                    style={{\n                      flex: 1,\n                      border:\n                        categoryKind === \'expense\'\n                          ? \'2px solid #4D4B91\'\n                          : \'1px solid #D9D9E2\',\n                      borderRadius: 12,\n                      background: \'#fff\',\n                      padding: 10,\n                      fontWeight: 800,\n                    }}\n                  >\n                    Expense\n                  </button>\n                  <button\n                    type="button"\n                    onClick={() => setCategoryKind(\'income\')}\n                    style={{\n                      flex: 1,\n                      border:\n                        categoryKind === \'income\'\n                          ? \'2px solid #4D4B91\'\n                          : \'1px solid #D9D9E2\',\n                      borderRadius: 12,\n                      background: \'#fff\',\n                      padding: 10,\n                      fontWeight: 800,\n                    }}\n                  >\n                    Income\n                  </button>\n                </View>\n                <Text style={{ fontSize: 12, color: \'#7D7F88\' }}>\n                  A new main category gets its own Home card. Set its monthly\n                  amount later from Budget.\n                </Text>\n              </>\n            )}\n\n            {categoryMessage && (\n              <Text\n                style={{\n                  fontSize: 12,\n                  fontWeight: 700,\n                  color: \'#4D4B91\',\n                }}\n              >\n                {categoryMessage}\n              </Text>\n            )}\n\n            <button\n              type="button"\n              disabled={savingCategory}\n              onClick={() => void saveCategoryChoice()}\n              style={{\n                border: 0,\n                borderRadius: 16,\n                background: \'#4D4B91\',\n                color: \'#fff\',\n                padding: 14,\n                fontSize: 15,\n                fontWeight: 850,\n              }}\n            >\n              {savingCategory ? \'Saving…\' : \'Save\'}\n            </button>\n          </View>\n        </View>\n      )}\n    </View>\n  );\n}\n'
QUICK_CATEGORY_TSX = 'import React, { useEffect, useMemo, useRef, useState } from \'react\';\nimport { useParams, useSearchParams } from \'react-router\';\n\nimport {\n  SvgCalendar,\n  SvgList,\n  SvgPiggyBank,\n} from \'@actual-app/components/icons/v1\';\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport { send } from \'@actual-app/core/platform/client/connection\';\nimport * as monthUtils from \'@actual-app/core/shared/months\';\nimport { q } from \'@actual-app/core/shared/query\';\nimport { amountToInteger } from \'@actual-app/core/shared/util\';\nimport type { CategoryEntity } from \'@actual-app/core/types/models\';\nimport { useQueryClient } from \'@tanstack/react-query\';\n\nimport { categoryQueries } from \'#budget\';\nimport { useAccounts } from \'#hooks/useAccounts\';\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useNavigate } from \'#hooks/useNavigate\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\nconst QUICK_TAGS_BY_CARD: Record<string, string[]> = {\n  \'Food & Drink\': [\n    \'Breakfast\',\n    \'Lunch\',\n    \'Dinner\',\n    \'Snacks\',\n    \'Coffee\',\n    \'Groceries\',\n  ],\n  Transport: [\n    \'Gas\',\n    \'Parking\',\n    \'Public Transit\',\n    \'Tolls\',\n    \'Maintenance\',\n    \'Car Payment\',\n    \'Auto Insurance\',\n  ],\n  \'Home Bills\': [\n    \'Mortgage\',\n    \'Rent\',\n    \'Electric\',\n    \'Gas (Home)\',\n    \'Phone\',\n    \'Cable\',\n    \'Internet\',\n    \'Water\',\n  ],\n  \'Self-Care\': [\n    \'Hair\',\n    \'Barber\',\n    \'Nails\',\n    \'Skincare\',\n    \'Gym\',\n    \'Spa\',\n    \'Beauty\',\n  ],\n  Shopping: [\n    \'Clothing\',\n    \'Shoes\',\n    \'Electronics\',\n    \'Household\',\n    \'Gifts\',\n    \'Online\',\n  ],\n  Health: [\n    \'Doctor\',\n    \'Pharmacy\',\n    \'Dental\',\n    \'Vision\',\n    \'Therapy\',\n    \'Insurance\',\n  ],\n  Salary: [\n    \'Paycheck\',\n    \'Overtime\',\n    \'Bonus\',\n    \'Commission\',\n    \'Tips\',\n  ],\n  Freelance: [\n    \'Client\',\n    \'Project\',\n    \'Contract\',\n    \'Side Job\',\n    \'Reimbursement\',\n  ],\n  Investment: [\n    \'Dividends\',\n    \'Interest\',\n    \'Stocks\',\n    \'ETF\',\n    \'Crypto\',\n    \'Retirement\',\n  ],\n};\n\nconst DEFAULT_QUICK_TAGS = [\'Other\'];\n\nconst SUBCATEGORY_STORAGE_KEY = \'budget-local-subcategories-v1\';\n\nfunction normalizeSubcategory(value: string) {\n  return value\n    .toLowerCase()\n    .normalize(\'NFD\')\n    .replace(/[\\u0300-\\u036f]/g, \'\')\n    .replace(/[^a-z0-9]+/g, \' \')\n    .trim();\n}\n\n\nfunction subcategorySlug(value: string) {\n  return normalizeSubcategory(value).replace(/\\s+/g, \'\');\n}\n\nfunction transactionSubcategory(\n  notes: string | null | undefined,\n  candidates: string[],\n) {\n  if (!notes || candidates.length === 0) return undefined;\n\n  const tokens = notes\n    .split(/\\s+/)\n    .filter(token => token.startsWith(\'#\'))\n    .map(token => token.slice(1));\n\n  for (const candidate of candidates) {\n    const slug = subcategorySlug(candidate);\n    if (\n      tokens.some(token => {\n        const clean = token.toLowerCase().startsWith(\'sub:\')\n          ? token.slice(4)\n          : token;\n        return subcategorySlug(clean) === slug;\n      })\n    ) {\n      return candidate;\n    }\n  }\n\n  return undefined;\n}\n\nfunction noteHasSubcategory(notes: string, candidate: string) {\n  return transactionSubcategory(notes, [candidate]) === candidate;\n}\n\nfunction readCustomSubcategories(): Record<string, string[]> {\n  try {\n    const raw = window.localStorage.getItem(SUBCATEGORY_STORAGE_KEY);\n    if (!raw) return {};\n    const parsed = JSON.parse(raw) as Record<string, unknown>;\n    const clean: Record<string, string[]> = {};\n    for (const [key, value] of Object.entries(parsed)) {\n      if (Array.isArray(value)) {\n        clean[key] = value.filter(item => typeof item === \'string\') as string[];\n      }\n    }\n    return clean;\n  } catch {\n    return {};\n  }\n}\n\nfunction writeCustomSubcategories(value: Record<string, string[]>) {\n  window.localStorage.setItem(SUBCATEGORY_STORAGE_KEY, JSON.stringify(value));\n}\n\nfunction formatEntryAmount(raw: string) {\n  const numeric = Number(raw || \'0\');\n  return Number.isFinite(numeric) ? numeric : 0;\n}\n\nexport function QuickCategoryPage() {\n  const navigate = useNavigate();\n  const format = useFormat();\n  const { categoryId = \'unmapped\' } = useParams();\n  const [searchParams] = useSearchParams();\n\n  const month = searchParams.get(\'month\') || monthUtils.currentMonth();\n  const fallbackLabel = searchParams.get(\'label\') || \'Category\';\n  const incomeFallback = searchParams.get(\'income\') === \'1\';\n\n  const queryClient = useQueryClient();\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n  const mappedCategory = categories.find(category => category.id === categoryId);\n  const [selectedCategoryId, setSelectedCategoryId] = useState(\n    mappedCategory?.id ?? \'\',\n  );\n\n  useEffect(() => {\n    if (mappedCategory?.id) {\n      setSelectedCategoryId(mappedCategory.id);\n    }\n  }, [mappedCategory?.id]);\n\n  const creationAttempted = useRef(false);\n  const [creatingCategory, setCreatingCategory] = useState(false);\n\n  useEffect(() => {\n    if (\n      categoryId !== \'unmapped\' ||\n      selectedCategoryId ||\n      creationAttempted.current ||\n      !categoryData ||\n      categories.length === 0\n    ) {\n      return;\n    }\n\n    const exactExisting = categories.find(\n      category =>\n        !category.hidden &&\n        category.name.toLowerCase() === fallbackLabel.toLowerCase() &&\n        Boolean(category.is_income) === incomeFallback,\n    );\n\n    if (exactExisting) {\n      setSelectedCategoryId(exactExisting.id);\n      return;\n    }\n\n    const targetGroup = categoryData.grouped.find(\n      group =>\n        !group.hidden && Boolean(group.is_income) === Boolean(incomeFallback),\n    );\n\n    if (!targetGroup) {\n      return;\n    }\n\n    creationAttempted.current = true;\n    setCreatingCategory(true);\n\n    void send(\'category-create\', {\n      name: fallbackLabel,\n      groupId: targetGroup.id,\n      isIncome: incomeFallback,\n    })\n      .then(async id => {\n        setSelectedCategoryId(id);\n        await queryClient.invalidateQueries({\n          queryKey: categoryQueries.all(),\n        });\n      })\n      .finally(() => {\n        setCreatingCategory(false);\n      });\n  }, [\n    categoryData,\n    categories,\n    categoryId,\n    fallbackLabel,\n    incomeFallback,\n    queryClient,\n    selectedCategoryId,\n  ]);\n\n  const selectedCategory =\n    categories.find(category => category.id === selectedCategoryId) ??\n    mappedCategory;\n\n  const effectiveCategoryId = selectedCategory?.id || selectedCategoryId;\n  const isIncome = selectedCategory?.is_income ?? incomeFallback;\n  const [customSubcategories, setCustomSubcategories] = useState<string[]>(\n    () => readCustomSubcategories()[fallbackLabel] ?? [],\n  );\n  const [showSubcategoryManager, setShowSubcategoryManager] = useState(false);\n  const [showBreakdown, setShowBreakdown] = useState(false);\n  const [newSubcategoryName, setNewSubcategoryName] = useState(\'\');\n\n  useEffect(() => {\n    setCustomSubcategories(\n      readCustomSubcategories()[fallbackLabel] ?? [],\n    );\n  }, [fallbackLabel]);\n\n  const mainCategoryNames = new Set(\n    categories\n      .filter(category => category.id !== effectiveCategoryId)\n      .map(category => normalizeSubcategory(category.name)),\n  );\n\n  const quickTags = Array.from(\n    new Set([\n      ...(QUICK_TAGS_BY_CARD[fallbackLabel] ?? DEFAULT_QUICK_TAGS),\n      ...customSubcategories,\n    ]),\n  ).filter(tag => !mainCategoryNames.has(normalizeSubcategory(tag)));\n\n  const title = fallbackLabel;\n\n  const addSubcategory = () => {\n    const name = newSubcategoryName.trim();\n    if (!name) return;\n    const all = readCustomSubcategories();\n    const current = all[fallbackLabel] ?? [];\n    if (!current.some(item => normalizeSubcategory(item) === normalizeSubcategory(name))) {\n      all[fallbackLabel] = [...current, name];\n      writeCustomSubcategories(all);\n      setCustomSubcategories(all[fallbackLabel]);\n    }\n    setNewSubcategoryName(\'\');\n  };\n\n  const removeSubcategory = (name: string) => {\n    const all = readCustomSubcategories();\n    all[fallbackLabel] = (all[fallbackLabel] ?? []).filter(\n      item => normalizeSubcategory(item) !== normalizeSubcategory(name),\n    );\n    writeCustomSubcategories(all);\n    setCustomSubcategories(all[fallbackLabel]);\n  };\n\n  const { data: accounts = [] } = useAccounts();\n  const availableAccounts = accounts.filter(\n    account => !account.closed && !account.tombstone,\n  );\n  const [accountId, setAccountId] = useState(\'\');\n\n  useEffect(() => {\n    if (!accountId && availableAccounts.length > 0) {\n      const preferred =\n        availableAccounts.find(account => account.offbudget === 0) ??\n        availableAccounts[0];\n      setAccountId(preferred.id);\n    }\n  }, [accountId, availableAccounts]);\n\n  const transactionQuery = useMemo(() => {\n    if (!effectiveCategoryId) {\n      return undefined;\n    }\n    return q(\'transactions\')\n      .options({ splits: \'inline\' })\n      .filter({\n        category: effectiveCategoryId,\n        date: { $transform: \'$month\', $eq: month },\n      })\n      .select(\'*\');\n  }, [effectiveCategoryId, month]);\n\n  const { transactions } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const monthTotal = useMemo(\n    () =>\n      transactions\n        .filter(\n          transaction =>\n            !transaction.is_parent &&\n            !transaction.tombstone &&\n            !transaction.starting_balance_flag,\n        )\n        .reduce((sum, transaction) => sum + transaction.amount, 0),\n    [transactions],\n  );\n\n  const monthDisplay = selectedCategory?.is_income\n    ? Math.max(0, monthTotal)\n    : Math.max(0, -monthTotal);\n\n  const subcategoryBreakdown = useMemo(() => {\n    const candidates = quickTags.filter(\n      tag =>\n        normalizeSubcategory(tag) !== \'other\' ||\n        customSubcategories.some(\n          custom => normalizeSubcategory(custom) === normalizeSubcategory(tag),\n        ),\n    );\n\n    const totals = new Map<string, number>();\n    const counts = new Map<string, number>();\n    let uncategorized = 0;\n    let uncategorizedCount = 0;\n\n    for (const transaction of transactions) {\n      if (\n        transaction.is_parent ||\n        transaction.tombstone ||\n        transaction.starting_balance_flag\n      ) {\n        continue;\n      }\n\n      const displayAmount = isIncome\n        ? transaction.amount\n        : -transaction.amount;\n\n      const matched = transactionSubcategory(\n        transaction.notes,\n        candidates,\n      );\n\n      if (matched) {\n        totals.set(matched, (totals.get(matched) ?? 0) + displayAmount);\n        counts.set(matched, (counts.get(matched) ?? 0) + 1);\n      } else {\n        uncategorized += displayAmount;\n        uncategorizedCount += 1;\n      }\n    }\n\n    return {\n      rows: candidates.map(name => ({\n        name,\n        amount: totals.get(name) ?? 0,\n        count: counts.get(name) ?? 0,\n      })),\n      uncategorized,\n      uncategorizedCount,\n    };\n  }, [customSubcategories, isIncome, quickTags, transactions]);\n\n  const reportMonthLabel = monthUtils.format(month, "MMMM yyyy");\n  const visibleBreakdownRows = subcategoryBreakdown.rows.filter(\n    row => row.amount !== 0,\n  );\n  const compactBreakdownRows = visibleBreakdownRows.slice(0, 4);\n  const hiddenBreakdownCount = Math.max(\n    0,\n    visibleBreakdownRows.length - compactBreakdownRows.length,\n  );\n\n  const [budgetAmount, setBudgetAmount] = useState(0);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    if (!effectiveCategoryId || isIncome) {\n      setBudgetAmount(0);\n      return;\n    }\n\n    void send(\'envelope-budget-month\', { month }).then(cells => {\n      if (cancelled) {\n        return;\n      }\n      const cell = cells.find(item =>\n        item.name.endsWith(`budget-${effectiveCategoryId}`),\n      );\n      setBudgetAmount(Number(cell?.value) || 0);\n    });\n\n    return () => {\n      cancelled = true;\n    };\n  }, [effectiveCategoryId, isIncome, month]);\n\n  const amountLeft = budgetAmount - monthDisplay;\n  const spentPercent =\n    budgetAmount > 0 ? Math.max(0, (monthDisplay / budgetAmount) * 100) : 0;\n  const leftPercent =\n    budgetAmount > 0 ? Math.max(0, 100 - spentPercent) : 0;\n\n  const [amount, setAmount] = useState(\'0\');\n  const [note, setNote] = useState(\'\');\n  const [showNote, setShowNote] = useState(false);\n  const [showAccount, setShowAccount] = useState(false);\n  const [date, setDate] = useState(() => monthUtils.currentDay());\n  const [saving, setSaving] = useState(false);\n  const [message, setMessage] = useState(\'\');\n\n  const displayAmount = format(\n    amountToInteger(formatEntryAmount(amount)),\n    \'financial\',\n  );\n\n  const pressKey = (key: string) => {\n    setMessage(\'\');\n    if (key === \'back\') {\n      setAmount(value => (value.length <= 1 ? \'0\' : value.slice(0, -1)));\n      return;\n    }\n    if (key === \'clear\') {\n      setAmount(\'0\');\n      return;\n    }\n    if (key === \'.\') {\n      setAmount(value => (value.includes(\'.\') ? value : `${value}.`));\n      return;\n    }\n    setAmount(value => {\n      const next = value === \'0\' ? key : `${value}${key}`;\n      const [, decimals = \'\'] = next.split(\'.\');\n      return decimals.length > 2 ? value : next;\n    });\n  };\n\n  const addTag = (tag: string) => {\n    const token = `#sub:${subcategorySlug(tag)}`;\n\n    setNote(value => {\n      const candidateSlugs = new Set(\n        quickTags.map(candidate => subcategorySlug(candidate)),\n      );\n\n      const keep = value\n        .trim()\n        .split(/\\s+/)\n        .filter(Boolean)\n        .filter(part => {\n          if (!part.startsWith(\'#\')) return true;\n          const raw = part.slice(1);\n          const clean = raw.toLowerCase().startsWith(\'sub:\')\n            ? raw.slice(4)\n            : raw;\n          return !candidateSlugs.has(subcategorySlug(clean));\n        });\n\n      return [...keep, token].join(\' \');\n    });\n  };\n\n\n  const saveTransaction = async () => {\n    if (!effectiveCategoryId) {\n      setMessage(creatingCategory ? \'Preparing category…\' : \'Category is not ready yet.\');\n      return;\n    }\n    if (!accountId) {\n      setMessage(\'Choose an account first.\');\n      setShowAccount(true);\n      return;\n    }\n\n    const integerAmount = amountToInteger(formatEntryAmount(amount));\n    if (integerAmount <= 0) {\n      setMessage(\'Enter an amount first.\');\n      return;\n    }\n\n    setSaving(true);\n    try {\n      await send(\'api/transactions-add\', {\n        accountId,\n        transactions: [\n          {\n            date,\n            amount: isIncome ? integerAmount : -integerAmount,\n            category: effectiveCategoryId,\n            notes: note.trim() || undefined,\n            cleared: false,\n          },\n        ],\n      });\n      void navigate(\'/home\', { replace: true });\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  const toolbarButton = (\n    label: string,\n    icon: React.ReactNode,\n    active: boolean,\n    onClick: () => void,\n  ) => (\n    <button\n      type="button"\n      onClick={onClick}\n      style={{\n        border: 0,\n        background: active ? \'#FFF2B8\' : \'transparent\',\n        color: \'#4D4B91\',\n        borderRadius: 12,\n        minWidth: 0,\n        padding: \'7px 4px\',\n        display: \'flex\',\n        flexDirection: \'column\',\n        alignItems: \'center\',\n        gap: 3,\n        fontSize: 10,\n        fontWeight: 750,\n      }}\n    >\n      {icon}\n      {label}\n    </button>\n  );\n\n  const keys = [\'7\', \'8\', \'9\', \'back\', \'4\', \'5\', \'6\', \'clear\', \'1\', \'2\', \'3\', \'.\', \'0\'];\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        backgroundColor: \'#D5D5D5\',\n        padding: \'calc(env(safe-area-inset-top) + 8px) 0 env(safe-area-inset-bottom)\',\n      }}\n    >\n      <View\n        style={{\n          minHeight: \'calc(100vh - env(safe-area-inset-top))\',\n          width: \'100%\',\n          backgroundColor: \'#FFFFFF\',\n          borderTopLeftRadius: 34,\n          borderTopRightRadius: 34,\n          overflowX: \'hidden\',\n          overflowY: \'visible\',\n          padding: \'12px 18px 28px\',\n        }}\n      >\n        <View\n          style={{\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            justifyContent: \'space-between\',\n            minHeight: 52,\n          }}\n        >\n          <button\n            type="button"\n            aria-label="Close"\n            onClick={() => void navigate(\'/home\')}\n            style={{\n              border: 0,\n              background: \'transparent\',\n              fontSize: 31,\n              lineHeight: 1,\n              padding: 6,\n              color: \'#111\',\n            }}\n          >\n            ×\n          </button>\n\n          <Text\n            style={{\n              flex: 1,\n              textAlign: \'center\',\n              fontSize: 24,\n              fontWeight: 850,\n              color: \'#111\',\n            }}\n          >\n            {title}\n          </Text>\n\n          <button\n            type="button"\n            aria-label="Open category transactions"\n            onClick={() => {\n              if (effectiveCategoryId) {\n                void navigate(`/categories/${effectiveCategoryId}?month=${month}`);\n              }\n            }}\n            style={{\n              border: 0,\n              width: 42,\n              height: 42,\n              borderRadius: 999,\n              background: \'#F0EDFF\',\n              color: \'#4D4B91\',\n              display: \'flex\',\n              alignItems: \'center\',\n              justifyContent: \'center\',\n            }}\n          >\n            <SvgList width={23} height={23} />\n          </button>\n        </View>\n\n        <View\n          style={{\n            flex: 1,\n            minHeight: 285,\n            alignItems: \'center\',\n            justifyContent: \'center\',\n            gap: 18,\n          }}\n        >\n          <Text\n            style={{\n              fontSize: 56,\n              lineHeight: 1,\n              fontWeight: 500,\n              color: \'#050505\',\n              letterSpacing: \'-0.045em\',\n            }}\n          >\n            {displayAmount}\n          </Text>\n\n          {!isIncome && (\n            <View\n              style={{\n                width: \'calc(100% + 36px)\',\n                marginLeft: -18,\n                marginRight: -18,\n                marginTop: 18,\n              }}\n            >\n              {budgetAmount > 0 ? (\n                <>\n                  <View\n                    style={{\n                      width: \'100%\',\n                      height: 50,\n                      flexDirection: \'row\',\n                      overflow: \'hidden\',\n                      backgroundColor: \'#CFF0E6\',\n                    }}\n                  >\n                    <View\n                      style={{\n                        width: `${Math.min(100, spentPercent)}%`,\n                        minWidth: monthDisplay > 0 ? 78 : 0,\n                        backgroundColor:\n                          amountLeft < 0 ? \'#E56B73\' : \'#43CE9A\',\n                        justifyContent: \'center\',\n                        paddingLeft: 12,\n                      }}\n                    >\n                      {monthDisplay > 0 && (\n                        <>\n                          <Text\n                            style={{\n                              color: \'#FFFFFF\',\n                              fontSize: 15,\n                              fontWeight: 850,\n                            }}\n                          >\n                            {format(monthDisplay, \'financial\')}\n                          </Text>\n                          <Text\n                            style={{\n                              color: \'#FFFFFF\',\n                              fontSize: 11,\n                              fontWeight: 750,\n                            }}\n                          >\n                            {spentPercent.toFixed(2)}% Spent\n                          </Text>\n                        </>\n                      )}\n                    </View>\n                    <View\n                      style={{\n                        flex: 1,\n                        alignItems: \'flex-end\',\n                        justifyContent: \'center\',\n                        paddingRight: 14,\n                      }}\n                    >\n                      <Text\n                        style={{\n                          color: amountLeft < 0 ? \'#C93645\' : \'#218565\',\n                          fontSize: 15,\n                          fontWeight: 850,\n                        }}\n                      >\n                        {format(Math.abs(amountLeft), \'financial\')}\n                      </Text>\n                      <Text\n                        style={{\n                          color: amountLeft < 0 ? \'#C93645\' : \'#218565\',\n                          fontSize: 11,\n                          fontWeight: 750,\n                        }}\n                      >\n                        {amountLeft >= 0\n                          ? `${leftPercent.toFixed(2)}% Left`\n                          : `${Math.abs(100 - leftPercent).toFixed(2)}% Over`}\n                      </Text>\n                    </View>\n                  </View>\n                  <View\n                    style={{\n                      paddingTop: 7,\n                      alignItems: \'center\',\n                    }}\n                  >\n                    <Text\n                      style={{\n                        color: \'#777A83\',\n                        fontSize: 11,\n                        fontWeight: 700,\n                      }}\n                    >\n                      Monthly budget: {format(budgetAmount, \'financial\')} · edit\n                      it only in Budget\n                    </Text>\n                  </View>\n                </>\n              ) : (\n                <View\n                  style={{\n                    backgroundColor: \'#F2F2F4\',\n                    padding: \'11px 14px\',\n                    alignItems: \'center\',\n                  }}\n                >\n                  <Text\n                    style={{\n                      color: \'#777A83\',\n                      fontSize: 12,\n                      fontWeight: 700,\n                    }}\n                  >\n                    No monthly budget set · set it in Budget\n                  </Text>\n                </View>\n              )}\n            </View>\n          )}\n\n          {isIncome && (\n            <Text\n              style={{\n                color: \'#777A83\',\n                fontSize: 13,\n                fontWeight: 650,\n              }}\n            >\n              Received this month: {format(monthDisplay, \'financial\')}\n            </Text>\n          )}\n\n          {message && (\n            <Text\n              style={{\n                color: message.includes(\'saved\') ? \'#167A59\' : \'#8A6112\',\n                fontSize: 12,\n                fontWeight: 700,\n                textAlign: \'center\',\n              }}\n            >\n              {message}\n            </Text>\n          )}\n        </View>\n\n        {!isIncome && (\n          <View\n            style={{\n              flexShrink: 0,\n              border: \'1px solid #ECEAF2\',\n              borderRadius: 16,\n              backgroundColor: \'#FAFAFC\',\n              padding: \'11px 13px\',\n              marginBottom: 10,\n              gap: 7,\n            }}\n          >\n            <View\n              style={{\n                flexDirection: \'row\',\n                justifyContent: \'space-between\',\n                alignItems: \'center\',\n                gap: 10,\n              }}\n            >\n              <View style={{ flex: 1 }}>\n                <Text style={{ fontSize: 14, fontWeight: 900 }}>\n                  Where it went\n                </Text>\n                <Text\n                  style={{\n                    marginTop: 1,\n                    color: \'#777A83\',\n                    fontSize: 10,\n                    fontWeight: 700,\n                  }}\n                >\n                  {reportMonthLabel}\n                </Text>\n              </View>\n              <Text style={{ fontSize: 15, fontWeight: 900 }}>\n                {format(monthDisplay, \'financial\')}\n              </Text>\n            </View>\n\n            {(compactBreakdownRows.length > 0 ||\n              subcategoryBreakdown.uncategorized !== 0) && (\n              <View\n                style={{\n                  borderTop: \'1px solid #E9E8EE\',\n                  paddingTop: 6,\n                  gap: 5,\n                }}\n              >\n                {compactBreakdownRows.map(row => (\n                  <View\n                    key={row.name}\n                    style={{\n                      flexDirection: \'row\',\n                      justifyContent: \'space-between\',\n                      alignItems: \'center\',\n                      gap: 10,\n                    }}\n                  >\n                    <Text\n                      style={{\n                        color: \'#5F6069\',\n                        fontSize: 12,\n                        fontWeight: 750,\n                      }}\n                    >\n                      {row.name}\n                    </Text>\n                    <Text style={{ fontSize: 12, fontWeight: 850 }}>\n                      {format(row.amount, \'financial\')}\n                    </Text>\n                  </View>\n                ))}\n\n                {subcategoryBreakdown.uncategorized !== 0 &&\n                  compactBreakdownRows.length < 4 && (\n                    <View\n                      style={{\n                        flexDirection: \'row\',\n                        justifyContent: \'space-between\',\n                        alignItems: \'center\',\n                        gap: 10,\n                      }}\n                    >\n                      <Text\n                        style={{\n                          color: \'#A86600\',\n                          fontSize: 12,\n                          fontWeight: 800,\n                        }}\n                      >\n                        Uncategorized\n                      </Text>\n                      <Text\n                        style={{\n                          color: \'#A86600\',\n                          fontSize: 12,\n                          fontWeight: 900,\n                        }}\n                      >\n                        {format(\n                          subcategoryBreakdown.uncategorized,\n                          \'financial\',\n                        )}\n                      </Text>\n                    </View>\n                  )}\n              </View>\n            )}\n\n            <button\n              type="button"\n              onClick={() => setShowBreakdown(true)}\n              style={{\n                border: 0,\n                borderRadius: 10,\n                background: \'#F0EDFF\',\n                color: \'#4D4B91\',\n                minHeight: 34,\n                padding: \'6px 10px\',\n                fontSize: 12,\n                fontWeight: 850,\n                width: \'100%\',\n              }}\n            >\n              {hiddenBreakdownCount > 0\n                ? `View full breakdown · ${hiddenBreakdownCount} more`\n                : \'View full breakdown\'}\n            </button>\n          </View>\n        )}\n\n        <div\n          style={{\n            display: \'flex\',\n            flexShrink: 0,\n            gap: 8,\n            flexWrap: \'wrap\',\n            marginBottom: 10,\n          }}\n        >\n          {quickTags.map(tag => (\n            <button\n              key={tag}\n              type="button"\n              onClick={() => addTag(tag)}\n              style={{\n                border: 0,\n                borderRadius: 999,\n                background: noteHasSubcategory(note, tag)\n                  ? \'#FFF0AE\'\n                  : \'#F5F5F6\',\n                color: \'#8B8D94\',\n                padding: \'8px 14px\',\n                fontSize: 13,\n                fontWeight: 650,\n              }}\n            >\n              {tag}\n            </button>\n          ))}\n          <button\n            type="button"\n            onClick={() => setShowSubcategoryManager(value => !value)}\n            style={{\n              border: 0,\n              borderRadius: 999,\n              background: \'#F0EDFF\',\n              color: \'#4D4B91\',\n              padding: \'8px 14px\',\n              fontSize: 13,\n              fontWeight: 800,\n            }}\n          >\n            ⚙ Subcategories\n          </button>\n        </div>\n\n        {showSubcategoryManager && (\n          <View\n            style={{\n              border: \'1px solid #E7E5F1\',\n              borderRadius: 14,\n              padding: 10,\n              marginBottom: 8,\n              gap: 8,\n              backgroundColor: \'#FAF9FF\',\n            }}\n          >\n            <Text style={{ fontSize: 13, fontWeight: 800 }}>\n              Manage {fallbackLabel} subcategories\n            </Text>\n            <View style={{ flexDirection: \'row\', gap: 7 }}>\n              <input\n                value={newSubcategoryName}\n                onChange={event => setNewSubcategoryName(event.target.value)}\n                placeholder="Example: Hair Cut"\n                style={{\n                  flex: 1,\n                  minWidth: 0,\n                  height: 42,\n                  borderRadius: 10,\n                  border: \'1px solid #D9D9E2\',\n                  padding: \'0 10px\',\n                  fontSize: 14,\n                }}\n              />\n              <button\n                type="button"\n                onClick={addSubcategory}\n                style={{\n                  border: 0,\n                  borderRadius: 10,\n                  background: \'#FFD954\',\n                  color: \'#4D4B91\',\n                  padding: \'0 14px\',\n                  fontWeight: 850,\n                }}\n              >\n                Add\n              </button>\n            </View>\n\n            {customSubcategories.length > 0 && (\n              <div\n                style={{\n                  display: \'flex\',\n                  gap: 6,\n                  flexWrap: \'wrap\',\n                }}\n              >\n                {customSubcategories.map(name => (\n                  <button\n                    key={name}\n                    type="button"\n                    onClick={() => removeSubcategory(name)}\n                    title="Tap to remove"\n                    style={{\n                      border: 0,\n                      borderRadius: 999,\n                      background: \'#FFFFFF\',\n                      color: \'#666873\',\n                      padding: \'6px 10px\',\n                      fontSize: 12,\n                    }}\n                  >\n                    {name} ×\n                  </button>\n                ))}\n              </div>\n            )}\n\n            <Text style={{ fontSize: 11, color: \'#7D7F88\' }}>\n              These do not create Home cards. They classify spending inside\n              {` ${fallbackLabel}`}.\n            </Text>\n          </View>\n        )}\n\n        {showAccount && (\n          <select\n            value={accountId}\n            onChange={event => setAccountId(event.target.value)}\n            style={{\n              width: \'100%\',\n              height: 46,\n              borderRadius: 12,\n              border: \'1px solid #E1E1E6\',\n              background: \'#fff\',\n              padding: \'0 12px\',\n              marginBottom: 8,\n              fontSize: 15,\n            }}\n          >\n            <option value="">Choose account</option>\n            {availableAccounts.map(account => (\n              <option key={account.id} value={account.id}>\n                {account.name}\n              </option>\n            ))}\n          </select>\n        )}\n\n        {showNote && (\n          <textarea\n            value={note}\n            onChange={event => setNote(event.target.value)}\n            placeholder="Note or merchant…"\n            rows={2}\n            style={{\n              width: \'100%\',\n              boxSizing: \'border-box\',\n              resize: \'none\',\n              borderRadius: 12,\n              border: \'1px solid #E1E1E6\',\n              background: \'#fff\',\n              padding: 10,\n              marginBottom: 8,\n              fontSize: 14,\n            }}\n          />\n        )}\n\n        <div\n          style={{\n            display: \'grid\',\n            flexShrink: 0,\n            gridTemplateColumns: \'repeat(6, minmax(0, 1fr))\',\n            gap: 3,\n            background: \'#FFF9E6\',\n            padding: 5,\n            marginBottom: 8,\n          }}\n        >\n          {toolbarButton(\n            \'Note\',\n            <span aria-hidden style={{ fontSize: 18 }}>📝</span>,\n            showNote,\n            () => setShowNote(value => !value),\n          )}\n          {toolbarButton(\n            \'Account\',\n            <SvgPiggyBank width={19} height={19} />,\n            showAccount,\n            () => setShowAccount(value => !value),\n          )}\n          {toolbarButton(\n            \'Today\',\n            <SvgCalendar width={19} height={19} />,\n            date === monthUtils.currentDay(),\n            () => setDate(monthUtils.currentDay()),\n          )}\n          {toolbarButton(\n            \'Tag\',\n            <span style={{ fontSize: 18 }}>🏷️</span>,\n            false,\n            () => setMessage(\'Tap one of the category tags above.\'),\n          )}\n          {toolbarButton(\'Clear\', <span style={{ fontSize: 18 }}>⌫</span>, false, () =>\n            pressKey(\'clear\'),\n          )}\n          {toolbarButton(\'List\', <SvgList width={19} height={19} />, false, () => {\n            if (effectiveCategoryId) {\n              void navigate(`/categories/${effectiveCategoryId}?month=${month}`);\n            }\n          })}\n        </div>\n\n        <div\n          style={{\n            display: \'grid\',\n            flexShrink: 0,\n            gridTemplateColumns: \'repeat(4, minmax(0, 1fr))\',\n            gap: 7,\n          }}\n        >\n          {keys.map((key, index) => {\n            const isBack = key === \'back\';\n            const isClear = key === \'clear\';\n            return (\n              <button\n                key={`${key}-${index}`}\n                type="button"\n                onClick={() => pressKey(key)}\n                style={{\n                  border: 0,\n                  height: 58,\n                  borderRadius: 4,\n                  background: isBack || isClear ? \'#FAFAFB\' : \'#F8F8F9\',\n                  color: \'#111\',\n                  fontSize: isBack || isClear ? 22 : 21,\n                  fontWeight: 800,\n                }}\n              >\n                {isBack ? \'⌫\' : isClear ? \'C\' : key}\n              </button>\n            );\n          })}\n\n          <button\n            type="button"\n            onClick={() => {\n              if (amount.includes(\'.\')) {\n                pressKey(\'0\');\n              } else {\n                setAmount(value => (value === \'0\' ? \'0.\' : `${value}.`));\n              }\n            }}\n            style={{\n              border: 0,\n              height: 58,\n              borderRadius: 4,\n              background: \'#F8F8F9\',\n              color: \'#111\',\n              fontSize: 21,\n              fontWeight: 800,\n            }}\n          >\n            .\n          </button>\n\n          <button\n            type="button"\n            disabled={saving || creatingCategory || !effectiveCategoryId}\n            onClick={() => void saveTransaction()}\n            style={{\n              border: 0,\n              height: 58,\n              borderRadius: 6,\n              background: \'#FFD954\',\n              color: \'#4D4B91\',\n              fontSize: 30,\n              fontWeight: 900,\n            }}\n          >\n            ✓\n          </button>\n        {showBreakdown && !isIncome && (\n          <View\n            style={{\n              position: \'fixed\',\n              inset: 0,\n              zIndex: 200,\n              backgroundColor: \'#FFFFFF\',\n              overflowY: \'auto\',\n              padding:\n                \'calc(env(safe-area-inset-top) + 12px) 16px calc(env(safe-area-inset-bottom) + 24px)\',\n            }}\n          >\n            <View\n              style={{\n                width: \'100%\',\n                maxWidth: 680,\n                alignSelf: \'center\',\n                gap: 14,\n              }}\n            >\n              <View\n                style={{\n                  flexDirection: \'row\',\n                  alignItems: \'center\',\n                  justifyContent: \'space-between\',\n                  minHeight: 48,\n                }}\n              >\n                <button\n                  type="button"\n                  aria-label="Close breakdown"\n                  onClick={() => setShowBreakdown(false)}\n                  style={{\n                    border: 0,\n                    background: \'transparent\',\n                    color: \'#111\',\n                    fontSize: 32,\n                    lineHeight: 1,\n                    padding: 6,\n                  }}\n                >\n                  ×\n                </button>\n\n                <View style={{ flex: 1, alignItems: \'center\' }}>\n                  <Text style={{ fontSize: 20, fontWeight: 900 }}>\n                    {title}\n                  </Text>\n                  <Text\n                    style={{\n                      marginTop: 2,\n                      color: \'#777A83\',\n                      fontSize: 12,\n                      fontWeight: 700,\n                    }}\n                  >\n                    {reportMonthLabel}\n                  </Text>\n                </View>\n\n                <View style={{ width: 44 }} />\n              </View>\n\n              <View\n                style={{\n                  borderRadius: 18,\n                  backgroundColor: \'#F7F5FF\',\n                  padding: 14,\n                  flexDirection: \'row\',\n                  justifyContent: \'space-between\',\n                  alignItems: \'center\',\n                  gap: 12,\n                }}\n              >\n                <Text\n                  style={{\n                    color: \'#595A63\',\n                    fontSize: 13,\n                    fontWeight: 750,\n                  }}\n                >\n                  Total spent\n                </Text>\n                <Text style={{ fontSize: 22, fontWeight: 900 }}>\n                  {format(monthDisplay, \'financial\')}\n                </Text>\n              </View>\n\n              <View\n                style={{\n                  border: \'1px solid #ECEAF2\',\n                  borderRadius: 18,\n                  backgroundColor: \'#FFFFFF\',\n                  overflow: \'hidden\',\n                }}\n              >\n                {subcategoryBreakdown.rows.map((row, index) => (\n                  <View\n                    key={row.name}\n                    style={{\n                      flexDirection: \'row\',\n                      justifyContent: \'space-between\',\n                      alignItems: \'center\',\n                      gap: 12,\n                      minHeight: 54,\n                      padding: \'10px 14px\',\n                      borderTop:\n                        index === 0 ? undefined : \'1px solid #F0EFF4\',\n                    }}\n                  >\n                    <View style={{ flex: 1 }}>\n                      <Text style={{ fontSize: 14, fontWeight: 800 }}>\n                        {row.name}\n                      </Text>\n                      {row.count > 1 && (\n                        <Text\n                          style={{\n                            marginTop: 2,\n                            color: \'#8B8C94\',\n                            fontSize: 10,\n                            fontWeight: 650,\n                          }}\n                        >\n                          {row.count} transactions\n                        </Text>\n                      )}\n                    </View>\n                    <Text\n                      style={{\n                        color: row.amount === 0 ? \'#A5A6AD\' : \'#17171C\',\n                        fontSize: 15,\n                        fontWeight: 900,\n                      }}\n                    >\n                      {format(row.amount, \'financial\')}\n                    </Text>\n                  </View>\n                ))}\n\n                {subcategoryBreakdown.uncategorized !== 0 && (\n                  <View\n                    style={{\n                      flexDirection: \'row\',\n                      justifyContent: \'space-between\',\n                      alignItems: \'center\',\n                      gap: 12,\n                      minHeight: 54,\n                      padding: \'10px 14px\',\n                      borderTop: \'1px solid #F0EFF4\',\n                      backgroundColor: \'#FFF9EE\',\n                    }}\n                  >\n                    <View style={{ flex: 1 }}>\n                      <Text\n                        style={{\n                          color: \'#A86600\',\n                          fontSize: 14,\n                          fontWeight: 850,\n                        }}\n                      >\n                        Uncategorized\n                      </Text>\n                      <Text\n                        style={{\n                          marginTop: 2,\n                          color: \'#B58B4A\',\n                          fontSize: 10,\n                          fontWeight: 650,\n                        }}\n                      >\n                        {subcategoryBreakdown.uncategorizedCount}{\' \'}\n                        transaction\n                        {subcategoryBreakdown.uncategorizedCount === 1\n                          ? \'\'\n                          : \'s\'}\n                      </Text>\n                    </View>\n                    <Text\n                      style={{\n                        color: \'#A86600\',\n                        fontSize: 15,\n                        fontWeight: 900,\n                      }}\n                    >\n                      {format(\n                        subcategoryBreakdown.uncategorized,\n                        \'financial\',\n                      )}\n                    </Text>\n                  </View>\n                )}\n              </View>\n\n              <Text\n                style={{\n                  color: \'#777A83\',\n                  fontSize: 11,\n                  lineHeight: 1.45,\n                  textAlign: \'center\',\n                }}\n              >\n                Every transaction in this category for {reportMonthLabel} is\n                included. Anything without a subcategory remains visible as\n                Uncategorized.\n              </Text>\n            </View>\n          </View>\n        )}\n\n        </div>\n      </View>\n    </View>\n  );\n}\n'

BUDGET_LOCAL_BUDGET_TSX = 'import React, { useEffect, useMemo, useState } from \'react\';\n\nimport {\n  SvgCheveronLeft,\n  SvgCheveronRight,\n} from \'@actual-app/components/icons/v1\';\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport { send } from \'@actual-app/core/platform/client/connection\';\nimport * as monthUtils from \'@actual-app/core/shared/months\';\nimport { q } from \'@actual-app/core/shared/query\';\nimport { amountToInteger } from \'@actual-app/core/shared/util\';\n\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useLocale } from \'#hooks/useLocale\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\nconst PINNED_MAIN_STORAGE_KEY = \'budget-local-pinned-main-v1\';\n\nconst PALETTE = [\n  \'#F7C84B\',\n  \'#FF9253\',\n  \'#58A8F5\',\n  \'#C17ADE\',\n  \'#EF5C62\',\n  \'#2AC6B0\',\n  \'#7BCB65\',\n  \'#8B78E7\',\n  \'#E59C48\',\n];\n\nfunction normalize(value: string) {\n  return value\n    .toLowerCase()\n    .normalize(\'NFD\')\n    .replace(/[\\u0300-\\u036f]/g, \'\')\n    .replace(/[^a-z0-9]+/g, \' \')\n    .trim();\n}\n\nfunction readPinnedMainIds(): string[] {\n  try {\n    const parsed = JSON.parse(\n      window.localStorage.getItem(PINNED_MAIN_STORAGE_KEY) || \'[]\',\n    );\n    return Array.isArray(parsed)\n      ? parsed.filter(item => typeof item === \'string\')\n      : [];\n  } catch {\n    return [];\n  }\n}\n\nfunction displayCategoryName(name: string) {\n  const value = normalize(name);\n  if (value === \'food\' || value === \'food drink\') return \'Food & Drink\';\n  if (value === \'transportation\' || value === \'transport\') return \'Transport\';\n  if (\n    value === \'bills\' ||\n    value === \'utilities\' ||\n    value === \'home bills\'\n  ) {\n    return \'Home Bills\';\n  }\n  if (value === \'self care\') return \'Self-Care\';\n  return name;\n}\n\nfunction categoryEmoji(name: string) {\n  const value = normalize(name);\n  if (value.includes(\'food\')) return \'🍽️\';\n  if (value.includes(\'transport\') || value.includes(\'gas\')) return \'🚌\';\n  if (\n    value === \'bills\' ||\n    value.includes(\'home bill\') ||\n    value.includes(\'utilit\')\n  ) {\n    return \'⚡\';\n  }\n  if (value.includes(\'self care\')) return \'✨\';\n  if (value.includes(\'shopping\')) return \'🛍️\';\n  if (value.includes(\'health\')) return \'✚\';\n  if (value.includes(\'subscription\')) return \'🔁\';\n  if (value.includes(\'mortgage\') || value.includes(\'house\')) return \'🏠\';\n  if (value.includes(\'rent\')) return \'🏡\';\n  if (value.includes(\'insurance\')) return \'🛡️\';\n  if (value.includes(\'travel\')) return \'✈️\';\n  if (value.includes(\'pet\')) return \'🐾\';\n  if (value.includes(\'entertain\')) return \'🎬\';\n  if (value.includes(\'school\') || value.includes(\'education\')) return \'🎓\';\n  if (value.includes(\'debt\') || value.includes(\'credit\')) return \'💳\';\n  if (value.includes(\'saving\')) return \'💰\';\n  return \'💵\';\n}\n\nfunction monthDays(month: string) {\n  const [year, value] = month.split(\'-\').map(Number);\n  return new Date(year, value, 0).getDate();\n}\n\nfunction makeDonutGradient(\n  rows: Array<{ budget: number; color: string }>,\n  total: number,\n) {\n  if (total <= 0 || rows.length === 0) {\n    return \'conic-gradient(#ECECF2 0% 100%)\';\n  }\n\n  let cursor = 0;\n  const parts: string[] = [];\n\n  rows.forEach(row => {\n    if (row.budget <= 0) return;\n    const start = cursor;\n    cursor += (row.budget / total) * 100;\n    parts.push(`${row.color} ${start}% ${cursor}%`);\n  });\n\n  if (cursor < 100) {\n    parts.push(`#ECECF2 ${cursor}% 100%`);\n  }\n\n  return `conic-gradient(${parts.join(\', \')})`;\n}\n\nexport function BudgetLocalBudget() {\n  const locale = useLocale();\n  const format = useFormat();\n  const [month, setMonth] = useState(() => monthUtils.currentMonth());\n  const [budgetByCategory, setBudgetByCategory] = useState<\n    Record<string, number>\n  >({});\n  const [refreshKey, setRefreshKey] = useState(0);\n  const [mode, setMode] = useState<\'plan\' | \'remain\'>(\'plan\');\n  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(\n    null,\n  );\n  const [editAmount, setEditAmount] = useState(\'\');\n  const [editError, setEditError] = useState(\'\');\n  const [saving, setSaving] = useState(false);\n\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n  const pinnedMainIds = useMemo(() => readPinnedMainIds(), []);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    void send(\'envelope-budget-month\', { month }).then(cells => {\n      if (cancelled) return;\n\n      const next: Record<string, number> = {};\n      for (const category of categories) {\n        const cell = cells.find(item =>\n          item.name.endsWith(`budget-${category.id}`),\n        );\n        next[category.id] = Number(cell?.value) || 0;\n      }\n      setBudgetByCategory(next);\n    });\n\n    return () => {\n      cancelled = true;\n    };\n  }, [categories, month, refreshKey]);\n\n  const transactionQuery = useMemo(\n    () =>\n      q(\'transactions\')\n        .options({ splits: \'all\' })\n        .filter({\n          date: { $transform: \'$month\', $eq: month },\n        })\n        .select(\'*\'),\n    [month],\n  );\n\n  const { transactions } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const spentByCategory = useMemo(() => {\n    const totals = new Map<string, number>();\n\n    for (const transaction of transactions) {\n      if (\n        transaction.is_parent ||\n        transaction.tombstone ||\n        transaction.starting_balance_flag ||\n        !transaction.category\n      ) {\n        continue;\n      }\n\n      totals.set(\n        transaction.category,\n        (totals.get(transaction.category) ?? 0) + transaction.amount,\n      );\n    }\n\n    return totals;\n  }, [transactions]);\n\n  const rows = useMemo(() => {\n    const hiddenLegacy = new Set([\'general\', \'bills flexible\']);\n\n    const expenseCategories = categories.filter(category => {\n      if (category.hidden || category.is_income) return false;\n      if (hiddenLegacy.has(normalize(category.name))) return false;\n\n      const budget = Math.max(0, budgetByCategory[category.id] ?? 0);\n      const spent = Math.max(\n        0,\n        -(spentByCategory.get(category.id) ?? 0),\n      );\n\n      return (\n        budget > 0 ||\n        spent > 0 ||\n        pinnedMainIds.includes(category.id) ||\n        normalize(category.name) !== \'general\'\n      );\n    });\n\n    return expenseCategories.map((category, index) => {\n      const budget = Math.max(0, budgetByCategory[category.id] ?? 0);\n      const spent = Math.max(\n        0,\n        -(spentByCategory.get(category.id) ?? 0),\n      );\n\n      return {\n        id: category.id,\n        name: displayCategoryName(category.name),\n        rawName: category.name,\n        emoji: categoryEmoji(category.name),\n        budget,\n        spent,\n        balance: budget - spent,\n        color: PALETTE[index % PALETTE.length],\n      };\n    });\n  }, [\n    budgetByCategory,\n    categories,\n    pinnedMainIds,\n    spentByCategory,\n  ]);\n\n  const orderedRows = useMemo(\n    () =>\n      [...rows].sort((a, b) => {\n        const aActive = a.budget > 0 || a.spent > 0 ? 1 : 0;\n        const bActive = b.budget > 0 || b.spent > 0 ? 1 : 0;\n        if (aActive !== bActive) return bActive - aActive;\n        if (a.budget !== b.budget) return b.budget - a.budget;\n        return a.name.localeCompare(b.name);\n      }),\n    [rows],\n  );\n\n  const budgetedRows = useMemo(\n    () => orderedRows.filter(row => row.budget > 0),\n    [orderedRows],\n  );\n\n  const totalBudget = budgetedRows.reduce(\n    (sum, row) => sum + row.budget,\n    0,\n  );\n  const totalSpent = orderedRows.reduce(\n    (sum, row) => sum + row.spent,\n    0,\n  );\n  const totalRemaining = totalBudget - totalSpent;\n\n  const summaryRows = budgetedRows.slice(0, 6);\n  const otherBudget = budgetedRows\n    .slice(6)\n    .reduce((sum, row) => sum + row.budget, 0);\n\n  const donut = makeDonutGradient(budgetedRows, totalBudget);\n  const days = Math.max(1, monthDays(month));\n  const perDay = Math.round(totalBudget / days);\n\n  const currentMonth = monthUtils.currentMonth();\n  const monthLabel =\n    month === currentMonth\n      ? \'This Month\'\n      : monthUtils.format(month, "MMMM \'\'yy", locale);\n\n  const editingRow = editingCategoryId\n    ? rows.find(row => row.id === editingCategoryId)\n    : undefined;\n\n  const openEditor = (id: string, budget: number) => {\n    setEditingCategoryId(id);\n    setEditError(\'\');\n    setEditAmount(\n      budget > 0\n        ? (budget / 100)\n            .toFixed(2)\n            .replace(/\\.00$/, \'\')\n            .replace(/(\\.\\d)0$/, \'$1\')\n        : \'\',\n    );\n  };\n\n  const saveBudget = async () => {\n    if (!editingCategoryId) return;\n\n    const cleaned = editAmount.replace(/[$,\\s]/g, \'\');\n    const numeric = Number(cleaned);\n\n    if (!Number.isFinite(numeric) || numeric < 0) {\n      setEditError(\'Enter a valid amount.\');\n      return;\n    }\n\n    setSaving(true);\n    setEditError(\'\');\n\n    try {\n      await send(\'budget/budget-amount\', {\n        month,\n        category: editingCategoryId,\n        amount: amountToInteger(numeric.toFixed(2)),\n      });\n      setEditingCategoryId(null);\n      setRefreshKey(value => value + 1);\n    } catch {\n      setEditError(\'Could not save the budget amount.\');\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        flexShrink: 0,\n        overflow: \'visible\',\n        backgroundColor: \'#F8F8FA\',\n        color: \'#111116\',\n        paddingTop: 18,\n        paddingLeft: 14,\n        paddingRight: 14,\n        paddingBottom: \'calc(env(safe-area-inset-bottom) + 210px)\',\n        boxSizing: \'border-box\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          flexShrink: 0,\n          gap: 24,\n        }}\n      >\n        <View\n          style={{\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            flexShrink: 0,\n            minHeight: 60,\n            paddingTop: 4,\n            paddingBottom: 8,\n          }}\n        >\n          <View style={{ width: 86, flexShrink: 0 }}>\n            <Text\n              style={{\n                color: \'#4D4B91\',\n                fontSize: 14,\n                fontWeight: 850,\n              }}\n            >\n              Monthly\n            </Text>\n          </View>\n\n          <View\n            style={{\n              flex: 1,\n              flexDirection: \'row\',\n              alignItems: \'center\',\n              justifyContent: \'center\',\n              gap: 7,\n            }}\n          >\n            <button\n              type="button"\n              aria-label="Previous month"\n              onClick={() =>\n                setMonth(value => monthUtils.addMonths(value, -1))\n              }\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronLeft width={22} height={22} />\n            </button>\n\n            <Text\n              style={{\n                minWidth: 128,\n                textAlign: \'center\',\n                fontSize: 20,\n                fontWeight: 900,\n                letterSpacing: \'-0.03em\',\n              }}\n            >\n              {monthLabel}\n            </Text>\n\n            <button\n              type="button"\n              aria-label="Next month"\n              onClick={() =>\n                setMonth(value => monthUtils.addMonths(value, 1))\n              }\n              style={{\n                border: 0,\n                background: \'transparent\',\n                color: \'#4D4B91\',\n                padding: 6,\n              }}\n            >\n              <SvgCheveronRight width={22} height={22} />\n            </button>\n          </View>\n\n          <View\n            aria-hidden\n            style={{\n              width: 86,\n              flexShrink: 0,\n            }}\n          />\n        </View>\n\n        <View\n          style={{\n            borderRadius: 24,\n            backgroundColor: \'#FFFFFF\',\n            flexShrink: 0,\n            padding: \'22px 18px 22px\',\n            boxShadow: \'0 10px 30px rgba(42, 42, 60, 0.07)\',\n            gap: 20,\n          }}\n        >\n          <View\n            style={{\n              flexDirection: \'row\',\n              alignItems: \'center\',\n              justifyContent: \'space-between\',\n              flexShrink: 0,\n            }}\n          >\n            <Text\n              style={{\n                color: \'#777983\',\n                fontSize: 12,\n                fontWeight: 800,\n                letterSpacing: \'0.02em\',\n              }}\n            >\n              MONTHLY PLAN\n            </Text>\n            <Text\n              style={{\n                color: \'#A2A2A8\',\n                fontSize: 11,\n                fontWeight: 750,\n              }}\n            >\n              {budgetedRows.length} categories\n            </Text>\n          </View>\n\n          <View\n            style={{\n              minHeight: 126,\n              flexDirection: \'row\',\n              alignItems: \'center\',\n              flexShrink: 0,\n              gap: 18,\n            }}\n          >\n            <View\n              aria-hidden\n              style={{\n                width: 108,\n                height: 108,\n                flexShrink: 0,\n                borderRadius: 999,\n                background: donut,\n                alignItems: \'center\',\n                justifyContent: \'center\',\n              }}\n            >\n              <View\n                style={{\n                  width: 70,\n                  height: 70,\n                  borderRadius: 999,\n                  backgroundColor: \'#FFFFFF\',\n                }}\n              />\n            </View>\n\n            <View style={{ flex: 1 }}>\n              <Text\n                style={{\n                  color: \'#A2A2A8\',\n                  fontSize: 15,\n                  fontWeight: 700,\n                }}\n              >\n                Monthly\n              </Text>\n              <Text\n                style={{\n                  marginTop: 2,\n                  fontSize: 31,\n                  lineHeight: 1.12,\n                  fontWeight: 950,\n                  letterSpacing: \'-0.045em\',\n                }}\n              >\n                {format(totalBudget, \'financial\')}\n              </Text>\n              <Text\n                style={{\n                  marginTop: 5,\n                  color: \'#A2A2A8\',\n                  fontSize: 13,\n                  fontWeight: 750,\n                }}\n              >\n                ~{format(perDay, \'financial\')} per day\n              </Text>\n            </View>\n          </View>\n\n          <View\n            style={{\n              borderTop: \'1px solid #F0EFF3\',\n              paddingTop: 14,\n              flexShrink: 0,\n              gap: 12,\n            }}\n          >\n            {summaryRows.length === 0 ? (\n              <View\n                style={{\n                  borderRadius: 16,\n                  backgroundColor: \'#F7F7F9\',\n                  padding: 14,\n                }}\n              >\n                <Text\n                  style={{\n                    color: \'#777983\',\n                    textAlign: \'center\',\n                    fontSize: 13,\n                    fontWeight: 750,\n                  }}\n                >\n                  No monthly plan yet. Add amounts below.\n                </Text>\n              </View>\n            ) : (\n              <>\n                {summaryRows.map(row => {\n                  const percent =\n                    totalBudget > 0\n                      ? (row.budget / totalBudget) * 100\n                      : 0;\n\n                  return (\n                    <View\n                      key={row.id}\n                      style={{\n                        flexDirection: \'row\',\n                        alignItems: \'center\',\n                        minHeight: 34,\n                        gap: 9,\n                      }}\n                    >\n                      <Text style={{ width: 28, fontSize: 19 }}>\n                        {row.emoji}\n                      </Text>\n                      <Text\n                        style={{\n                          flex: 1,\n                          fontSize: 14,\n                          fontWeight: 850,\n                        }}\n                      >\n                        {row.name}{\' \'}\n                        <Text\n                          style={{\n                            color: \'#A6A6AB\',\n                            fontWeight: 750,\n                          }}\n                        >\n                          {percent.toFixed(2)}%\n                        </Text>\n                      </Text>\n                      <Text\n                        style={{\n                          fontSize: 14,\n                          fontWeight: 900,\n                        }}\n                      >\n                        {format(row.budget, \'financial\')}\n                      </Text>\n                    </View>\n                  );\n                })}\n\n                {otherBudget > 0 && (\n                  <View\n                    style={{\n                      flexDirection: \'row\',\n                      alignItems: \'center\',\n                      minHeight: 34,\n                      gap: 9,\n                    }}\n                  >\n                    <Text style={{ width: 28, fontSize: 19 }}>•••</Text>\n                    <Text\n                      style={{\n                        flex: 1,\n                        fontSize: 14,\n                        fontWeight: 850,\n                      }}\n                    >\n                      Other categories{\' \'}\n                      <Text\n                        style={{\n                          color: \'#A6A6AB\',\n                          fontWeight: 750,\n                        }}\n                      >\n                        {((otherBudget / totalBudget) * 100).toFixed(2)}%\n                      </Text>\n                    </Text>\n                    <Text\n                      style={{\n                        fontSize: 14,\n                        fontWeight: 900,\n                      }}\n                    >\n                      {format(otherBudget, \'financial\')}\n                    </Text>\n                  </View>\n                )}\n              </>\n            )}\n          </View>\n\n          <View\n            style={{\n              flexDirection: \'row\',\n              flexShrink: 0,\n              gap: 8,\n              borderTop: \'1px solid #F0EFF3\',\n              paddingTop: 14,\n              marginTop: 2,\n            }}\n          >\n            <View\n              style={{\n                flex: 1,\n                borderRadius: 14,\n                backgroundColor: \'#F7F7F9\',\n                padding: \'9px 10px\',\n              }}\n            >\n              <Text\n                style={{\n                  color: \'#9A9BA2\',\n                  fontSize: 10,\n                  fontWeight: 800,\n                }}\n              >\n                SPENT\n              </Text>\n              <Text\n                style={{\n                  marginTop: 2,\n                  fontSize: 14,\n                  fontWeight: 900,\n                }}\n              >\n                {format(totalSpent, \'financial\')}\n              </Text>\n            </View>\n            <View\n              style={{\n                flex: 1,\n                borderRadius: 14,\n                backgroundColor:\n                  totalRemaining < 0 ? \'#FFF0F1\' : \'#F1FAF7\',\n                padding: \'9px 10px\',\n              }}\n            >\n              <Text\n                style={{\n                  color:\n                    totalRemaining < 0 ? \'#C93645\' : \'#5D8C7E\',\n                  fontSize: 10,\n                  fontWeight: 800,\n                }}\n              >\n                {totalRemaining < 0 ? \'OVER\' : \'REMAIN\'}\n              </Text>\n              <Text\n                style={{\n                  marginTop: 2,\n                  color:\n                    totalRemaining < 0 ? \'#C93645\' : \'#111116\',\n                  fontSize: 14,\n                  fontWeight: 900,\n                }}\n              >\n                {format(Math.abs(totalRemaining), \'financial\')}\n              </Text>\n            </View>\n          </View>\n        </View>\n\n        <View\n          style={{\n            alignSelf: \'center\',\n            flexDirection: \'row\',\n            flexShrink: 0,\n            marginTop: 2,\n            border: \'1px solid #DADAE0\',\n            borderRadius: 999,\n            backgroundColor: \'#FFFFFF\',\n            padding: 3,\n          }}\n        >\n          <button\n            type="button"\n            onClick={() => setMode(\'plan\')}\n            style={{\n              border: 0,\n              borderRadius: 999,\n              minWidth: 110,\n              padding: \'8px 16px\',\n              background:\n                mode === \'plan\' ? \'#F0EDFF\' : \'transparent\',\n              color: mode === \'plan\' ? \'#4D4B91\' : \'#A0A1A7\',\n              fontSize: 13,\n              fontWeight: 850,\n            }}\n          >\n            Plan\n          </button>\n          <button\n            type="button"\n            onClick={() => setMode(\'remain\')}\n            style={{\n              border: 0,\n              borderRadius: 999,\n              minWidth: 110,\n              padding: \'8px 16px\',\n              background:\n                mode === \'remain\' ? \'#F0EDFF\' : \'transparent\',\n              color: mode === \'remain\' ? \'#4D4B91\' : \'#A0A1A7\',\n              fontSize: 13,\n              fontWeight: 850,\n            }}\n          >\n            Remain\n          </button>\n        </View>\n\n        <View\n          style={{\n            flexShrink: 0,\n            gap: 14,\n          }}\n        >\n          {orderedRows.map(row => {\n            const value =\n              mode === \'plan\' ? row.budget : row.balance;\n            const negative = mode === \'remain\' && value < 0;\n\n            return (\n              <View\n                key={row.id}\n                style={{\n                  minHeight: 82,\n                  flexShrink: 0,\n                  scrollMarginBottom: 160,\n                  borderRadius: 20,\n                  backgroundColor: \'#FFFFFF\',\n                  boxShadow: \'0 7px 20px rgba(42, 42, 60, 0.06)\',\n                  padding: \'13px 14px\',\n                  flexDirection: \'row\',\n                  alignItems: \'center\',\n                  gap: 11,\n                }}\n              >\n                <View\n                  style={{\n                    width: 38,\n                    height: 38,\n                    borderRadius: 13,\n                    backgroundColor: `${row.color}1F`,\n                    alignItems: \'center\',\n                    justifyContent: \'center\',\n                  }}\n                >\n                  <Text style={{ fontSize: 20 }}>{row.emoji}</Text>\n                </View>\n\n                <View style={{ flex: 1, minWidth: 0 }}>\n                  <Text\n                    style={{\n                      fontSize: 15,\n                      fontWeight: 900,\n                    }}\n                  >\n                    {row.name}\n                  </Text>\n                  <Text\n                    style={{\n                      marginTop: 3,\n                      color: \'#9A9BA2\',\n                      fontSize: 10,\n                      fontWeight: 700,\n                    }}\n                  >\n                    Spent {format(row.spent, \'financial\')}\n                  </Text>\n                </View>\n\n                {mode === \'plan\' ? (\n                  <button\n                    type="button"\n                    onClick={() => openEditor(row.id, row.budget)}\n                    aria-label={`Edit ${row.name} budget`}\n                    style={{\n                      border: 0,\n                      borderRadius: 999,\n                      minWidth: 84,\n                      padding: \'8px 12px\',\n                      background: \'#F5F5F6\',\n                      color: \'#111116\',\n                      fontSize: 15,\n                      fontWeight: 900,\n                    }}\n                  >\n                    {format(row.budget, \'financial\')}\n                  </button>\n                ) : (\n                  <View\n                    style={{\n                      borderRadius: 999,\n                      minWidth: 84,\n                      padding: \'8px 12px\',\n                      backgroundColor: negative\n                        ? \'#FFF0F1\'\n                        : \'#F5F5F6\',\n                      alignItems: \'center\',\n                    }}\n                  >\n                    <Text\n                      style={{\n                        color: negative ? \'#C93645\' : \'#111116\',\n                        fontSize: 15,\n                        fontWeight: 900,\n                      }}\n                    >\n                      {format(value, \'financial\')}\n                    </Text>\n                  </View>\n                )}\n              </View>\n            );\n          })}\n        </View>\n\n        <View\n          aria-hidden\n          style={{\n            height: 230,\n            flexShrink: 0,\n            pointerEvents: \'none\',\n          }}\n        />\n      </View>\n\n      {editingRow && (\n        <View\n          style={{\n            position: \'fixed\',\n            inset: 0,\n            zIndex: 220,\n            backgroundColor: \'rgba(15, 15, 24, 0.34)\',\n            padding:\n              \'calc(env(safe-area-inset-top) + 20px) 18px calc(env(safe-area-inset-bottom) + 20px)\',\n            alignItems: \'center\',\n            justifyContent: \'center\',\n          }}\n        >\n          <View\n            style={{\n              width: \'100%\',\n              maxWidth: 420,\n              borderRadius: 24,\n              backgroundColor: \'#FFFFFF\',\n              padding: 18,\n              boxShadow: \'0 22px 60px rgba(0,0,0,0.18)\',\n              gap: 14,\n            }}\n          >\n            <View\n              style={{\n                flexDirection: \'row\',\n                alignItems: \'center\',\n                gap: 10,\n              }}\n            >\n              <Text style={{ fontSize: 24 }}>{editingRow.emoji}</Text>\n              <View style={{ flex: 1 }}>\n                <Text style={{ fontSize: 18, fontWeight: 900 }}>\n                  {editingRow.name}\n                </Text>\n                <Text\n                  style={{\n                    marginTop: 2,\n                    color: \'#8A8B93\',\n                    fontSize: 11,\n                    fontWeight: 700,\n                  }}\n                >\n                  {monthLabel} budget\n                </Text>\n              </View>\n            </View>\n\n            <label\n              style={{\n                display: \'flex\',\n                alignItems: \'center\',\n                gap: 8,\n                minHeight: 58,\n                borderRadius: 16,\n                background: \'#F7F7F9\',\n                padding: \'0 14px\',\n                fontSize: 22,\n                fontWeight: 900,\n              }}\n            >\n              $\n              <input\n                autoFocus\n                inputMode="decimal"\n                value={editAmount}\n                onChange={event => setEditAmount(event.target.value)}\n                onKeyDown={event => {\n                  if (event.key === \'Enter\') {\n                    event.preventDefault();\n                    void saveBudget();\n                  }\n                }}\n                placeholder="0.00"\n                style={{\n                  flex: 1,\n                  minWidth: 0,\n                  border: 0,\n                  outline: \'none\',\n                  background: \'transparent\',\n                  color: \'#111116\',\n                  font: \'inherit\',\n                }}\n              />\n            </label>\n\n            {editError && (\n              <Text\n                style={{\n                  color: \'#C93645\',\n                  fontSize: 12,\n                  fontWeight: 750,\n                }}\n              >\n                {editError}\n              </Text>\n            )}\n\n            <View\n              style={{\n                flexDirection: \'row\',\n                gap: 9,\n              }}\n            >\n              <button\n                type="button"\n                onClick={() => setEditingCategoryId(null)}\n                disabled={saving}\n                style={{\n                  flex: 1,\n                  border: \'1px solid #E1E1E7\',\n                  borderRadius: 14,\n                  minHeight: 46,\n                  background: \'#FFFFFF\',\n                  color: \'#555761\',\n                  fontSize: 14,\n                  fontWeight: 850,\n                }}\n              >\n                Cancel\n              </button>\n              <button\n                type="button"\n                onClick={() => void saveBudget()}\n                disabled={saving}\n                style={{\n                  flex: 1,\n                  border: 0,\n                  borderRadius: 14,\n                  minHeight: 46,\n                  background: \'#4D4B91\',\n                  color: \'#FFFFFF\',\n                  fontSize: 14,\n                  fontWeight: 900,\n                }}\n              >\n                {saving ? \'Saving…\' : \'Save\'}\n              </button>\n            </View>\n\n            <Text\n              style={{\n                color: \'#999AA1\',\n                textAlign: \'center\',\n                fontSize: 10,\n                lineHeight: 1.4,\n              }}\n            >\n              Monthly budgets are edited only here in Budget.\n            </Text>\n          </View>\n        </View>\n      )}\n    </View>\n  );\n}\n'

RECURRING_INCOME_TSX = 'import React, { useMemo, useState } from \'react\';\n\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport { q } from \'@actual-app/core/shared/query\';\n\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\nconst STORAGE_KEY = \'budget-local-recurring-income-v1\';\n\ntype RecurringIncomeConfig = {\n  enabled: boolean;\n  amount: number;\n  anchorDate: string;\n  intervalDays: number;\n  autoSweep: boolean;\n};\n\nfunction todayString() {\n  const value = new Date();\n  const year = value.getFullYear();\n  const month = String(value.getMonth() + 1).padStart(2, \'0\');\n  const day = String(value.getDate()).padStart(2, \'0\');\n  return `${year}-${month}-${day}`;\n}\n\nfunction readConfig(): RecurringIncomeConfig | null {\n  try {\n    const raw = window.localStorage.getItem(STORAGE_KEY);\n    if (!raw) return null;\n    const parsed = JSON.parse(raw) as Partial<RecurringIncomeConfig>;\n    if (\n      typeof parsed.amount !== \'number\' ||\n      !Number.isFinite(parsed.amount) ||\n      parsed.amount <= 0 ||\n      typeof parsed.anchorDate !== \'string\' ||\n      !parsed.anchorDate\n    ) {\n      return null;\n    }\n\n    return {\n      enabled: parsed.enabled !== false,\n      amount: parsed.amount,\n      anchorDate: parsed.anchorDate,\n      intervalDays:\n        typeof parsed.intervalDays === \'number\' && parsed.intervalDays > 0\n          ? parsed.intervalDays\n          : 14,\n      autoSweep: parsed.autoSweep !== false,\n    };\n  } catch {\n    return null;\n  }\n}\n\nfunction dateUtc(value: string) {\n  const [year, month, day] = value.split(\'-\').map(Number);\n  return Date.UTC(year, month - 1, day);\n}\n\nfunction diffDays(from: string, to: string) {\n  return Math.floor((dateUtc(to) - dateUtc(from)) / 86_400_000);\n}\n\nfunction addDays(value: string, amount: number) {\n  const date = new Date(dateUtc(value));\n  date.setUTCDate(date.getUTCDate() + amount);\n  return date.toISOString().slice(0, 10);\n}\n\nfunction friendlyDate(value: string) {\n  return new Date(`${value}T12:00:00`).toLocaleDateString(undefined, {\n    month: \'short\',\n    day: \'numeric\',\n  });\n}\n\nexport function RecurringIncomeCard() {\n  const format = useFormat();\n  const [config, setConfig] = useState<RecurringIncomeConfig | null>(() =>\n    readConfig(),\n  );\n  const [showEditor, setShowEditor] = useState(false);\n  const [draftAmount, setDraftAmount] = useState(() =>\n    config ? String(config.amount) : \'2000\',\n  );\n  const [draftDate, setDraftDate] = useState(\n    () => config?.anchorDate ?? todayString(),\n  );\n  const [draftInterval, setDraftInterval] = useState(\n    () => config?.intervalDays ?? 14,\n  );\n  const [draftSweep, setDraftSweep] = useState(\n    () => config?.autoSweep ?? true,\n  );\n  const [error, setError] = useState(\'\');\n\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n  const categoryById = useMemo(\n    () => new Map(categories.map(category => [category.id, category])),\n    [categories],\n  );\n\n  const today = todayString();\n  const queryStart =\n    config?.enabled && config.anchorDate <= today ? config.anchorDate : today;\n\n  const transactionQuery = useMemo(\n    () =>\n      q(\'transactions\')\n        .options({ splits: \'all\' })\n        .filter({\n          $and: [\n            { date: { $gte: queryStart } },\n            { date: { $lte: today } },\n          ],\n        })\n        .select(\'*\'),\n    [queryStart, today],\n  );\n\n  const { transactions } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const cycle = useMemo(() => {\n    if (!config?.enabled || config.anchorDate > today) {\n      return null;\n    }\n\n    const amount = Math.round(config.amount * 100);\n    const interval = Math.max(1, config.intervalDays);\n    const elapsed = Math.max(0, diffDays(config.anchorDate, today));\n    const currentIndex = Math.floor(elapsed / interval);\n    const currentStart = addDays(\n      config.anchorDate,\n      currentIndex * interval,\n    );\n    const nextPayday = addDays(currentStart, interval);\n    const spendingByCycle = new Map<number, number>();\n\n    for (const transaction of transactions) {\n      if (\n        transaction.is_parent ||\n        transaction.is_child ||\n        transaction.tombstone ||\n        transaction.starting_balance_flag ||\n        !transaction.category ||\n        transaction.date < config.anchorDate ||\n        transaction.date > today\n      ) {\n        continue;\n      }\n\n      const category = categoryById.get(transaction.category);\n      if (!category || category.hidden || category.is_income) {\n        continue;\n      }\n\n      const index = Math.floor(\n        Math.max(0, diffDays(config.anchorDate, transaction.date)) /\n          interval,\n      );\n      const spendingDelta = -transaction.amount;\n      spendingByCycle.set(\n        index,\n        (spendingByCycle.get(index) ?? 0) + spendingDelta,\n      );\n    }\n\n    const currentSpent = Math.max(\n      0,\n      spendingByCycle.get(currentIndex) ?? 0,\n    );\n    const currentAvailable = amount - currentSpent;\n\n    let piggyBank = 0;\n    if (config.autoSweep) {\n      for (let index = 0; index < currentIndex; index += 1) {\n        const spent = Math.max(0, spendingByCycle.get(index) ?? 0);\n        piggyBank += Math.max(0, amount - spent);\n      }\n    }\n\n    return {\n      amount,\n      currentSpent,\n      currentAvailable,\n      piggyBank,\n      currentStart,\n      nextPayday,\n    };\n  }, [categoryById, config, today, transactions]);\n\n  const save = () => {\n    const amount = Number(draftAmount.replace(/[$,\\s]/g, \'\'));\n    if (!Number.isFinite(amount) || amount <= 0) {\n      setError(\'Enter a valid paycheck amount.\');\n      return;\n    }\n    if (!draftDate) {\n      setError(\'Choose a payday.\');\n      return;\n    }\n\n    const next: RecurringIncomeConfig = {\n      enabled: true,\n      amount,\n      anchorDate: draftDate,\n      intervalDays: draftInterval,\n      autoSweep: draftSweep,\n    };\n\n    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));\n    setConfig(next);\n    setError(\'\');\n    setShowEditor(false);\n  };\n\n  if (!config?.enabled || !cycle) {\n    return (\n      <>\n        <button\n          type="button"\n          onClick={() => setShowEditor(true)}\n          style={{\n            width: \'100%\',\n            border: \'1px solid #E5E2F3\',\n            borderRadius: 20,\n            background: \'#F8F6FF\',\n            padding: \'14px 16px\',\n            color: \'#4D4B91\',\n            textAlign: \'left\',\n            fontSize: 14,\n            fontWeight: 850,\n            fontFamily: \'inherit\',\n          }}\n        >\n          💵 Set recurring income\n          <span\n            style={{\n              display: \'block\',\n              marginTop: 4,\n              color: \'#8C8C96\',\n              fontSize: 11,\n              fontWeight: 650,\n            }}\n          >\n            Track each paycheck and sweep leftover money to Piggy Bank.\n          </span>\n        </button>\n\n        {showEditor && (\n          <RecurringIncomeEditor\n            amount={draftAmount}\n            date={draftDate}\n            interval={draftInterval}\n            autoSweep={draftSweep}\n            error={error}\n            onAmount={setDraftAmount}\n            onDate={setDraftDate}\n            onInterval={setDraftInterval}\n            onSweep={setDraftSweep}\n            onCancel={() => setShowEditor(false)}\n            onSave={save}\n          />\n        )}\n      </>\n    );\n  }\n\n  const ratio =\n    cycle.amount > 0\n      ? Math.min(1, Math.max(0, cycle.currentSpent / cycle.amount))\n      : 0;\n\n  return (\n    <>\n      <View\n        style={{\n          flexShrink: 0,\n          borderRadius: 22,\n          backgroundColor: \'#F7F5FF\',\n          padding: 16,\n          gap: 12,\n          boxShadow: \'0 8px 24px rgba(72, 69, 143, 0.07)\',\n        }}\n      >\n        <View\n          style={{\n            flexDirection: \'row\',\n            justifyContent: \'space-between\',\n            alignItems: \'flex-start\',\n            gap: 10,\n          }}\n        >\n          <View style={{ flex: 1 }}>\n            <Text style={{ fontSize: 15, fontWeight: 900 }}>\n              💵 Current Paycheck\n            </Text>\n            <Text\n              style={{\n                marginTop: 3,\n                color: \'#7B7C86\',\n                fontSize: 11,\n                fontWeight: 700,\n              }}\n            >\n              {friendlyDate(cycle.currentStart)} →{\' \'}\n              {friendlyDate(addDays(cycle.nextPayday, -1))}\n            </Text>\n          </View>\n          <button\n            type="button"\n            onClick={() => setShowEditor(true)}\n            style={{\n              border: 0,\n              borderRadius: 999,\n              background: \'#EBE7FF\',\n              color: \'#4D4B91\',\n              padding: \'6px 10px\',\n              fontSize: 11,\n              fontWeight: 850,\n            }}\n          >\n            Edit\n          </button>\n        </View>\n\n        <View\n          style={{\n            flexDirection: \'row\',\n            justifyContent: \'space-between\',\n            gap: 12,\n          }}\n        >\n          <View>\n            <Text\n              style={{\n                color: \'#8B8C94\',\n                fontSize: 10,\n                fontWeight: 800,\n              }}\n            >\n              AVAILABLE\n            </Text>\n            <Text\n              style={{\n                marginTop: 3,\n                color:\n                  cycle.currentAvailable < 0 ? \'#C93645\' : \'#111116\',\n                fontSize: 25,\n                fontWeight: 950,\n              }}\n            >\n              {format(cycle.currentAvailable, \'financial\')}\n            </Text>\n          </View>\n\n          <View style={{ alignItems: \'flex-end\' }}>\n            <Text\n              style={{\n                color: \'#8B8C94\',\n                fontSize: 10,\n                fontWeight: 800,\n              }}\n            >\n              NEXT PAYDAY\n            </Text>\n            <Text\n              style={{\n                marginTop: 5,\n                fontSize: 14,\n                fontWeight: 900,\n              }}\n            >\n              {friendlyDate(cycle.nextPayday)}\n            </Text>\n          </View>\n        </View>\n\n        <View\n          style={{\n            height: 9,\n            borderRadius: 999,\n            backgroundColor: \'#E3E0EC\',\n            overflow: \'hidden\',\n          }}\n        >\n          <View\n            style={{\n              width: `${ratio * 100}%`,\n              height: \'100%\',\n              borderRadius: 999,\n              backgroundColor: \'#6B62C7\',\n            }}\n          />\n        </View>\n\n        <View style={{ flexDirection: \'row\', gap: 8 }}>\n          <View\n            style={{\n              flex: 1,\n              borderRadius: 15,\n              backgroundColor: \'#FFFFFF\',\n              padding: 10,\n            }}\n          >\n            <Text style={{ color: \'#8B8C94\', fontSize: 9, fontWeight: 800 }}>\n              PAYCHECK\n            </Text>\n            <Text style={{ marginTop: 3, fontSize: 13, fontWeight: 900 }}>\n              {format(cycle.amount, \'financial\')}\n            </Text>\n          </View>\n          <View\n            style={{\n              flex: 1,\n              borderRadius: 15,\n              backgroundColor: \'#FFFFFF\',\n              padding: 10,\n            }}\n          >\n            <Text style={{ color: \'#8B8C94\', fontSize: 9, fontWeight: 800 }}>\n              SPENT\n            </Text>\n            <Text style={{ marginTop: 3, fontSize: 13, fontWeight: 900 }}>\n              {format(cycle.currentSpent, \'financial\')}\n            </Text>\n          </View>\n          <View\n            style={{\n              flex: 1,\n              borderRadius: 15,\n              backgroundColor: \'#EAF7F0\',\n              padding: 10,\n            }}\n          >\n            <Text style={{ color: \'#54806A\', fontSize: 9, fontWeight: 800 }}>\n              🐷 PIGGY BANK\n            </Text>\n            <Text style={{ marginTop: 3, fontSize: 13, fontWeight: 900 }}>\n              {format(cycle.piggyBank, \'financial\')}\n            </Text>\n          </View>\n        </View>\n\n        <Text style={{ color: \'#8B8C94\', fontSize: 10, lineHeight: 1.4 }}>\n          Expenses from this pay cycle reduce Available. When the next\n          paycheck starts, leftover from the completed cycle is automatically\n          counted in Piggy Bank.\n        </Text>\n      </View>\n\n      {showEditor && (\n        <RecurringIncomeEditor\n          amount={draftAmount}\n          date={draftDate}\n          interval={draftInterval}\n          autoSweep={draftSweep}\n          error={error}\n          onAmount={setDraftAmount}\n          onDate={setDraftDate}\n          onInterval={setDraftInterval}\n          onSweep={setDraftSweep}\n          onCancel={() => setShowEditor(false)}\n          onSave={save}\n        />\n      )}\n    </>\n  );\n}\n\nfunction RecurringIncomeEditor({\n  amount,\n  date,\n  interval,\n  autoSweep,\n  error,\n  onAmount,\n  onDate,\n  onInterval,\n  onSweep,\n  onCancel,\n  onSave,\n}: {\n  amount: string;\n  date: string;\n  interval: number;\n  autoSweep: boolean;\n  error: string;\n  onAmount: (value: string) => void;\n  onDate: (value: string) => void;\n  onInterval: (value: number) => void;\n  onSweep: (value: boolean) => void;\n  onCancel: () => void;\n  onSave: () => void;\n}) {\n  return (\n    <View\n      style={{\n        position: \'fixed\',\n        inset: 0,\n        zIndex: 300,\n        backgroundColor: \'rgba(20, 20, 30, 0.38)\',\n        padding:\n          \'calc(env(safe-area-inset-top) + 18px) 18px calc(env(safe-area-inset-bottom) + 18px)\',\n        alignItems: \'center\',\n        justifyContent: \'center\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 430,\n          flexShrink: 0,\n          borderRadius: 24,\n          backgroundColor: \'#FFFFFF\',\n          padding: 18,\n          gap: 14,\n          boxShadow: \'0 24px 64px rgba(0,0,0,0.20)\',\n        }}\n      >\n        <Text style={{ fontSize: 20, fontWeight: 950 }}>\n          Recurring Income\n        </Text>\n        <Text style={{ color: \'#777983\', fontSize: 11, lineHeight: 1.45 }}>\n          Example: $2,000 every two weeks. Spending is deducted from the\n          current paycheck; leftover from completed cycles rolls into Piggy\n          Bank.\n        </Text>\n\n        <label style={{ display: \'grid\', gap: 5 }}>\n          <span style={{ fontSize: 11, fontWeight: 800 }}>Paycheck amount</span>\n          <input\n            inputMode="decimal"\n            value={amount}\n            onChange={event => onAmount(event.target.value)}\n            style={{\n              minHeight: 48,\n              border: \'1px solid #DEDEE5\',\n              borderRadius: 14,\n              padding: \'0 12px\',\n              fontSize: 18,\n              fontWeight: 850,\n            }}\n          />\n        </label>\n\n        <label style={{ display: \'grid\', gap: 5 }}>\n          <span style={{ fontSize: 11, fontWeight: 800 }}>\n            A payday to start from\n          </span>\n          <input\n            type="date"\n            value={date}\n            onChange={event => onDate(event.target.value)}\n            style={{\n              minHeight: 48,\n              border: \'1px solid #DEDEE5\',\n              borderRadius: 14,\n              padding: \'0 12px\',\n              fontSize: 15,\n              fontWeight: 750,\n            }}\n          />\n        </label>\n\n        <label style={{ display: \'grid\', gap: 5 }}>\n          <span style={{ fontSize: 11, fontWeight: 800 }}>Frequency</span>\n          <select\n            value={interval}\n            onChange={event => onInterval(Number(event.target.value))}\n            style={{\n              minHeight: 48,\n              border: \'1px solid #DEDEE5\',\n              borderRadius: 14,\n              padding: \'0 12px\',\n              background: \'#FFFFFF\',\n              fontSize: 15,\n              fontWeight: 750,\n            }}\n          >\n            <option value={7}>Every week</option>\n            <option value={14}>Every 2 weeks</option>\n            <option value={28}>Every 4 weeks</option>\n          </select>\n        </label>\n\n        <label\n          style={{\n            minHeight: 48,\n            display: \'flex\',\n            alignItems: \'center\',\n            justifyContent: \'space-between\',\n            gap: 12,\n            borderRadius: 14,\n            background: \'#F7F7F9\',\n            padding: \'0 12px\',\n          }}\n        >\n          <span style={{ fontSize: 12, fontWeight: 800 }}>\n            Auto sweep leftover to Piggy Bank\n          </span>\n          <input\n            type="checkbox"\n            checked={autoSweep}\n            onChange={event => onSweep(event.target.checked)}\n            style={{ width: 22, height: 22 }}\n          />\n        </label>\n\n        {error && (\n          <Text style={{ color: \'#C93645\', fontSize: 11, fontWeight: 800 }}>\n            {error}\n          </Text>\n        )}\n\n        <View style={{ flexDirection: \'row\', gap: 9 }}>\n          <button\n            type="button"\n            onClick={onCancel}\n            style={{\n              flex: 1,\n              minHeight: 46,\n              border: \'1px solid #E1E1E7\',\n              borderRadius: 14,\n              background: \'#FFFFFF\',\n              fontWeight: 850,\n            }}\n          >\n            Cancel\n          </button>\n          <button\n            type="button"\n            onClick={onSave}\n            style={{\n              flex: 1,\n              minHeight: 46,\n              border: 0,\n              borderRadius: 14,\n              background: \'#4D4B91\',\n              color: \'#FFFFFF\',\n              fontWeight: 900,\n            }}\n          >\n            Save\n          </button>\n        </View>\n\n        <Text\n          style={{\n            color: \'#999AA1\',\n            textAlign: \'center\',\n            fontSize: 9.5,\n            lineHeight: 1.4,\n          }}\n        >\n          Piggy Bank is a Budget Local tracking bucket. This does not move\n          money at your bank.\n        </Text>\n      </View>\n    </View>\n  );\n}\n'
BUDGET_LOCAL_ACCOUNTS_TSX = 'import React, { useCallback } from \'react\';\n\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport type { AccountEntity } from \'@actual-app/core/types/models\';\n\nimport { useAccounts } from \'#hooks/useAccounts\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useNavigate } from \'#hooks/useNavigate\';\nimport { useSheetValue } from \'#hooks/useSheetValue\';\nimport { replaceModal } from \'#modals/modalsSlice\';\nimport { useDispatch } from \'#redux\';\nimport * as bindings from \'#spreadsheet/bindings\';\n\nfunction AccountCard({ account }: { account: AccountEntity }) {\n  const format = useFormat();\n  const navigate = useNavigate();\n  const balance =\n    useSheetValue<\'account\', \'balance\'>(\n      bindings.accountBalance(account.id),\n    ) ?? 0;\n\n  return (\n    <button\n      type="button"\n      onClick={() => void navigate(`/accounts/${account.id}`)}\n      style={{\n        width: \'100%\',\n        minHeight: 82,\n        border: 0,\n        borderRadius: 20,\n        background: \'#FFFFFF\',\n        boxShadow: \'0 7px 22px rgba(42, 42, 60, 0.06)\',\n        padding: \'13px 15px\',\n        display: \'flex\',\n        alignItems: \'center\',\n        gap: 12,\n        color: \'#111116\',\n        textAlign: \'left\',\n        fontFamily: \'inherit\',\n      }}\n    >\n      <span\n        aria-hidden\n        style={{\n          width: 44,\n          height: 44,\n          flexShrink: 0,\n          borderRadius: 15,\n          display: \'flex\',\n          alignItems: \'center\',\n          justifyContent: \'center\',\n          background: account.offbudget ? \'#F2ECFF\' : \'#E8F5FF\',\n          fontSize: 22,\n        }}\n      >\n        {account.offbudget ? \'💰\' : \'💳\'}\n      </span>\n\n      <span style={{ flex: 1, minWidth: 0 }}>\n        <span\n          style={{\n            display: \'block\',\n            fontSize: 15,\n            fontWeight: 900,\n            overflow: \'hidden\',\n            textOverflow: \'ellipsis\',\n            whiteSpace: \'nowrap\',\n          }}\n        >\n          {account.name}\n        </span>\n        <span\n          style={{\n            display: \'block\',\n            marginTop: 4,\n            color: \'#9798A0\',\n            fontSize: 10,\n            fontWeight: 700,\n          }}\n        >\n          {account.offbudget ? \'Off budget\' : \'On budget\'}\n          {account.bank ? \' · Connected\' : \'\'}\n        </span>\n      </span>\n\n      <span\n        style={{\n          borderRadius: 999,\n          background: balance < 0 ? \'#FFF0F1\' : \'#F5F5F6\',\n          color: balance < 0 ? \'#C93645\' : \'#111116\',\n          padding: \'8px 11px\',\n          fontSize: 14,\n          fontWeight: 900,\n          whiteSpace: \'nowrap\',\n        }}\n      >\n        {format(balance, \'financial\')}\n      </span>\n    </button>\n  );\n}\n\nexport function BudgetLocalAccounts() {\n  const format = useFormat();\n  const dispatch = useDispatch();\n  const navigate = useNavigate();\n  const { data: accounts = [] } = useAccounts();\n\n  const total =\n    useSheetValue<\'account\', \'accounts-balance\'>(\n      bindings.allAccountBalance(),\n    ) ?? 0;\n  const onBudget =\n    useSheetValue<\'account\', \'onbudget-accounts-balance\'>(\n      bindings.onBudgetAccountBalance(),\n    ) ?? 0;\n  const offBudget =\n    useSheetValue<\'account\', \'offbudget-accounts-balance\'>(\n      bindings.offBudgetAccountBalance(),\n    ) ?? 0;\n\n  const activeAccounts = accounts.filter(account => !account.closed);\n\n  const onAddAccount = useCallback(() => {\n    dispatch(replaceModal({ modal: { name: \'add-account\', options: {} } }));\n  }, [dispatch]);\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        flexShrink: 0,\n        backgroundColor: \'#F8F8FA\',\n        color: \'#111116\',\n        paddingTop: 20,\n        paddingLeft: 14,\n        paddingRight: 14,\n        paddingBottom: \'calc(env(safe-area-inset-bottom) + 210px)\',\n        boxSizing: \'border-box\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          flexShrink: 0,\n          gap: 22,\n        }}\n      >\n        <View\n          style={{\n            minHeight: 58,\n            flexShrink: 0,\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            justifyContent: \'space-between\',\n          }}\n        >\n          <View>\n            <Text style={{ fontSize: 24, fontWeight: 950 }}>\n              Accounts\n            </Text>\n            <Text\n              style={{\n                marginTop: 2,\n                color: \'#8B8C94\',\n                fontSize: 11,\n                fontWeight: 700,\n              }}\n            >\n              Your money by account\n            </Text>\n          </View>\n\n          <button\n            type="button"\n            onClick={onAddAccount}\n            aria-label="Add account"\n            style={{\n              width: 44,\n              height: 44,\n              border: 0,\n              borderRadius: 15,\n              background: \'#F0EDFF\',\n              color: \'#4D4B91\',\n              fontSize: 25,\n              fontWeight: 800,\n            }}\n          >\n            +\n          </button>\n        </View>\n\n        <View\n          style={{\n            flexShrink: 0,\n            borderRadius: 24,\n            backgroundColor: \'#FFFFFF\',\n            padding: 18,\n            gap: 15,\n            boxShadow: \'0 10px 30px rgba(42, 42, 60, 0.07)\',\n          }}\n        >\n          <Text\n            style={{\n              color: \'#90919A\',\n              fontSize: 11,\n              fontWeight: 850,\n            }}\n          >\n            TOTAL BALANCE\n          </Text>\n          <Text\n            style={{\n              fontSize: 34,\n              lineHeight: 1.1,\n              fontWeight: 950,\n              color: total < 0 ? \'#C93645\' : \'#111116\',\n            }}\n          >\n            {format(total, \'financial\')}\n          </Text>\n\n          <View style={{ flexDirection: \'row\', gap: 9 }}>\n            <View\n              style={{\n                flex: 1,\n                borderRadius: 15,\n                backgroundColor: \'#F1FAF7\',\n                padding: 11,\n              }}\n            >\n              <Text style={{ color: \'#638276\', fontSize: 9, fontWeight: 850 }}>\n                ON BUDGET\n              </Text>\n              <Text style={{ marginTop: 3, fontSize: 14, fontWeight: 900 }}>\n                {format(onBudget, \'financial\')}\n              </Text>\n            </View>\n\n            <View\n              style={{\n                flex: 1,\n                borderRadius: 15,\n                backgroundColor: \'#F7F5FF\',\n                padding: 11,\n              }}\n            >\n              <Text style={{ color: \'#6D6798\', fontSize: 9, fontWeight: 850 }}>\n                OFF BUDGET\n              </Text>\n              <Text style={{ marginTop: 3, fontSize: 14, fontWeight: 900 }}>\n                {format(offBudget, \'financial\')}\n              </Text>\n            </View>\n          </View>\n\n          <button\n            type="button"\n            onClick={() => void navigate(\'/accounts/all\')}\n            style={{\n              minHeight: 42,\n              border: 0,\n              borderRadius: 13,\n              background: \'#F4F4F6\',\n              color: \'#4D4B91\',\n              fontSize: 12,\n              fontWeight: 850,\n            }}\n          >\n            View all transactions\n          </button>\n        </View>\n\n        <View style={{ flexShrink: 0, gap: 14 }}>\n          {activeAccounts.map(account => (\n            <AccountCard key={account.id} account={account} />\n          ))}\n\n          {activeAccounts.length === 0 && (\n            <View\n              style={{\n                borderRadius: 20,\n                backgroundColor: \'#FFFFFF\',\n                padding: 20,\n                alignItems: \'center\',\n                gap: 8,\n              }}\n            >\n              <Text style={{ fontSize: 24 }}>🐷</Text>\n              <Text style={{ fontSize: 14, fontWeight: 850 }}>\n                No accounts yet\n              </Text>\n              <Text\n                style={{\n                  color: \'#8B8C94\',\n                  textAlign: \'center\',\n                  fontSize: 11,\n                }}\n              >\n                Add your first account to start tracking balances.\n              </Text>\n            </View>\n          )}\n        </View>\n\n        <View\n          aria-hidden\n          style={{\n            height: 210,\n            flexShrink: 0,\n            pointerEvents: \'none\',\n          }}\n        />\n      </View>\n    </View>\n  );\n}\n'
BUDGET_LOCAL_TRANSACTIONS_TSX = 'import React, { useMemo, useState } from \'react\';\n\nimport {\n  SvgCheveronLeft,\n  SvgCheveronRight,\n} from \'@actual-app/components/icons/v1\';\nimport { Text } from \'@actual-app/components/text\';\nimport { View } from \'@actual-app/components/view\';\nimport * as monthUtils from \'@actual-app/core/shared/months\';\nimport { q } from \'@actual-app/core/shared/query\';\n\nimport { useAccounts } from \'#hooks/useAccounts\';\nimport { useCategories } from \'#hooks/useCategories\';\nimport { useFormat } from \'#hooks/useFormat\';\nimport { useLocale } from \'#hooks/useLocale\';\nimport { useNavigate } from \'#hooks/useNavigate\';\nimport { usePayees } from \'#hooks/usePayees\';\nimport { useTransactions } from \'#hooks/useTransactions\';\n\nfunction displayDate(value: string) {\n  return new Date(`${value}T12:00:00`).toLocaleDateString(undefined, {\n    month: \'short\',\n    day: \'numeric\',\n  });\n}\n\nexport function BudgetLocalTransactions() {\n  const format = useFormat();\n  const locale = useLocale();\n  const navigate = useNavigate();\n  const [month, setMonth] = useState(() => monthUtils.currentMonth());\n\n  const { data: accounts = [] } = useAccounts();\n  const { data: categoryData } = useCategories();\n  const categories = categoryData?.list ?? [];\n  const { data: payees = [] } = usePayees();\n\n  const accountById = useMemo(\n    () => new Map(accounts.map(account => [account.id, account])),\n    [accounts],\n  );\n  const categoryById = useMemo(\n    () => new Map(categories.map(category => [category.id, category])),\n    [categories],\n  );\n  const payeeById = useMemo(\n    () => new Map(payees.map(payee => [payee.id, payee])),\n    [payees],\n  );\n\n  const transactionQuery = useMemo(\n    () =>\n      q(\'transactions\')\n        .options({ splits: \'all\' })\n        .filter({\n          date: { $transform: \'$month\', $eq: month },\n        })\n        .orderBy({ date: \'desc\' })\n        .select(\'*\'),\n    [month],\n  );\n\n  const { transactions, isPending } = useTransactions({\n    query: transactionQuery,\n    options: { pageSize: 10000 },\n  });\n\n  const visibleTransactions = useMemo(\n    () =>\n      transactions.filter(\n        transaction =>\n          !transaction.tombstone &&\n          !transaction.is_child &&\n          !transaction.is_parent,\n      ),\n    [transactions],\n  );\n\n  const totals = useMemo(() => {\n    let expenses = 0;\n    let income = 0;\n\n    for (const transaction of visibleTransactions) {\n      const category = transaction.category\n        ? categoryById.get(transaction.category)\n        : undefined;\n\n      if (category) {\n        if (category.is_income) {\n          income += Math.max(0, transaction.amount);\n        } else {\n          expenses += -transaction.amount;\n        }\n      } else if (transaction.amount > 0) {\n        income += transaction.amount;\n      } else {\n        expenses += -transaction.amount;\n      }\n    }\n\n    return {\n      expenses: Math.max(0, expenses),\n      income: Math.max(0, income),\n    };\n  }, [categoryById, visibleTransactions]);\n\n  const currentMonth = monthUtils.currentMonth();\n  const monthLabel =\n    month === currentMonth\n      ? \'This Month\'\n      : monthUtils.format(month, "MMMM \'\'yy", locale);\n\n  return (\n    <View\n      style={{\n        minHeight: \'100%\',\n        width: \'100%\',\n        flexShrink: 0,\n        backgroundColor: \'#F8F8FA\',\n        color: \'#111116\',\n        paddingTop: 18,\n        paddingLeft: 14,\n        paddingRight: 14,\n        paddingBottom: \'calc(env(safe-area-inset-bottom) + 230px)\',\n        boxSizing: \'border-box\',\n      }}\n    >\n      <View\n        style={{\n          width: \'100%\',\n          maxWidth: 760,\n          alignSelf: \'center\',\n          flexShrink: 0,\n          gap: 20,\n        }}\n      >\n        <View\n          style={{\n            minHeight: 58,\n            flexShrink: 0,\n            flexDirection: \'row\',\n            alignItems: \'center\',\n            justifyContent: \'center\',\n            gap: 8,\n          }}\n        >\n          <button\n            type="button"\n            aria-label="Previous month"\n            onClick={() =>\n              setMonth(value => monthUtils.addMonths(value, -1))\n            }\n            style={{\n              border: 0,\n              background: \'transparent\',\n              color: \'#4D4B91\',\n              padding: 7,\n            }}\n          >\n            <SvgCheveronLeft width={22} height={22} />\n          </button>\n\n          <Text\n            style={{\n              minWidth: 150,\n              textAlign: \'center\',\n              fontSize: 23,\n              fontWeight: 950,\n            }}\n          >\n            {monthLabel}\n          </Text>\n\n          <button\n            type="button"\n            aria-label="Next month"\n            onClick={() =>\n              setMonth(value => monthUtils.addMonths(value, 1))\n            }\n            style={{\n              border: 0,\n              background: \'transparent\',\n              color: \'#4D4B91\',\n              padding: 7,\n            }}\n          >\n            <SvgCheveronRight width={22} height={22} />\n          </button>\n        </View>\n\n        <View\n          style={{\n            flexShrink: 0,\n            flexDirection: \'row\',\n            gap: 10,\n          }}\n        >\n          <View\n            style={{\n              flex: 1,\n              borderRadius: 18,\n              backgroundColor: \'#FFF2D5\',\n              padding: 14,\n            }}\n          >\n            <Text style={{ color: \'#8C7650\', fontSize: 10, fontWeight: 850 }}>\n              EXPENSES\n            </Text>\n            <Text style={{ marginTop: 4, fontSize: 20, fontWeight: 950 }}>\n              {isPending ? \'…\' : format(totals.expenses, \'financial\')}\n            </Text>\n          </View>\n\n          <View\n            style={{\n              flex: 1,\n              borderRadius: 18,\n              backgroundColor: \'#DDF7EF\',\n              padding: 14,\n            }}\n          >\n            <Text style={{ color: \'#5F8676\', fontSize: 10, fontWeight: 850 }}>\n              INCOME\n            </Text>\n            <Text style={{ marginTop: 4, fontSize: 20, fontWeight: 950 }}>\n              {isPending ? \'…\' : format(totals.income, \'financial\')}\n            </Text>\n          </View>\n        </View>\n\n        <View style={{ flexShrink: 0, gap: 12 }}>\n          {visibleTransactions.map(transaction => {\n            const category = transaction.category\n              ? categoryById.get(transaction.category)\n              : undefined;\n            const account = transaction.account\n              ? accountById.get(transaction.account)\n              : undefined;\n            const payee = transaction.payee\n              ? payeeById.get(transaction.payee)\n              : undefined;\n            const positive = transaction.amount > 0;\n\n            return (\n              <button\n                key={transaction.id}\n                type="button"\n                onClick={() =>\n                  void navigate(`/transactions/${transaction.id}`)\n                }\n                style={{\n                  width: \'100%\',\n                  minHeight: 78,\n                  flexShrink: 0,\n                  scrollMarginBottom: 170,\n                  border: 0,\n                  borderRadius: 20,\n                  background: \'#FFFFFF\',\n                  boxShadow: \'0 7px 20px rgba(42, 42, 60, 0.055)\',\n                  padding: \'12px 14px\',\n                  display: \'flex\',\n                  alignItems: \'center\',\n                  gap: 11,\n                  color: \'#111116\',\n                  textAlign: \'left\',\n                  fontFamily: \'inherit\',\n                }}\n              >\n                <span\n                  aria-hidden\n                  style={{\n                    width: 42,\n                    height: 42,\n                    flexShrink: 0,\n                    borderRadius: 14,\n                    display: \'flex\',\n                    alignItems: \'center\',\n                    justifyContent: \'center\',\n                    background: positive ? \'#E8F7F0\' : \'#F3F1FA\',\n                    fontSize: 19,\n                  }}\n                >\n                  {positive ? \'↙\' : \'↗\'}\n                </span>\n\n                <span style={{ flex: 1, minWidth: 0 }}>\n                  <span\n                    style={{\n                      display: \'block\',\n                      fontSize: 14,\n                      fontWeight: 900,\n                      overflow: \'hidden\',\n                      textOverflow: \'ellipsis\',\n                      whiteSpace: \'nowrap\',\n                    }}\n                  >\n                    {payee?.name ||\n                      category?.name ||\n                      (positive ? \'Income\' : \'Transaction\')}\n                  </span>\n                  <span\n                    style={{\n                      display: \'block\',\n                      marginTop: 4,\n                      color: \'#91929A\',\n                      fontSize: 10,\n                      fontWeight: 700,\n                      overflow: \'hidden\',\n                      textOverflow: \'ellipsis\',\n                      whiteSpace: \'nowrap\',\n                    }}\n                  >\n                    {displayDate(transaction.date)}\n                    {category?.name ? ` · ${category.name}` : \'\'}\n                    {account?.name ? ` · ${account.name}` : \'\'}\n                  </span>\n                </span>\n\n                <span\n                  style={{\n                    color: positive ? \'#287B55\' : \'#111116\',\n                    fontSize: 14,\n                    fontWeight: 950,\n                    whiteSpace: \'nowrap\',\n                  }}\n                >\n                  {positive ? \'+\' : \'\'}\n                  {format(transaction.amount, \'financial\')}\n                </span>\n              </button>\n            );\n          })}\n\n          {!isPending && visibleTransactions.length === 0 && (\n            <View\n              style={{\n                borderRadius: 20,\n                backgroundColor: \'#FFFFFF\',\n                padding: 22,\n                alignItems: \'center\',\n                gap: 7,\n              }}\n            >\n              <Text style={{ fontSize: 24 }}>🧾</Text>\n              <Text style={{ fontSize: 14, fontWeight: 850 }}>\n                No transactions this month\n              </Text>\n            </View>\n          )}\n        </View>\n\n        <View\n          aria-hidden\n          style={{\n            height: 230,\n            flexShrink: 0,\n            pointerEvents: \'none\',\n          }}\n        />\n      </View>\n    </View>\n  );\n}\n'

def fail(message: str) -> None:
    raise SystemExit(f"ERROR: {message}")


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    # Apply the replacement whenever the original block is still present.
    # Only treat it as already patched when the original is gone and the
    # replacement exists. This matters when `new` is a substring of `old`.
    if old in text:
        path.write_text(text.replace(old, new, 1), encoding="utf-8")
        return
    if new in text:
        return
    fail(f"No encontré el bloque esperado para {label} en {path}")


def remove_once(path: Path, old: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    if old not in text:
        return
    path.write_text(text.replace(old, "", 1), encoding="utf-8")


def download(url: str, destination: Path, label: str) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    print(f"Descargando {label}...")
    request = urllib.request.Request(url, headers={"User-Agent": "Budget-Local-iPhone/0.3.30"})
    with urllib.request.urlopen(request, timeout=180) as response, destination.open("wb") as output:
        while True:
            chunk = response.read(1024 * 1024)
            if not chunk:
                break
            output.write(chunk)


def fetch_ocr(url: str, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists() and destination.stat().st_size > 1024:
        return
    download(url, destination, destination.name)
    if destination.stat().st_size < 1024:
        destination.unlink(missing_ok=True)
        fail(f"Descarga OCR inválida: {url}")


def validate_patch_literals() -> None:
    upstream_slot = "                  {isNarrowWidth && <MobilePageHeaderSlot />}\n"
    expected_slot = (
        "                  {isNarrowWidth &&\n"
        "                    location.pathname !== '/budget' &&\n"
        "                    location.pathname !== '/accounts' &&\n"
        "                    location.pathname !== '/accounts/all' && (\n"
        "                      <MobilePageHeaderSlot />\n"
        "                    )}\n"
    )
    upstream_scroll = (
        "                    position: 'relative',\n"
        "                  }}\n"
        "                >\n"
    )
    expected_scroll = (
        "                    position: 'relative',\n"
        "                    scrollPaddingBottom:\n"
        "                      isNarrowWidth && (\n"
        "                        location.pathname === '/budget' ||\n"
        "                        location.pathname === '/home' ||\n"
        "                        location.pathname === '/accounts' ||\n"
        "                        location.pathname === '/accounts/all'\n"
        "                      )\n"
        "                        ? 'calc(140px + env(safe-area-inset-bottom))'\n"
        "                        : undefined,\n"
        "                    paddingBottom:\n"
        "                      isNarrowWidth && (\n"
        "                        location.pathname === '/budget' ||\n"
        "                        location.pathname === '/home' ||\n"
        "                        location.pathname === '/accounts' ||\n"
        "                        location.pathname === '/accounts/all'\n"
        "                      )\n"
        "                        ? 'calc(130px + env(safe-area-inset-bottom))'\n"
        "                        : undefined,\n"
        "                    boxSizing: 'border-box',\n"
        "                  }}\n"
        "                >\n"
    )

    for label, value in (
        ("MobilePageHeaderSlot old", upstream_slot),
        ("MobilePageHeaderSlot new", expected_slot),
        ("clean mobile scroller old", upstream_scroll),
        ("clean mobile scroller new", expected_scroll),
    ):
        if "\\\\n" in value:
            fail(f"Hay un \\\\n literal en {label}.")

