def prepare_ocr(root: Path) -> None:
    public_ocr = root / "packages/desktop-client/public/ocr"
    for relative, url in OCR_FILES.items():
        fetch_ocr(url, public_ocr / relative)
    (public_ocr / "NOTICE.txt").write_text(
        "Budget Local - OCR local vendorizado\n\n"
        f"Tesseract.js {TESSERACT_JS} (Apache-2.0)\n"
        f"tesseract.js-core {TESSERACT_CORE} (Apache-2.0)\n"
        f"English traineddata package {LANG_DATA}\n\n"
        "Los archivos se sirven desde /ocr y el recibo se procesa en el navegador.\n"
        "No se requiere CDN ni API de OCR en tiempo de ejecución.\n",
        encoding="utf-8",
    )




def prepare_ai_runtime(root: Path) -> None:
    public_ai = root / "packages/desktop-client/public/ai"
    runtime = public_ai / AI_RUNTIME_FILENAME
    if not runtime.exists() or runtime.stat().st_size < 100_000:
        download(AI_RUNTIME_URL, runtime, f"Transformers.js {TRANSFORMERS_JS}")
    if runtime.stat().st_size < 100_000:
        runtime.unlink(missing_ok=True)
        fail("Descarga inválida de Transformers.js para Local AI.")

    (public_ai / "NOTICE.txt").write_text(
        "Budget Local - Local AI runtime\\n\\n"
        f"Transformers.js {TRANSFORMERS_JS} (Apache-2.0)\\n"
        f"ONNX Runtime Web {ONNXRUNTIME_WEB} (MIT)\\n"
        "Modelo: onnx-community/SmolLM2-135M-Instruct-ONNX\\n"
        "Configuración: WebGPU + q4f16.\\n\\n"
        "Transformers.js se sirve como Static Asset. Los archivos ONNX Runtime "
        "y Qwen se transmiten por rutas del mismo Budget Worker (/ort y /hf), "
        "eliminando cargas cross-origin desde Safari. El Worker transmite los "
        "bytes sin recibir el texto de tus gastos.\\n",
        encoding="utf-8",
    )


def ensure_upstream_core_integrity(root: Path) -> None:
    """Verify the Actual core utility module survived source ZIP extraction.

    Cloudflare occasionally produced a zero/invalid util.ts after extracting the
    GitHub source archive. TypeScript then reports TS2306 from dozens of files.
    Repair only that official upstream file and verify its expected exports.
    """

    util_path = root / "packages/loot-core/src/shared/util.ts"

    def is_valid(path: Path) -> bool:
        if not path.exists() or path.stat().st_size < 10_000:
            return False
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return False
        return (
            "export function amountToInteger" in text
            and "export function last" in text
            and "export " in text
        )

    if is_valid(util_path):
        print(f"Core util.ts verificado: {util_path.stat().st_size} bytes")
        return

    print("ADVERTENCIA: util.ts upstream inválido; restaurando copia oficial...")
    repair_path = util_path.with_name("util.ts.repair")
    repair_path.unlink(missing_ok=True)

    download(
        UPSTREAM_UTIL_URL,
        repair_path,
        f"Actual Budget {UPSTREAM_TAG} shared/util.ts",
    )

    if not is_valid(repair_path):
        repair_path.unlink(missing_ok=True)
        fail("No pude restaurar un util.ts upstream válido.")

    repair_path.replace(util_path)
    print(f"Core util.ts restaurado: {util_path.stat().st_size} bytes")


def restore_executable_bits(root: Path) -> None:
    """GitHub source ZIP extraction does not preserve Unix executable bits.

    Restore +x only for shebang scripts living in a bin directory. Actual's
    browser build executes ./bin/package-browser directly, so this is required
    on Linux/GitHub Actions after extracting the upstream ZIP.
    """
    restored = 0
    for path in root.rglob("*"):
        if not path.is_file() or "bin" not in path.parts:
            continue
        try:
            with path.open("rb") as handle:
                if handle.read(2) != b"#!":
                    continue
            path.chmod(path.stat().st_mode | 0o111)
            restored += 1
        except OSError:
            continue
    print(f"Permisos ejecutables restaurados: {restored}")


def create_project(destination: Path, archive: Path | None, force: bool) -> None:
    if destination.exists():
        if not force:
            fail(f"La carpeta ya existe: {destination}. Usa --force para reemplazarla.")
        shutil.rmtree(destination)

    with tempfile.TemporaryDirectory(prefix="budget-local-") as temp_dir:
        temp = Path(temp_dir)
        local_archive = temp / "actual.zip"
        if archive:
            shutil.copy2(archive, local_archive)
            print(f"Usando archivo local: {archive}")
        else:
            download(ARCHIVE_URL, local_archive, f"Actual Budget {UPSTREAM_TAG}")
        print("Extrayendo base oficial...")
        with zipfile.ZipFile(local_archive) as zf:
            zf.extractall(temp / "extract")
        extracted = next((temp / "extract").iterdir())
        shutil.move(str(extracted), str(destination))

    print("Restaurando permisos de scripts...")
    restore_executable_bits(destination)
    print("Verificando integridad de Actual Budget...")
    ensure_upstream_core_integrity(destination)
    print("Aplicando Budget Local...")
    apply_mod(destination)
    print("Preparando OCR local...")
    prepare_ocr(destination)
    print("Preparando runtime de IA local...")
    prepare_ai_runtime(destination)
    print(f"OK: proyecto listo en {destination}")


def main() -> None:
    validate_patch_literals()
    parser = argparse.ArgumentParser(description="Crea Budget Local sobre Actual Budget desde un solo archivo")
    parser.add_argument("--dest", default="actual-budget-local", help="Carpeta destino")
    parser.add_argument("--force", action="store_true", help="Reemplaza la carpeta destino")
    parser.add_argument("--archive", help="ZIP local de Actual Budget v26.10.0 para pruebas sin red")
    args = parser.parse_args()
    archive = Path(args.archive).resolve() if args.archive else None
    if archive and not archive.exists():
        fail(f"No existe el archivo: {archive}")
    create_project(Path(args.dest).resolve(), archive, args.force)


if __name__ == "__main__":
    main()
